import type { Context, Next } from 'hono';
import type { Env } from '../types';

interface RateLimitOptions {
  windowMs?: number; // Janela em ms
  max?: number; // Máximo de requisições na janela
  keyGenerator?: (c: Context<{ Bindings: Env }>) => string;
}

// Estrutura em memória (reinicia no deploy do worker)
const buckets = new Map<string, { count: number; resetAt: number }>();

export function rateLimit(opts: RateLimitOptions = {}) {
  const windowMs = opts.windowMs ?? 60000; // 1 min
  const max = opts.max ?? 30;
  const keyGen = opts.keyGenerator ?? ((c) => {
    const ip = c.req.header('CF-Connecting-IP') || 'unknown';
    return `ip:${ip}`;
  });

  return async (c: Context<{ Bindings: Env }>, next: Next) => {
    const key = keyGen(c);
    const now = Date.now();
    let bucket = buckets.get(key);

    if (!bucket || bucket.resetAt < now) {
      bucket = { count: 0, resetAt: now + windowMs };
      buckets.set(key, bucket);
    }

    bucket.count += 1;

    if (bucket.count > max) {
      const retrySec = Math.ceil((bucket.resetAt - now) / 1000);
      return c.json(
        {
          success: false,
          error: 'Rate limit excedido',
          meta: { retry_after_seconds: retrySec },
        },
        429,
      );
    }

    // Headers informativos
    c.header('X-RateLimit-Limit', String(max));
    c.header('X-RateLimit-Remaining', String(Math.max(0, max - bucket.count)));
    c.header('X-RateLimit-Reset', String(Math.floor(bucket.resetAt / 1000)));

    await next();
  };
}
