/**
 * EXPORTAÇÃO DE DADOS PARA EXCEL
 *
 * Endpoints:
 * - GET /api/exportacao/funcionarios - Exporta todos os funcionários
 * - GET /api/exportacao/qualificacoes-historico - Exporta histórico de qualificações
 * - GET /api/exportacao/qualificacoes-tipos - Exporta tipos de qualificações
 */

import { Hono } from 'hono';
import type { Env } from '../types';
import { auth } from '../middleware/auth';
import ExcelJS from 'exceljs';

const app = new Hono<{ Bindings: Env }>();

/**
 * GET /api/exportacao/funcionarios
 * Exporta todos os funcionários em formato XLSX
 */
app.get('/funcionarios', auth(), async (c) => {
  try {
    const db = c.env.DB;

    const funcionarios = await db
      .prepare(
        `SELECT 
          f.id,
          f.nome,
          f.matricula,
          f.cpf,
          f.email,
          f.telefone,
          f.nascimento,
          f.admissao,
          f.cargo,
          f.funcao,
          COALESCE(ma.modelo, ma.codigo, ma.nome) as aeronave,
          f.codigo_anac,
          f.licenca,
          f.is_instrutor,
          COALESCE(f.is_examinador, f.is_checador, 0) as is_examinador,
          COALESCE(f.ativo, CASE WHEN UPPER(COALESCE(f.status, 'ATIVO')) = 'ATIVO' THEN 1 ELSE 0 END, 1) as ativo,
          f.created_at,
          f.updated_at
        FROM funcionarios f
        LEFT JOIN modelos_aeronave ma ON CAST(ma.id AS TEXT) = f.modelo_aeronave_id AND ma.deleted_at IS NULL
        WHERE f.deleted_at IS NULL
        ORDER BY f.nome`,
      )
      .all();

    if (!funcionarios.success) {
      return c.json({ success: false, error: 'Erro ao buscar funcionários' }, 500);
    }

    const rows = funcionarios.results || [];
    if (rows.length === 0) {
      return c.json({ success: false, error: 'Nenhum funcionário encontrado' }, 404);
    }

    // Criar workbook Excel
    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet('Funcionários');

    // Definir colunas
    worksheet.columns = [
      { header: 'ID', key: 'id', width: 10 },
      { header: 'Nome', key: 'nome', width: 30 },
      { header: 'Matrícula', key: 'matricula', width: 15 },
      { header: 'CPF', key: 'cpf', width: 15 },
      { header: 'Email', key: 'email', width: 30 },
      { header: 'Telefone', key: 'telefone', width: 15 },
      { header: 'Nascimento', key: 'nascimento', width: 12 },
      { header: 'Admissão', key: 'admissao', width: 12 },
      { header: 'Cargo', key: 'cargo', width: 20 },
      { header: 'Função', key: 'funcao', width: 20 },
      { header: 'Aeronave', key: 'aeronave', width: 15 },
      { header: 'Código ANAC', key: 'codigo_anac', width: 15 },
      { header: 'Licença', key: 'licenca', width: 15 },
      { header: 'Instrutor', key: 'is_instrutor', width: 10 },
      { header: 'Examinador', key: 'is_examinador', width: 12 },
      { header: 'Ativo', key: 'ativo', width: 10 },
      { header: 'Criado em', key: 'created_at', width: 20 },
      { header: 'Atualizado em', key: 'updated_at', width: 20 },
    ];

    // Estilizar cabeçalho
    worksheet.getRow(1).font = { bold: true };
    worksheet.getRow(1).fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FFE0E0E0' },
    };

    // Adicionar dados
    for (const row of rows as any[]) {
      worksheet.addRow({
        id: row.id || '',
        nome: row.nome || '',
        matricula: row.matricula || '',
        cpf: row.cpf || '',
        email: row.email || '',
        telefone: row.telefone || '',
        nascimento: row.nascimento || '',
        admissao: row.admissao || '',
        cargo: row.cargo || '',
        funcao: row.funcao || '',
        aeronave: row.aeronave || '',
        codigo_anac: row.codigo_anac || '',
        licenca: row.licenca || '',
        is_instrutor: row.is_instrutor ? 'Sim' : 'Não',
        is_examinador: row.is_examinador ? 'Sim' : 'Não',
        ativo: row.ativo ? 'Sim' : 'Não',
        created_at: row.created_at || '',
        updated_at: row.updated_at || '',
      });
    }

    // Gerar buffer
    const buffer = await workbook.xlsx.writeBuffer();
    const timestamp = new Date().toISOString().split('T')[0];

    return new Response(buffer, {
      headers: {
        'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'Content-Disposition': `attachment; filename="funcionarios_${timestamp}.xlsx"`,
        'Access-Control-Allow-Origin': '*',
      },
    });
  } catch (error: any) {
    console.error('[EXPORTACAO] Erro ao exportar funcionários:', error);
    return c.json({ success: false, error: error.message }, 500);
  }
});

/**
 * GET /api/exportacao/qualificacoes-historico
 * Exporta histórico de qualificações em formato XLSX
 */
app.get('/qualificacoes-historico', auth(), async (c) => {
  try {
    const db = c.env.DB;

    const historico = await db
      .prepare(
        `SELECT 
          h.id,
          f.nome as funcionario_nome,
          f.matricula as funcionario_matricula,
          h.qualificacao_codigo,
          h.tipo_codigo,
          h.categoria,
          h.data_conclusao,
          h.data_vencimento,
          h.validade_meses,
          h.numero_certificado,
          h.instrutor,
          h.local,
          h.modalidade,
          h.nota,
          h.carga_horaria,
          h.observacoes,
          h.status,
          h.created_at
        FROM qualificacoes_historico h
        LEFT JOIN funcionarios f ON h.funcionario_id = f.id
        WHERE h.deleted_at IS NULL
        ORDER BY h.created_at DESC`,
      )
      .all();

    if (!historico.success) {
      return c.json({ success: false, error: 'Erro ao buscar histórico' }, 500);
    }

    const rows = historico.results || [];
    if (rows.length === 0) {
      return c.json({ success: false, error: 'Nenhum histórico encontrado' }, 404);
    }

    // Criar workbook Excel
    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet('Histórico Qualificações');

    // Definir colunas
    worksheet.columns = [
      { header: 'ID', key: 'id', width: 10 },
      { header: 'Funcionário', key: 'funcionario_nome', width: 30 },
      { header: 'Matrícula', key: 'funcionario_matricula', width: 15 },
      { header: 'Código', key: 'qualificacao_codigo', width: 15 },
      { header: 'Tipo', key: 'tipo_codigo', width: 15 },
      { header: 'Categoria', key: 'categoria', width: 15 },
      { header: 'Data Conclusão', key: 'data_conclusao', width: 15 },
      { header: 'Data Vencimento', key: 'data_vencimento', width: 15 },
      { header: 'Validade (meses)', key: 'validade_meses', width: 15 },
      { header: 'Nº Certificado', key: 'numero_certificado', width: 20 },
      { header: 'Instrutor', key: 'instrutor', width: 25 },
      { header: 'Local', key: 'local', width: 20 },
      { header: 'Modalidade', key: 'modalidade', width: 15 },
      { header: 'Nota', key: 'nota', width: 10 },
      { header: 'Carga Horária', key: 'carga_horaria', width: 15 },
      { header: 'Observações', key: 'observacoes', width: 30 },
      { header: 'Status', key: 'status', width: 15 },
      { header: 'Criado em', key: 'created_at', width: 20 },
    ];

    // Estilizar cabeçalho
    worksheet.getRow(1).font = { bold: true };
    worksheet.getRow(1).fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FFE0E0E0' },
    };

    // Adicionar dados
    for (const row of rows as any[]) {
      worksheet.addRow({
        id: row.id || '',
        funcionario_nome: row.funcionario_nome || '',
        funcionario_matricula: row.funcionario_matricula || '',
        qualificacao_codigo: row.qualificacao_codigo || '',
        tipo_codigo: row.tipo_codigo || '',
        categoria: row.categoria || '',
        data_conclusao: row.data_conclusao || '',
        data_vencimento: row.data_vencimento || '',
        validade_meses: row.validade_meses || '',
        numero_certificado: row.numero_certificado || '',
        instrutor: row.instrutor || '',
        local: row.local || '',
        modalidade: row.modalidade || '',
        nota: row.nota || '',
        carga_horaria: row.carga_horaria || '',
        observacoes: row.observacoes || '',
        status: row.status || '',
        created_at: row.created_at || '',
      });
    }

    // Gerar buffer
    const buffer = await workbook.xlsx.writeBuffer();
    const timestamp = new Date().toISOString().split('T')[0];

    return new Response(buffer, {
      headers: {
        'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'Content-Disposition': `attachment; filename="qualificacoes_historico_${timestamp}.xlsx"`,
        'Access-Control-Allow-Origin': '*',
      },
    });
  } catch (error: any) {
    console.error('[EXPORTACAO] Erro ao exportar histórico:', error);
    return c.json({ success: false, error: error.message }, 500);
  }
});

/**
 * GET /api/exportacao/qualificacoes-tipos
 * Exporta tipos de qualificações em formato XLSX
 */
