function timeToMinutes(h: unknown): number | null {
  if (typeof h !== 'string') return null;
  if (h.length < 5) return null;
  const hh = Number(h.slice(0, 2));
  const mm = Number(h.slice(3, 5));
  if (!Number.isFinite(hh) || !Number.isFinite(mm)) return null;
  if (hh < 0 || hh > 23 || mm < 0 || mm > 59) return null;
  return hh * 60 + mm;
}

async function findSessaoConflict(
  db: D1Database,
  p: {
    simuladorId: number;
    data: string;
    inicioMin: number;
    fimMin: number;
    excludeId?: string | number;
  },
) {
  const baseWhere = `
    FROM simulador_agendamentos sa
    WHERE sa.deleted_at IS NULL
      AND sa.simulador_id = ?
      AND sa.data = ?
      AND sa.hora_inicio IS NOT NULL
      AND sa.hora_fim IS NOT NULL
  `;

  const minutesStartExpr = `(CAST(substr(sa.hora_inicio, 1, 2) AS INTEGER) * 60 + CAST(substr(sa.hora_inicio, 4, 2) AS INTEGER))`;
  const minutesEndExpr = `(CAST(substr(sa.hora_fim, 1, 2) AS INTEGER) * 60 + CAST(substr(sa.hora_fim, 4, 2) AS INTEGER))`;

  const overlapWhere = `
      AND ? < ${minutesEndExpr}
      AND ? > ${minutesStartExpr}
  `;

  if (p.excludeId !== undefined && p.excludeId !== null) {
    return await db
      .prepare(
        `SELECT sa.id, sa.hora_inicio, sa.hora_fim ${baseWhere} AND sa.id != ? ${overlapWhere} LIMIT 1`,
      )
      .bind(p.simuladorId, p.data, p.excludeId, p.inicioMin, p.fimMin)
      .first();
  }

  return await db
    .prepare(`SELECT sa.id, sa.hora_inicio, sa.hora_fim ${baseWhere} ${overlapWhere} LIMIT 1`)
    .bind(p.simuladorId, p.data, p.inicioMin, p.fimMin)
    .first();
}

async function audit(db: D1Database, p: any) {
  try {
    const e = await db
      .prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='auditoria_avancada_v2'")
      .first();
    if (!e) {
      await db
        .prepare(
          "CREATE TABLE IF NOT EXISTS auditoria_avancada_v2(id INTEGER PRIMARY KEY AUTOINCREMENT,tabela TEXT,acao TEXT,registro_id TEXT,dados_anteriores TEXT,dados_novos TEXT,created_at TEXT DEFAULT(datetime('now')))",
        )
        .run();
    }
    await db
      .prepare(
        'INSERT INTO auditoria_avancada_v2(tabela,acao,registro_id,dados_anteriores,dados_novos)VALUES(?,?,?,?,?)',
      )
      .bind(
        p.tabela,
        p.acao,
        String(p.registro_id),
        p.dados_anteriores ? JSON.stringify(p.dados_anteriores) : null,
        p.dados_novos ? JSON.stringify(p.dados_novos) : null,
      )
      .run();
  } catch (e) {
    console.error('audit:', e);
  }
}
