/**
 * GET /api/simuladores/fichas/:id
 * Buscar ficha completa com todos os dados para exibição
 * Retorna: sessão, tripulante, instrutor, simulador, 22 manobras, assinaturas
 */
app.get('/fichas/:id', async (c: Context) => {
  try {
    const id = c.req.param('id');

    // 1. Buscar ficha com JOINs para sessão, tripulante, instrutor, simulador e template
    const f = await c.env.DB.prepare(
      `SELECT 
        fs.id,
        fs.uuid,
        fs.agendamento_slot_id,
        fs.status,
        fs.aprovado,
        fs.nota_final,
        fs.resultado_final,
        fs.observacoes,
        fs.data_sessao,
        fs.assinatura_aluno_timestamp,
        fs.assinatura_instrutor_timestamp,
        fs.assinatura_aluno_ip,
        fs.assinatura_instrutor_ip,
        fs.colaborador_id_aluno,
        sa.tipo_sessao,
        sa.nome as sessao_nome,
        sa.data,
        sa.hora_inicio as horario_inicio,
        sa.hora_fim as horario_fim,
        sa.duracao_minutos,
        sa.is_check,
        sa.examinador_id,
        ft.id as tripulante_id,
        ft.nome as tripulante_nome,
        ft.matricula as tripulante_matricula,
        ft.codigo_anac as tripulante_codigo_anac,
        sp.funcao as tripulante_funcao,
        fi.id as instrutor_id,
        fi.nome as instrutor_nome,
        fi.matricula as instrutor_matricula,
        fi.codigo_anac as instrutor_codigo_anac,
        s.nome as simulador_nome,
        s.modelo as simulador_modelo,
        s.tipo as simulador_tipo,
        tpl.codigo as template_codigo,
        tpl.tema as template_tema,
        fex.nome as examinador_nome
      FROM fichas_sessao fs
      INNER JOIN simulador_agendamentos sa ON fs.agendamento_slot_id = sa.id AND sa.deleted_at IS NULL
      INNER JOIN funcionarios ft ON fs.colaborador_id_aluno = ft.id AND ft.deleted_at IS NULL
      INNER JOIN funcionarios fi ON fs.instrutor_id = fi.id AND fi.deleted_at IS NULL
      INNER JOIN simuladores s ON sa.simulador_id = s.id AND s.deleted_at IS NULL
      LEFT JOIN sessoes_participantes sp ON sp.sessao_id = sa.id 
        AND sp.funcionario_id = ft.id 
        AND sp.deleted_at IS NULL
      LEFT JOIN sessoes_template tpl ON fs.template_id = tpl.id
      LEFT JOIN funcionarios fex ON sa.examinador_id = fex.id AND fex.deleted_at IS NULL
      WHERE fs.id = ? AND fs.deleted_at IS NULL
      `,
    )
      .bind(id)
      .first();

    if (!f) return c.json({ success: false, error: 'Ficha não encontrada' }, 404);

    // 2. Buscar manobras da ficha (SEMPRE de fichas_sessao_manobras)
    let m = await c.env.DB.prepare(
      `SELECT 
        id,
        ordem,
        codigo,
        descricao,
        categoria,
        resultado,
        observacoes
      FROM fichas_sessao_manobras 
      WHERE ficha_id = ? AND deleted_at IS NULL 
      ORDER BY ordem ASC`,
    )
      .bind(id)
      .all();

    // 2.1 Se não houver manobras na ficha, popular automaticamente do modelo
    if (!m.results || m.results.length === 0) {
      console.log(`[AUTO-POPULATE] Ficha ${id} sem manobras, iniciando auto-população...`);

      // Buscar tipo_sessao e tipo_aeronave da ficha (com fallback para simulador do agendamento)
      const fichaCompleta = await c.env.DB.prepare(
        `SELECT 
           COALESCE(sa.tipo_sessao, fs.tipo_sessao) as tipo_sessao,
           COALESCE(aer.modelo, s.modelo, fs.tipo_aeronave) as tipo_aeronave
         FROM fichas_sessao fs 
         LEFT JOIN simulador_agendamentos sa ON fs.agendamento_slot_id = sa.id
         LEFT JOIN simuladores s ON sa.simulador_id = s.id
         LEFT JOIN aeronaves aer ON fs.tipo_aeronave = aer.id
         WHERE fs.id = ?`,
      )
        .bind(id)
        .first();

      console.log(`[AUTO-POPULATE] fichaCompleta:`, fichaCompleta);

      if (fichaCompleta) {
        // Buscar modelo de sessão correspondente ao tipo_sessao e tipo_aeronave
        const modelo = await c.env.DB.prepare(
          `SELECT ms.id 
           FROM modelos_sessao ms
           INNER JOIN tipos_sessao ts ON ms.tipo_sessao_id = ts.id
           WHERE ts.codigo = ?
             AND ms.modelo_aeronave = ?
             AND ms.deleted_at IS NULL
           LIMIT 1`,
        )
          .bind(fichaCompleta.tipo_sessao, fichaCompleta.tipo_aeronave)
          .first();

        console.log(`[AUTO-POPULATE] modelo encontrado:`, modelo);

        const modeloIdFinal = modelo ? modelo.id : null;

        if (modeloIdFinal) {
          // Buscar manobras do modelo e inserir em fichas_sessao_manobras
          const manobrasModelo = await c.env.DB.prepare(
            `SELECT 
              man.codigo,
              man.descricao,
              man.categoria,
              msm.ordem
             FROM modelos_sessao_manobras msm
             INNER JOIN manobras man ON msm.manobra_id = man.id
             WHERE msm.modelo_id = ? AND msm.deleted_at IS NULL AND man.deleted_at IS NULL
             ORDER BY msm.ordem ASC
             LIMIT 22`,
          )
            .bind(modeloIdFinal)
            .all();

          console.log(`[AUTO-POPULATE] manobras do modelo: ${manobrasModelo.results?.length || 0}`);

          // Se o modelo tiver manobras, inserir todas
          if (manobrasModelo.results && manobrasModelo.results.length > 0) {
            console.log(`[AUTO-POPULATE] Inserindo ${manobrasModelo.results.length} manobras...`);
            for (const manobra of manobrasModelo.results) {
              const man = manobra as {
                codigo: string;
                descricao: string;
                categoria: string;
                ordem: number;
              };
              await c.env.DB.prepare(
                `INSERT INTO fichas_sessao_manobras (
                  ficha_id, codigo, descricao, categoria, ordem, resultado, observacoes
                ) VALUES (?, ?, ?, ?, ?, NULL, '')`,
              )
                .bind(id, man.codigo, man.descricao, man.categoria, man.ordem)
                .run();
            }
          } else {
            // Fallback: criar 22 manobras padrão se modelo não tiver manobras
            for (let i = 1; i <= 22; i++) {
              await c.env.DB.prepare(
                `INSERT INTO fichas_sessao_manobras (
                  ficha_id, codigo, descricao, categoria, ordem, resultado, observacoes
                ) VALUES (?, ?, ?, ?, ?, NULL, '')`,
              )
                .bind(id, `ORD-${i}`, `Manobra ${i}`, 'GERAL', i)
                .run();
            }
          }
        } else {
          // Fallback: sem modelo encontrado, criar 22 manobras padrão
          for (let i = 1; i <= 22; i++) {
            await c.env.DB.prepare(
              `INSERT INTO fichas_sessao_manobras (
                ficha_id, codigo, descricao, categoria, ordem, resultado, observacoes
              ) VALUES (?, ?, ?, ?, ?, NULL, '')`,
            )
              .bind(id, `ORD-${i}`, `Manobra ${i}`, 'GERAL', i)
              .run();
          }
        }

        // SEMPRE recarregar manobras após criação (qualquer fallback)
        m = await c.env.DB.prepare(
          `SELECT 
            id,
            ordem,
            codigo,
            descricao,
            categoria,
            resultado,
            observacoes
          FROM fichas_sessao_manobras 
          WHERE ficha_id = ? AND deleted_at IS NULL 
          ORDER BY ordem ASC`,
        )
          .bind(id)
          .all();

        console.log(`[AUTO-POPULATE] ✅ Recarregou: ${m.results?.length || 0} manobras`);
      }
    }

    // 3. Calcular carga horária total (em horas) e dividir para PF e PM
    const carga_horaria_total = f.duracao_minutos
      ? `${(f.duracao_minutos / 60).toFixed(1)}h`
      : 'N/A';

    // Carga horária PF e PM são sempre metade da carga total
    const carga_horaria_horas = f.duracao_minutos ? f.duracao_minutos / 60 : 0;
    const carga_horaria_pf = carga_horaria_horas > 0 ? (carga_horaria_horas / 2).toFixed(1) : '0.0';
    const carga_horaria_pm = carga_horaria_horas > 0 ? (carga_horaria_horas / 2).toFixed(1) : '0.0';

    // 4. Formatar título da sessão: usar nome do agendamento ou construir com template
    let sessao_titulo = f.sessao_nome || 'Sessão de Treinamento';

    // Se não tiver nome no agendamento, construir com template
    if (!f.sessao_nome) {
      const partes = [f.tipo_sessao];
      if (f.template_codigo) partes.push(f.template_codigo);
      if (f.template_tema) partes.push(f.template_tema);
      sessao_titulo = partes.join(' - ') || 'Sessão de Treinamento';
    }

    // 5. Montar resposta completa
    const ficha = {
      id: f.id,
      uuid: f.uuid,
      sessao_titulo,
      tripulante_nome: f.tripulante_nome,
      tripulante_matricula: f.tripulante_matricula,
      tripulante_codigo_anac: f.tripulante_codigo_anac || 'N/A',
      tripulante_funcao: f.tripulante_funcao || 'ALUNO',
      instrutor_nome: f.instrutor_nome,
      instrutor_matricula: f.instrutor_matricula,
      instrutor_codigo_anac: f.instrutor_codigo_anac || 'N/A',
      data: f.data || f.data_sessao,
      horario_inicio: f.horario_inicio || 'N/A',
      horario_fim: f.horario_fim || 'N/A',
      simulador: `${f.simulador_nome} (${f.simulador_modelo})`,
      simulador_nome: f.simulador_nome,
      simulador_modelo: f.simulador_modelo,
      simulador_tipo: f.simulador_tipo,
      carga_horaria_total,
      carga_horaria_pf,
      carga_horaria_pm,
      duracao_minutos: f.duracao_minutos,
      status: f.status,
      aprovado: f.aprovado,
      nota_final: f.nota_final,
      resultado_final: f.resultado_final,
      observacoes_gerais: f.observacoes || '',
      assinatura_aluno_timestamp: f.assinatura_aluno_timestamp,
      assinatura_instrutor_timestamp: f.assinatura_instrutor_timestamp,
      assinatura_aluno_ip: f.assinatura_aluno_ip,
      assinatura_instrutor_ip: f.assinatura_instrutor_ip,
      colaborador_id_aluno: f.colaborador_id_aluno,
      manobras: m.results,
      total_manobras: m.results.length,
      // Campos de checks
      is_check: f.is_check || 0,
      examinador_id: f.examinador_id || null,
      examinador_nome: f.examinador_nome || null,
      // ID da sessão para endpoints de checks
      sessao_id: f.agendamento_slot_id || null,
    };

    return c.json({ success: true, data: ficha });
  } catch (e: any) {
    console.error('Erro ao buscar ficha:', e);
    return c.json({ success: false, error: e.message }, 500);
  }
});

/**
 * POST /api/simuladores/fichas/:id/pdf
 * Gerar PDF da ficha de treinamento (A4 comprimido, 1 página)
 */
app.post('/fichas/:id/pdf', async (c: Context) => {
  try {
    const fichaId = c.req.param('id');

    // 1. Buscar ficha com JOINs (mesma query do GET)
    const f = await c.env.DB.prepare(
      `SELECT 
        fs.id,
        fs.uuid,
        fs.status,
        fs.observacoes,
        fs.assinatura_aluno_timestamp,
        fs.assinatura_instrutor_timestamp,
        fs.colaborador_id_aluno,
        sa.tipo_sessao,
        sa.data,
        sa.hora_inicio as horario_inicio,
        sa.hora_fim as horario_fim,
        sa.duracao_minutos,
        ft.nome as tripulante_nome,
        ft.codigo_anac as tripulante_codigo_anac,
        sp.funcao as tripulante_funcao,
        fi.nome as instrutor_nome,
        fi.codigo_anac as instrutor_codigo_anac,
        s.nome as simulador_nome,
        s.modelo as simulador_modelo
      FROM fichas_sessao fs
      INNER JOIN simulador_agendamentos sa ON fs.agendamento_slot_id = sa.id AND sa.deleted_at IS NULL
      INNER JOIN funcionarios ft ON fs.colaborador_id_aluno = ft.id AND ft.deleted_at IS NULL
      INNER JOIN funcionarios fi ON fs.instrutor_id = fi.id AND fi.deleted_at IS NULL
      INNER JOIN simuladores s ON sa.simulador_id = s.id AND s.deleted_at IS NULL
      LEFT JOIN sessoes_participantes sp ON sp.sessao_id = sa.id 
        AND sp.funcionario_id = ft.id 
        AND sp.deleted_at IS NULL
      WHERE fs.id = ? AND fs.deleted_at IS NULL
      `,
    )
      .bind(fichaId)
      .first();

    if (!f) return c.json({ success: false, error: 'Ficha não encontrada' }, 404);

    // 2. Buscar empresa_id do funcionário e logo da empresa
    let logoBytes: Buffer | undefined;
    try {
      console.log('[FICHA PDF] Buscando empresa_id do funcionário:', f.colaborador_id_aluno);

      const funcionario = await c.env.DB.prepare(
        `SELECT empresa_id FROM funcionarios WHERE id = ? AND deleted_at IS NULL`,
      )
        .bind(f.colaborador_id_aluno)
        .first<{ empresa_id: number }>();

      console.log('[FICHA PDF] Funcionário encontrado:', funcionario);

      if (funcionario?.empresa_id) {
        const dadosEmpresa = await c.env.DB.prepare(
          `SELECT 
            e.logo_url as logo_principal,
            ec.certificado_logo_url
          FROM empresas e
          LEFT JOIN empresas_config ec ON ec.empresa_id = e.id
          WHERE e.id = ?`,
        )
          .bind(funcionario.empresa_id)
          .first<{
            logo_principal: string;
            certificado_logo_url: string;
          }>();

        console.log('[FICHA PDF] Dados da empresa:', dadosEmpresa);

        // Prioridade: 1. Logo específico do certificado, 2. Logo principal da empresa
        const logoUrl = dadosEmpresa?.certificado_logo_url || dadosEmpresa?.logo_principal;

        console.log('[FICHA PDF] Logo URL:', logoUrl);

        if (logoUrl) {
          // Se for asset interno (/api/assets/...)
          if (logoUrl.startsWith('/api/assets/')) {
            const key = logoUrl.replace('/api/assets/', '');
            console.log('[FICHA PDF] Buscando logo do R2 com key:', key);
            const obj = await c.env.BUCKET.get(key);
            if (obj) {
              logoBytes = Buffer.from(await obj.arrayBuffer());
              console.log('[FICHA PDF] ✅ Logo carregado do R2:', logoBytes.length, 'bytes');
            } else {
              console.warn('[FICHA PDF] ⚠️ Logo não encontrado no R2 com key:', key);
            }
          } else {
            // URL externa
            console.log('[FICHA PDF] Buscando logo de URL externa:', logoUrl);
            const res = await fetch(logoUrl);
            if (res.ok) {
              logoBytes = Buffer.from(await res.arrayBuffer());
              console.log(
                '[FICHA PDF] ✅ Logo carregado de URL externa:',
                logoBytes.length,
                'bytes',
              );
            } else {
              console.warn('[FICHA PDF] ⚠️ Falha ao carregar logo de URL externa:', res.status);
            }
          }
        } else {
          console.log('[FICHA PDF] ⚠️ Nenhuma URL de logo configurada para a empresa');
        }
      } else {
        console.log('[FICHA PDF] ⚠️ Funcionário não possui empresa_id');
      }
    } catch (logoError) {
      console.error('[FICHA PDF] ❌ Erro ao carregar logo:', logoError);
      // Continuar sem logo
    }

    // 3. Buscar 22 manobras
    const m = await c.env.DB.prepare(
      `SELECT 
        ordem,
        descricao,
        codigo,
        resultado
      FROM fichas_sessao_manobras 
      WHERE ficha_id = ? AND deleted_at IS NULL 
      ORDER BY ordem ASC`,
    )
      .bind(fichaId)
      .all();

    // 3. Preparar dados para PDF
    const carga_horaria_total = f.duracao_minutos
      ? `${(f.duracao_minutos / 60).toFixed(1)}h`
      : 'N/A';

    const sessao_titulo = `${f.tipo_sessao} - ${f.simulador_nome}`;

    const dadosPDF = {
      fichaId: f.id.toString(),
      sessao_titulo,
      tripulante_nome: f.tripulante_nome,
      tripulante_codigo_anac: f.tripulante_codigo_anac || 'N/A',
      tripulante_funcao: f.tripulante_funcao || 'ALUNO',
      instrutor_nome: f.instrutor_nome,
      instrutor_codigo_anac: f.instrutor_codigo_anac || 'N/A',
      data: new Date(f.data).toLocaleDateString('pt-BR'),
      horario_inicio: f.horario_inicio || 'N/A',
      horario_fim: f.horario_fim || 'N/A',
      simulador: `${f.simulador_nome} (${f.simulador_modelo})`,
      carga_horaria_total,
      status: f.status,
      observacoes_gerais: f.observacoes || '',
      assinatura_aluno_timestamp: f.assinatura_aluno_timestamp,
      assinatura_instrutor_timestamp: f.assinatura_instrutor_timestamp,
      logoBytes, // Add logo bytes for embedding in PDF
      manobras: m.results.map((man: any) => ({
        ordem: man.ordem,
        descricao: man.descricao,
        codigo: man.codigo,
        resultado: man.resultado,
      })),
    };

    // 4. Gerar PDF usando pdfkit (implementação inline para evitar import externo)
    const { gerarPDFFicha } = await import('../services/pdf-ficha.service');
    const pdfBuffer = await gerarPDFFicha(dadosPDF);

    // 5. Salvar em R2 (se disponível)
    // Sanitizar nome do funcionário para usar no arquivo
    const nomeSanitizado = (f.tripulante_nome as string)
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '') // Remove acentos
      .replace(/[^a-zA-Z0-9\s]/g, '') // Remove caracteres especiais
      .replace(/\s+/g, '_') // Substitui espaços por underscore
      .toUpperCase()
      .substring(0, 30);

    // Format date as DD-MM-YYYY for filename
    const dataObj = new Date(f.data);
    const dia = String(dataObj.getDate()).padStart(2, '0');
    const mes = String(dataObj.getMonth() + 1).padStart(2, '0');
    const ano = dataObj.getFullYear();
    const dataFormatada = `${dia}-${mes}-${ano}`;

    const fileName = `FICHA-${nomeSanitizado}-${dataFormatada}.pdf`;
    if (c.env.R2_BUCKET) {
      try {
        await c.env.R2_BUCKET.put(`fichas-pdf/${fichaId}/${fileName}`, pdfBuffer, {
          customMetadata: {
            fichaId: fichaId.toString(),
            tripulante: f.tripulante_nome,
            data_geracao: new Date().toISOString(),
          },
        });
      } catch (r2Error) {
        console.warn('Aviso: Não foi possível salvar em R2:', r2Error);
      }
    }

    // 6. Auditoria
    await audit(c.env.DB, {
      tabela: 'fichas_sessao',
      acao: 'EXPORTAR_PDF',
      registro_id: fichaId,
      dados_novos: { fileName, tamanho_bytes: pdfBuffer.length },
    });

    // 7. Retornar PDF
    return new Response(pdfBuffer, {
      status: 200,
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `attachment; filename="${fileName}"`,
        'Content-Length': pdfBuffer.length.toString(),
        'Cache-Control': 'no-cache',
      },
    });
  } catch (e: any) {
    console.error('Erro ao gerar PDF:', e);
    return c.json({ success: false, error: e.message || 'Erro ao gerar PDF' }, 500);
  }
});

