// (REMOVIDO) Endpoint legado baseado em tipos_check.
// Os checks devem ser sempre os tipos de qualificação com qualificacoes_tipos.is_check = 1.

// GET /api/simuladores/sessoes/:id/checks - Listar checks de uma sessão
app.get('/sessoes/:id/checks', async (c: Context) => {
  try {
    const id = c.req.param('id');
    const result = await c.env.DB.prepare(
      `SELECT 
        sc.id,
        sc.qualificacao_tipo_id,
        qt.codigo,
        qt.nome,
        qt.descricao,
        scr.aprovado,
        scr.observacoes
      FROM sessoes_checks sc
      INNER JOIN qualificacoes_tipos qt ON sc.qualificacao_tipo_id = qt.id
      LEFT JOIN sessoes_checks_resultados scr ON sc.id = scr.sessao_check_id AND scr.deleted_at IS NULL
      WHERE sc.sessao_id = ? AND sc.deleted_at IS NULL
      ORDER BY qt.codigo`,
    )
      .bind(id)
      .all();
    return c.json({ success: true, data: result.results });
  } catch (e: any) {
    return c.json({ success: false, error: e.message }, 500);
  }
});

// POST /api/simuladores/sessoes/:id/checks/resultados - Salvar resultados de checks
app.post('/sessoes/:id/checks/resultados', async (c: Context) => {
  try {
    const sessao_id = c.req.param('id');
    const body = await c.req.json();
    const { resultados } = body; // [{ sessao_check_id, aprovado, observacoes }]

    if (!resultados || !Array.isArray(resultados)) {
      return c.json({ success: false, error: 'Formato inválido' }, 400);
    }

    // Buscar informações da sessão
    const sessao = await c.env.DB.prepare(
      `SELECT sa.id, sa.funcionario_id, sa.instrutor_id, sa.data, sa.is_check
       FROM simulador_agendamentos sa
       WHERE sa.id = ? AND sa.deleted_at IS NULL`,
    )
      .bind(sessao_id)
      .first();

    if (!sessao) {
      return c.json({ success: false, error: 'Sessão não encontrada' }, 404);
    }

    if ((sessao as any).is_check !== 1) {
      return c.json({ success: false, error: 'Sessão não é do tipo check' }, 400);
    }

    // Descobrir colunas suportadas em qualificacoes_historico (compat)
    const qhCols = await c.env.DB.prepare("PRAGMA table_info('qualificacoes_historico')").all();
    const qhColSet = new Set((qhCols.results || []).map((r: any) => r.name));
    const hasFuncionarioCpf = qhColSet.has('funcionario_cpf');
    const hasCpfLegacy = qhColSet.has('cpf');
    const hasQualificacaoCodigo = qhColSet.has('qualificacao_codigo');
    const hasTipoIdLegacy = qhColSet.has('tipo_id');
    const hasDataConclusao = qhColSet.has('data_conclusao');
    const hasDataRealizacaoLegacy = qhColSet.has('data_realizacao');
    const hasDataVencimento = qhColSet.has('data_vencimento');
    const hasStatus = qhColSet.has('status');
    const hasSessaoId = qhColSet.has('sessao_id');
    const hasObservacoes = qhColSet.has('observacoes');

    // Buscar CPF do aluno da sessão (funcionario_id legado)
    const aluno = await c.env.DB.prepare(
      'SELECT id, cpf FROM funcionarios WHERE id = ? AND deleted_at IS NULL',
    )
      .bind((sessao as any).funcionario_id)
      .first();
    const alunoCpf = (aluno as any)?.cpf;
    if (!alunoCpf) {
      return c.json(
        { success: false, error: 'CPF do aluno não encontrado para gerar qualificação' },
        400,
      );
    }

    const dataConclusaoBase = (sessao as any).data
      ? String((sessao as any).data)
      : new Date().toISOString().split('T')[0];

    // Salvar resultados e gerar qualificações para aprovados
    const qualificacoes_geradas = [];

    for (const res of resultados) {
      const { sessao_check_id, aprovado, observacoes } = res;

      // Verificar se já existe resultado
      const existente = await c.env.DB.prepare(
        'SELECT id FROM sessoes_checks_resultados WHERE sessao_check_id = ? AND deleted_at IS NULL',
      )
        .bind(sessao_check_id)
        .first();

      if (existente) {
        // Atualizar
        await c.env.DB.prepare(
          `UPDATE sessoes_checks_resultados 
           SET aprovado = ?, observacoes = ?, updated_at = datetime('now')
           WHERE id = ?`,
        )
          .bind(aprovado ? 1 : 0, observacoes || null, existente.id)
          .run();
      } else {
        // Inserir
        await c.env.DB.prepare(
          `INSERT INTO sessoes_checks_resultados (sessao_check_id, aprovado, observacoes, created_at, updated_at)
           VALUES (?, ?, ?, datetime('now'), datetime('now'))`,
        )
          .bind(sessao_check_id, aprovado ? 1 : 0, observacoes || null)
          .run();
      }

      // Se aprovado, gerar qualificação automática
      if (aprovado) {
        // Buscar info do check (qualificacao_tipo_id já é o ID correto)
        const check = await c.env.DB.prepare(
          `SELECT sc.qualificacao_tipo_id, qt.codigo, qt.nome, qt.validade
           FROM sessoes_checks sc
           INNER JOIN qualificacoes_tipos qt ON sc.qualificacao_tipo_id = qt.id
           WHERE sc.id = ?`,
        )
          .bind(sessao_check_id)
          .first();

        if (!check) continue;

        const qualificacaoTipoId = (check as any).qualificacao_tipo_id;
        const validadeMeses = (check as any).validade || 12;

        // Evitar duplicar: mesma sessão + mesmo tipo + mesmo aluno
        if (hasSessaoId && (hasFuncionarioCpf || hasCpfLegacy)) {
          // Usar qualificacao_id ou qualificacao_tipo_id dependendo do schema
          const colQualificacao = qhColSet.has('qualificacao_id')
            ? 'qualificacao_id'
            : 'qualificacao_tipo_id';
          const dup = await c.env.DB.prepare(
            `SELECT id FROM qualificacoes_historico
             WHERE sessao_id = ?
               AND ${colQualificacao} = ?
               AND ${hasFuncionarioCpf ? 'funcionario_cpf' : 'cpf'} = ?
               AND deleted_at IS NULL
             LIMIT 1`,
          )
            .bind(sessao_id, qualificacaoTipoId, alunoCpf)
            .first();
          if (dup) {
            continue;
          }
        }

        const dataVencimentoStr = calcularDataVencimento(dataConclusaoBase, validadeMeses, 1);

        // Montar INSERT compatível
        const cols: string[] = [];
        const vals: string[] = [];
        const binds: any[] = [];

        // Funcionário (CPF)
        if (hasFuncionarioCpf) {
          cols.push('funcionario_cpf');
          vals.push('?');
          binds.push(alunoCpf);
        } else if (hasCpfLegacy) {
          cols.push('cpf');
          vals.push('?');
          binds.push(alunoCpf);
        }

        // Tipo de qualificação (usando ID diretamente do check)
        // Tabela usa qualificacao_id, não qualificacao_tipo_id
        if (qhColSet.has('qualificacao_id')) {
          cols.push('qualificacao_id');
          vals.push('?');
          binds.push(qualificacaoTipoId);
        } else if (qhColSet.has('qualificacao_tipo_id')) {
          cols.push('qualificacao_tipo_id');
          vals.push('?');
          binds.push(qualificacaoTipoId);
        }

        // tipo_check_id para rastreabilidade
        if (qhColSet.has('tipo_check_id')) {
          cols.push('tipo_check_id');
          vals.push('?');
          binds.push(sessao_check_id);
        }

        // Data conclusão/realização
        if (hasDataConclusao) {
          cols.push('data_conclusao');
          vals.push('?');
          binds.push(dataConclusaoBase);
        } else if (hasDataRealizacaoLegacy) {
          cols.push('data_realizacao');
          vals.push('?');
          binds.push(dataConclusaoBase);
        }

        // Data vencimento
        if (hasDataVencimento) {
          cols.push('data_vencimento');
          vals.push('?');
          binds.push(dataVencimentoStr);
        }

        // Status
        if (hasStatus) {
          cols.push('status');
          vals.push('?');
          binds.push('CONCLUIDA');
        }

        // Sessão ID
        if (hasSessaoId) {
          cols.push('sessao_id');
          vals.push('?');
          binds.push(Number(sessao_id));
        }

        if (hasObservacoes && observacoes) {
          cols.push('observacoes');
          vals.push('?');
          binds.push(String(observacoes));
        }

        // created_at / updated_at se existirem
        if (qhColSet.has('created_at')) {
          cols.push('created_at');
          vals.push("datetime('now')");
        }
        if (qhColSet.has('updated_at')) {
          cols.push('updated_at');
          vals.push("datetime('now')");
        }

        const insertSql = `INSERT INTO qualificacoes_historico (${cols.join(
          ', ',
        )}) VALUES (${vals.join(', ')})`;

        const qual = await c.env.DB.prepare(insertSql)
          .bind(...binds)
          .run();

        qualificacoes_geradas.push({
          id: qual.meta.last_row_id,
          tipo_check: (check as any).codigo,
          funcionario_id: (sessao as any).funcionario_id,
          qualificacao_tipo_id: qualificacaoTipoId,
        });

        await audit(c.env.DB, {
          tabela: 'qualificacoes_historico',
          acao: 'INSERT_AUTO_CHECK',
          registro_id: qual.meta.last_row_id,
          dados_novos: {
            check: (check as any).codigo,
            sessao_id,
            funcionario_id: (sessao as any).funcionario_id,
            qualificacao_tipo_id: qualificacaoTipoId,
            validade_meses: validadeMeses,
          },
        });
      }
    }

    return c.json({
      success: true,
      message: 'Resultados salvos',
      qualificacoes_geradas,
    });
  } catch (e: any) {
    console.error('Erro ao salvar checks:', e);
    return c.json({ success: false, error: e.message }, 500);
  }
});

export default app;
