/**
 * FUNCIONARIOS ROUTES - Gestão de Funcionários
 *
 * Endpoints CRUD para funcionários:
 * - GET /api/funcionarios - Lista com paginação e busca
 * - GET /api/funcionarios/:id - Busca por ID
 * - POST /api/funcionarios - Cria novo
 * - PUT /api/funcionarios/:id - Atualiza
 * - DELETE /api/funcionarios/:id - Remove (soft delete)
 */

import { Hono } from 'hono';
import type { Env, Funcionario, ApiResponse, PaginatedResponse } from '../types';
import {
  softDelete,
  calculatePagination,
  countRecords,
  buildSearchWhere,
  buildOrderBy,
} from '../utils/db';
import { notFound, badRequest } from '../middleware/error-handler';
import { isValidEmail, isValidCPF, sanitizeString } from '../utils/security';
import { auth } from '../middleware/auth';
import { requireRole } from '../middleware/rbac';
import { registrarAuditoria, extrairUsuarioAuditoria } from '../utils/auditoria';
import { syncFuncionarioCertificacoes } from '../services/sync-certificacoes-funcionarios';

const app = new Hono<{ Bindings: Env }>();

/**
 * GET /api/funcionarios
 * Lista funcionários com paginação e busca
 *
 * Query params:
 * - page: número da página (default: 1)
 * - limit: itens por página (default: 50, max: 100)
 * - search: busca por nome, email, cpf, matricula
 * - status: filtro por ativo (true/false)
 * - cargo: filtro por cargo
 * - setor: filtro por setor
 * - aeronave: filtro por aeronave (string exibida; usa COALESCE(modelo/codigo/nome/aeronave)
 * - orderBy: coluna para ordenação (default: id)
 * - order: direção (ASC/DESC, default: DESC)
 */
app.get('/', auth(), async (c) => {
  const db = c.env.DB;

  // Parâmetros de paginação
  const page = parseInt(c.req.query('page') || '1');
  const limit = parseInt(c.req.query('limit') || '50');

  // Parâmetros de busca/filtro
  const search = c.req.query('search');
  const status = c.req.query('status'); // "true" ou "false"
  const cargo = c.req.query('cargo');
  const setor = c.req.query('setor'); // ✅ ATENÇÃO: Requer migration 0006 aplicada
  const funcao = c.req.query('funcao'); // ✅ Filtro de função
  const aeronave = c.req.query('aeronave'); // ✅ Filtro por aeronave (texto)
  const examinador = c.req.query('examinador'); // NOVO: Filtro para examinadores

  // Parâmetros de ordenação
  const orderBy = c.req.query('orderBy');
  const order = c.req.query('order')?.toUpperCase() as 'ASC' | 'DESC' | undefined;

  // Descobrir schema real (status TEXT vs. ativo INTEGER)
  const cols = (await db.prepare("PRAGMA table_info('funcionarios')").all<{ name: string }>())
    .results as Array<{ name: string }>;
  const hasStatus = cols.some((c) => c.name === 'status');
  const hasAtivo = cols.some((c) => c.name === 'ativo');
  const hasIsExaminador = cols.some((c) => c.name === 'is_examinador');
  const hasIsChecador = cols.some((c) => c.name === 'is_checador');

  // Construir WHERE clauses (main query uses alias `f`; countRecords does not)
  const whereClausesQuery: string[] = ['f.deleted_at IS NULL'];
  const whereClausesCount: string[] = [];
  const bindings: unknown[] = [];

  // Busca textual
  if (search) {
    const searchConditionQuery = buildSearchWhere(
      ['f.nome', 'f.email', 'f.cpf', 'f.matricula'],
      search,
    );
    const searchConditionCount = buildSearchWhere(['nome', 'email', 'cpf', 'matricula'], search);
    if (searchConditionQuery && searchConditionCount) {
      whereClausesQuery.push(searchConditionQuery.clause);
      whereClausesCount.push(searchConditionCount.clause);
      // Adicionar binding para cada coluna
      bindings.push(
        searchConditionQuery.binding,
        searchConditionQuery.binding,
        searchConditionQuery.binding,
        searchConditionQuery.binding,
      );
    }
  }

  // Filtro por status/ativo (compatível com ambos os schemas)
  // Aceita: status=true/false OU status=ativo/inativo/afastados/ferias/desligados
  if (status === 'true' || status === 'ativo' || status === 'ativos') {
    if (hasStatus) {
      whereClausesQuery.push("UPPER(COALESCE(NULLIF(TRIM(f.status), ''), 'ATIVO')) = 'ATIVO'");
      whereClausesCount.push("UPPER(COALESCE(NULLIF(TRIM(status), ''), 'ATIVO')) = 'ATIVO'");
    } else if (hasAtivo) {
      whereClausesQuery.push('COALESCE(f.ativo, 1) = 1');
      whereClausesCount.push('COALESCE(ativo, 1) = 1');
    }
  } else if (status === 'false' || status === 'inativo' || status === 'inativos') {
    if (hasStatus) {
      whereClausesQuery.push("UPPER(COALESCE(NULLIF(TRIM(f.status), ''), 'ATIVO')) = 'INATIVO'");
      whereClausesCount.push("UPPER(COALESCE(NULLIF(TRIM(status), ''), 'ATIVO')) = 'INATIVO'");
    } else if (hasAtivo) {
      whereClausesQuery.push('COALESCE(f.ativo, 1) = 0');
      whereClausesCount.push('COALESCE(ativo, 1) = 0');
    }
  } else if (status === 'afastados' || status === 'afastado') {
    if (hasStatus) {
      whereClausesQuery.push("UPPER(COALESCE(NULLIF(TRIM(f.status), ''), 'ATIVO')) = 'AFASTADO'");
      whereClausesCount.push("UPPER(COALESCE(NULLIF(TRIM(status), ''), 'ATIVO')) = 'AFASTADO'");
    }
  } else if (status === 'ferias') {
    if (hasStatus) {
      whereClausesQuery.push("UPPER(COALESCE(NULLIF(TRIM(f.status), ''), 'ATIVO')) = 'FERIAS'");
      whereClausesCount.push("UPPER(COALESCE(NULLIF(TRIM(status), ''), 'ATIVO')) = 'FERIAS'");
    }
  } else if (status === 'desligados' || status === 'desligado') {
    if (hasStatus) {
      whereClausesQuery.push("UPPER(COALESCE(NULLIF(TRIM(f.status), ''), 'ATIVO')) = 'DESLIGADO'");
      whereClausesCount.push("UPPER(COALESCE(NULLIF(TRIM(status), ''), 'ATIVO')) = 'DESLIGADO'");
    }
  }

  // Filtro por cargo
  if (cargo) {
    whereClausesQuery.push('f.cargo = ?');
    whereClausesCount.push('cargo = ?');
    bindings.push(cargo);
  }

  // Filtro por setor (✅ ATENÇÃO: Requer migration 0006 aplicada)
  if (setor) {
    whereClausesQuery.push('f.setor = ?');
    whereClausesCount.push('setor = ?');
    bindings.push(setor);
  }

  // Filtro por função
  if (funcao) {
    whereClausesQuery.push('f.funcao = ?');
    whereClausesCount.push('funcao = ?');
    bindings.push(funcao);
  }

  // Filtro por aeronave (usa o mesmo COALESCE do SELECT)
  if (aeronave) {
    whereClausesQuery.push('COALESCE(ma.modelo, ma.codigo, ma.nome, f.aeronave) = ?');
    // No countRecords não temos alias nem join; melhor filtrar pelo campo base f.aeronave
    // (fallback seguro para schemas antigos)
    whereClausesCount.push('COALESCE(aeronave, "") = ?');
    bindings.push(aeronave);
  }

  // Filtro por examinador
  if (examinador === 'true') {
    // Compat: projetos antigos usam is_checador; novos podem ter is_examinador
    if (hasIsExaminador && hasIsChecador) {
      whereClausesQuery.push(
        '(COALESCE(f.is_examinador, 0) = 1 OR COALESCE(f.is_checador, 0) = 1)',
      );
      whereClausesCount.push('(COALESCE(is_examinador, 0) = 1 OR COALESCE(is_checador, 0) = 1)');
    } else if (hasIsExaminador) {
      whereClausesQuery.push('COALESCE(f.is_examinador, 0) = 1');
      whereClausesCount.push('COALESCE(is_examinador, 0) = 1');
    } else if (hasIsChecador) {
      whereClausesQuery.push('COALESCE(f.is_checador, 0) = 1');
      whereClausesCount.push('COALESCE(is_checador, 0) = 1');
    } else {
      // Sem colunas de flag disponíveis
      whereClausesQuery.push('0 = 1');
      whereClausesCount.push('0 = 1');
    }
  }

  const whereClauseQuery = whereClausesQuery.join(' AND ');
  const whereClauseForCount =
    whereClausesCount.length > 0 ? whereClausesCount.join(' AND ') : undefined;
  const total = await countRecords(db, 'funcionarios', whereClauseForCount, bindings);

  // Calcular paginação
  const pagination = calculatePagination({ page, limit }, total);

  // Construir ORDER BY (✅ ATENÇÃO: 'setor' requer migration 0006 aplicada)
  const orderByClause = buildOrderBy(
    ['id', 'nome', 'matricula', 'email', 'cargo', 'setor', 'created_at'],
    orderBy,
    order,
  );
  const [orderByColumn, orderByDirection] = orderByClause.split(' ');
  const orderByQueryClause = `f.${orderByColumn} ${orderByDirection}`;

  // Query principal (✅ ATENÇÃO: Coluna 'setor' requer migration 0006 aplicada em produção)
  // Seleção compatível com ambos os schemas
  const statusExprList = hasStatus
    ? "UPPER(COALESCE(NULLIF(TRIM(f.status), ''), 'ATIVO')) AS status, CASE WHEN UPPER(COALESCE(NULLIF(TRIM(f.status), ''), 'ATIVO')) = 'ATIVO' THEN 1 ELSE 0 END AS ativo"
    : hasAtivo
      ? "CASE WHEN COALESCE(f.ativo, 1) = 1 THEN 'ATIVO' ELSE 'INATIVO' END AS status, COALESCE(f.ativo, 1) AS ativo"
      : "'ATIVO' AS status, 1 AS ativo";

  const query = `
    SELECT 
      f.id, f.matricula, f.nome, f.guerra, f.cpf, f.email, f.telefone,
      f.cargo, f.setor, f.funcao,
      COALESCE(ma.modelo, ma.codigo, ma.nome, f.aeronave) AS aeronave,
      f.codigo_anac,
      f.nascimento, f.licenca, f.codigo_anac, f.sispat, f.prestserv,
      f.admissao,
      ${statusExprList},
      f.is_instrutor, f.is_checador,
      f.created_at, f.updated_at
    FROM funcionarios f
    LEFT JOIN modelos_aeronave ma ON CAST(ma.id AS TEXT) = f.modelo_aeronave_id AND ma.deleted_at IS NULL
    WHERE ${whereClauseQuery}
    ORDER BY ${orderByQueryClause}
    LIMIT ? OFFSET ?
  `;

  const { results } = await db
    .prepare(query)
    .bind(...bindings, pagination.limit, pagination.offset)
    .all<Funcionario>();

  const response: PaginatedResponse<Funcionario> = {
    success: true,
    data: results || [],
    pagination,
  };

  return c.json(response);
});

/**
 * GET /api/funcionarios/stats
 * Retorna estatísticas dos funcionários (total, ativos, inativos)
 */
app.get('/stats', auth(), async (c) => {
  const db = c.env.DB;

  // Descobrir schema real (status TEXT vs. ativo INTEGER)
  const cols = (await db.prepare("PRAGMA table_info('funcionarios')").all<{ name: string }>())
    .results as Array<{ name: string }>;
  const hasStatus = cols.some((col) => col.name === 'status');
  const hasAtivo = cols.some((col) => col.name === 'ativo');

  // Construir expressão para contar ativos/inativos
  // Observação: alguns registros podem ter status = '' (string vazia). Tratar como ATIVO.
  let ativoExpr: string;
  if (hasStatus) {
    ativoExpr = "UPPER(COALESCE(NULLIF(TRIM(f.status), ''), 'ATIVO')) = 'ATIVO'";
  } else if (hasAtivo) {
    // Tratar NULL como ativo por padrão, para evitar totais sem ativos/inativos.
    ativoExpr = 'COALESCE(f.ativo, 1) = 1';
  } else {
    ativoExpr = '1 = 1'; // Assume todos ativos se não há campo
  }

  const stats = await db
    .prepare(
      `
      SELECT 
        COUNT(*) as total,
        SUM(CASE WHEN ${ativoExpr} THEN 1 ELSE 0 END) as ativos,
        SUM(CASE WHEN NOT (${ativoExpr}) THEN 1 ELSE 0 END) as inativos
      FROM funcionarios f
      LEFT JOIN modelos_aeronave ma ON CAST(ma.id AS TEXT) = f.modelo_aeronave_id
      WHERE f.deleted_at IS NULL
    `,
    )
    .first<{ total: number; ativos: number; inativos: number }>();

  return c.json({
    success: true,
    data: {
      total: stats?.total || 0,
      ativos: stats?.ativos || 0,
      inativos: stats?.inativos || 0,
    },
  });
});

/**
 * GET /api/funcionarios/stats/dashboard
 * Retorna estatísticas detalhadas para o dashboard (aeronaves, setores, funções, etc.)
 */
app.get('/stats/dashboard', auth(), async (c) => {
  try {
    const db = c.env.DB;

    // Descobrir schema real
    const cols = (await db.prepare("PRAGMA table_info('funcionarios')").all<{ name: string }>())
      .results as Array<{ name: string }>;
    const hasStatus = cols.some((col) => col.name === 'status');
    const hasAtivo = cols.some((col) => col.name === 'ativo');

    let ativoExpr: string;
    if (hasStatus) {
      ativoExpr = "UPPER(COALESCE(NULLIF(TRIM(f.status), ''), 'ATIVO')) = 'ATIVO'";
    } else if (hasAtivo) {
      ativoExpr = 'COALESCE(f.ativo, 1) = 1';
    } else {
      ativoExpr = '1 = 1';
    }

    // Stats gerais
    const generalStats = await db
      .prepare(
        `
      SELECT 
        COUNT(*) as total,
        SUM(CASE WHEN ${ativoExpr} THEN 1 ELSE 0 END) as ativos,
        SUM(CASE WHEN NOT (${ativoExpr}) THEN 1 ELSE 0 END) as inativos
      FROM funcionarios f
      WHERE f.deleted_at IS NULL
    `,
      )
      .first<{ total: number; ativos: number; inativos: number }>();

    // Funcionários por aeronave
    const porAeronave = await db
      .prepare(
        `
      SELECT 
        COALESCE(ma.codigo, ma.modelo, 'Sem Aeronave') as aeronave,
        COUNT(*) as total,
        SUM(CASE WHEN ${ativoExpr} THEN 1 ELSE 0 END) as ativos
      FROM funcionarios f
      LEFT JOIN modelos_aeronave ma ON CAST(ma.id AS TEXT) = f.modelo_aeronave_id
      WHERE f.deleted_at IS NULL
      GROUP BY ma.id, ma.codigo, ma.modelo
      ORDER BY total DESC
      LIMIT 10
    `,
      )
      .all<{ aeronave: string; total: number; ativos: number }>();

    // Funcionários por função
    const porFuncao = await db
      .prepare(
        `
      SELECT 
        COALESCE(NULLIF(TRIM(f.funcao), ''), 'Não Definida') as funcao,
        COUNT(*) as total,
        SUM(CASE WHEN ${ativoExpr} THEN 1 ELSE 0 END) as ativos
      FROM funcionarios f
      WHERE f.deleted_at IS NULL
      GROUP BY UPPER(TRIM(COALESCE(f.funcao, '')))
      ORDER BY total DESC
      LIMIT 10
    `,
      )
      .all<{ funcao: string; total: number; ativos: number }>();

    // Funcionários por setor
    const porSetor = await db
      .prepare(
        `
      SELECT 
        COALESCE(NULLIF(TRIM(f.setor), ''), 'Não Definido') as setor,
        COUNT(*) as total,
        SUM(CASE WHEN ${ativoExpr} THEN 1 ELSE 0 END) as ativos
      FROM funcionarios f
      WHERE f.deleted_at IS NULL
      GROUP BY UPPER(TRIM(COALESCE(f.setor, '')))
      ORDER BY total DESC
      LIMIT 10
    `,
      )
      .all<{ setor: string; total: number; ativos: number }>();

    // Distribuição por status (detalhada)
    const porStatus = await db
      .prepare(
        `
      SELECT 
        UPPER(COALESCE(NULLIF(TRIM(f.status), ''), 'ATIVO')) as status,
        COUNT(*) as total
      FROM funcionarios f
      WHERE f.deleted_at IS NULL
      GROUP BY UPPER(TRIM(COALESCE(f.status, 'ATIVO')))
      ORDER BY total DESC
    `,
      )
      .all<{ status: string; total: number }>();

    // Contagem de qualificações válidas - DESABILITADO (tabela não existe)
    const qualificacoesStats = {
      funcionarios_com_qualificacoes: 0,
      total_qualificacoes: 0,
      qualificacoes_validas: 0,
      qualificacoes_vencidas: 0,
    };

    // TODO: Habilitar quando a tabela de relação funcionario-qualificacao existir
    // const qualificacoesStats = await db.prepare(...).first();

    const generalTotal = generalStats?.total || 0;
    const generalAtivos = generalStats?.ativos || 0;
    const generalInativos = generalStats?.inativos || 0;

    return c.json({
      success: true,
      data: {
        geral: {
          total: generalTotal,
          ativos: generalAtivos,
          inativos: generalInativos,
          percentual_ativos:
            generalTotal === 0 ? 0 : Math.round((generalAtivos / generalTotal) * 100),
        },
        por_aeronave: porAeronave.results || [],
        por_funcao: porFuncao.results || [],
        por_setor: porSetor.results || [],
        por_status: porStatus.results || [],
        qualificacoes: {
          funcionarios_com_qualificacoes: qualificacoesStats?.funcionarios_com_qualificacoes || 0,
          total_qualificacoes: qualificacoesStats?.total_qualificacoes || 0,
          qualificacoes_validas: qualificacoesStats?.qualificacoes_validas || 0,
          qualificacoes_vencidas: qualificacoesStats?.qualificacoes_vencidas || 0,
          percentual_validas:
            (qualificacoesStats?.total_qualificacoes || 0) === 0
              ? 0
              : Math.round(
                  ((qualificacoesStats?.qualificacoes_validas || 0) /
                    (qualificacoesStats?.total_qualificacoes || 0)) *
                    100,
                ),
        },
      },
    });
  } catch (error) {
    console.error('Erro em /stats/dashboard:', error);
    return c.json(
      {
        success: false,
        error: error instanceof Error ? error.message : 'Erro ao carregar estatísticas',
        details: error instanceof Error ? error.stack : undefined,
      },
      500,
    );
  }
});

/**
 * GET /api/funcionarios/:id
 * Busca funcionário por ID com TODOS os campos
 */
app.get('/:id', auth(), async (c) => {
  const db = c.env.DB;
  const id = parseInt(c.req.param('id'));

  if (isNaN(id)) {
    badRequest('ID inválido');
  }

  // Descobrir schema real
  const cols = (await db.prepare("PRAGMA table_info('funcionarios')").all<{ name: string }>())
    .results as Array<{ name: string }>;
  const hasStatus = cols.some((c) => c.name === 'status');
  const hasAtivo = cols.some((c) => c.name === 'ativo');

  const statusExpr = hasStatus
    ? 'status'
    : hasAtivo
      ? "CASE WHEN ativo = 1 THEN 'ATIVO' ELSE 'INATIVO' END AS status"
      : "'ATIVO' AS status";

  // Query com TODOS os campos incluindo dados pessoais, profissionais e endereço
  const funcionario = await db
    .prepare(
      `
    SELECT 
      id, matricula, nome, guerra, cpf, rg, 
      nascimento, email, telefone,
      funcao, cargo, setor, base, aeronave, modelo_aeronave_id,
      admissao, codigo_anac,
      nivel_icao, data_realizacao_icao, validade_icao, 
      cma, data_realizacao_cma, validade_cma, 
      aso, data_realizacao_aso, validade_aso, 
      sispat, prestserv,
      cep, logradouro, numero, complemento, bairro, cidade, estado,
      observacoes, endereco,
      ${statusExpr},
      is_instrutor, is_checador,
      created_at, updated_at
    FROM funcionarios
    WHERE id = ? AND deleted_at IS NULL
  `,
    )
    .bind(id)
    .first<Funcionario>();

  if (!funcionario) {
    notFound('Funcionário não encontrado');
  }

  const response: ApiResponse<Funcionario> = {
    success: true,
    data: funcionario,
  };

  return c.json(response);
});

/**
 * POST /api/funcionarios
 * Cria novo funcionário
 *
 * RBAC: admin, manager
 *
 * Body (JSON):
 * - matricula: string (obrigatório)
 * - nome: string (obrigatório)
 * - cpf: string (obrigatório, validado)
 * - email: string (obrigatório, validado)
 * - telefone: string (opcional)
 * - cargo: string (opcional)
 * - setor: string (opcional)
 * - funcao: string (opcional)
 * - codigo_anac: string (opcional)
 * - ativo: boolean (default: true)
 * - is_instrutor: boolean (default: false)
 * - is_checador: boolean (default: false)
 * - admissao: string ISO date (opcional)
 * - nascimento: string ISO date (opcional)
 */
app.post('/', auth(), requireRole('admin', 'manager'), async (c) => {
  const db = c.env.DB;
  const body = await c.req.json();

  // Validações obrigatórias (matrícula OPCIONAL agora)
  if (!body.nome || !body.cpf || !body.email) {
    badRequest('Campos obrigatórios: nome, cpf, email');
  }

  // Validar email
  if (!isValidEmail(body.email)) {
    badRequest('Email inválido');
  }

  // Validar CPF
  if (!isValidCPF(body.cpf)) {
    badRequest('CPF inválido');
  }

  // Verificar se matricula já existe (APENAS se fornecida)
  if (body.matricula) {
    const existing = await db
      .prepare('SELECT id FROM funcionarios WHERE matricula = ? AND deleted_at IS NULL')
      .bind(body.matricula)
      .first();

    if (existing) {
      badRequest('Matrícula já cadastrada');
    }
  }

  // Verificar se CPF já existe
  const existingCPF = await db
    .prepare('SELECT id FROM funcionarios WHERE cpf = ? AND deleted_at IS NULL')
    .bind(body.cpf)
    .first();

  if (existingCPF) {
    badRequest('CPF já cadastrado');
  }

  // Inserir com TODOS os campos (novos são opcionais)
  const query = `
    INSERT INTO funcionarios (
      matricula, nome, guerra, cpf, rg, nascimento, sexo, nacionalidade,
      email, telefone, telefone_emergencia, contato_emergencia_nome,
      funcao, cargo, setor, base, modelo_aeronave_id, admissao, codigo_anac,
      nivel_icao, data_realizacao_icao, validade_icao, 
      cma, data_realizacao_cma, validade_cma, 
      aso, data_realizacao_aso, validade_aso, 
      sispat, prestserv,
      cep, logradouro, numero, complemento, bairro, cidade, estado,
      observacoes, foto_url, status, ativo, is_instrutor, is_checador,
      created_at, updated_at
    )
    VALUES (
      ?, ?, ?, ?, ?, ?, ?, ?,
      ?, ?, ?, ?,
      ?, ?, ?, ?, ?, ?, ?,
      ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
      ?, ?, ?, ?, ?, ?, ?,
      ?, ?, ?, ?, ?, ?,
      datetime('now'), datetime('now')
    )
  `;

  const result = await db
    .prepare(query)
    .bind(
      // Dados Pessoais
      body.matricula ? sanitizeString(body.matricula) : null,
      body.nome ? sanitizeString(body.nome) : null,
      body.nome_guerra || null,
      body.cpf ? body.cpf.replace(/\D/g, '') : null,
      body.rg || null,
      body.nascimento || null,
      body.sexo || null,
      body.nacionalidade || 'Brasileira',
      body.email ? body.email.toLowerCase() : null,
      body.telefone || null,
      body.telefone_emergencia || null,
      body.contato_emergencia_nome || null,
      // Dados Profissionais
      body.funcao || null,
      body.cargo || null,
      body.setor || null,
      body.base || null,
      body.modelo_aeronave_id || null,
      body.admissao || null,
      body.codigo_anac || null,
      // Qualificações/Documentação
      body.nivel_icao || null,
      body.data_realizacao_icao || null,
      body.validade_icao || null,
      body.cma || null,
      body.data_realizacao_cma || null,
      body.validade_cma || null,
      body.aso || null,
      body.data_realizacao_aso || null,
      body.validade_aso || null,
      body.sispat || null,
      body.prestserv || null,
      // Endereço
      body.cep || null,
      body.logradouro || null,
      body.numero || null,
      body.complemento || null,
      body.bairro || null,
      body.cidade || null,
      body.estado || null,
      // Outros
      body.observacoes || null,
      body.foto_url || null,
      body.status || 'ATIVO',
      body.ativo !== undefined ? (body.ativo ? 1 : 0) : 1, // Default: ativo
      body.is_instrutor ? 1 : 0,
      body.is_checador ? 1 : 0,
    )
    .run();

  const novoId = result.meta.last_row_id;

  // Buscar dados completos para auditoria
  const novoFuncionario = await db
    .prepare('SELECT * FROM funcionarios WHERE id = ?')
    .bind(novoId)
    .first();

  // Registrar auditoria
  const auditoriaInfo = extrairUsuarioAuditoria(c);
  await registrarAuditoria({
    db,
    tabela: 'funcionarios',
    acao: 'INSERT',
    registro_id: novoId,
    dados_novos: novoFuncionario,
    ...auditoriaInfo,
  });

  // Sincronizar certificações para qualificacoes_historico
  try {
    await syncFuncionarioCertificacoes(db, {
      funcionario_id: novoId,
      nivel_icao: body.nivel_icao,
      data_realizacao_icao: body.data_realizacao_icao,
      validade_icao: body.validade_icao,
      cma: body.cma,
      data_realizacao_cma: body.data_realizacao_cma,
      validade_cma: body.validade_cma,
      aso: body.aso,
      data_realizacao_aso: body.data_realizacao_aso,
      validade_aso: body.validade_aso,
    });
  } catch (syncError) {
    console.error('[Funcionarios] Erro ao sincronizar certificações:', syncError);
    // Não falhar a requisição, apenas logar o erro
  }

  const response: ApiResponse<{ id: number }> = {
    success: true,
    data: { id: novoId },
    message: 'Funcionário criado com sucesso',
  };

  return c.json(response, 201);
});

/**
 * PUT /api/funcionarios/:id
 * Atualiza funcionário existente
 *
 * RBAC: admin, manager
 */
app.put('/:id', auth(), requireRole('admin', 'manager'), async (c) => {
  const db = c.env.DB;
  const id = parseInt(c.req.param('id'));
  const body = await c.req.json();

  if (isNaN(id)) {
    badRequest('ID inválido');
  }

  // Verificar se existe
  const existing = await db
    .prepare('SELECT * FROM funcionarios WHERE id = ? AND deleted_at IS NULL')
    .bind(id)
    .first();

  if (!existing) {
    notFound('Funcionário não encontrado');
  }

  // Guardar dados anteriores para auditoria
  const dadosAnteriores = { ...existing };

  // Validações opcionais
  if (body.email && !isValidEmail(body.email)) {
    badRequest('Email inválido');
  }

  // Verificar duplicatas de matrícula (excluindo próprio registro)
  if (body.matricula) {
    const duplicateMatricula = await db
      .prepare('SELECT id FROM funcionarios WHERE matricula = ? AND id != ? AND deleted_at IS NULL')
      .bind(body.matricula, id)
      .first();

    if (duplicateMatricula) {
      badRequest('Matrícula já cadastrada para outro funcionário');
    }
  }

  // Verificar duplicatas de CPF (excluindo próprio registro)
  if (body.cpf) {
    const duplicateCPF = await db
      .prepare('SELECT id FROM funcionarios WHERE cpf = ? AND id != ? AND deleted_at IS NULL')
      .bind(body.cpf, id)
      .first();

    if (duplicateCPF) {
      badRequest('CPF já cadastrado para outro funcionário');
    }
  }

  // Construir UPDATE dinâmico (apenas campos fornecidos)
  const updates: string[] = [];
  const bindings: unknown[] = [];

  if (body.matricula !== undefined) {
    updates.push('matricula = ?');
    bindings.push(body.matricula ? sanitizeString(body.matricula) : null);
  }

  if (body.nome !== undefined) {
    updates.push('nome = ?');
    bindings.push(body.nome ? sanitizeString(body.nome) : null);
  }

  if (body.cpf !== undefined) {
    updates.push('cpf = ?');
    bindings.push(body.cpf ? body.cpf.replace(/\D/g, '') : null);
  }

  if (body.email !== undefined) {
    updates.push('email = ?');
    bindings.push(body.email ? body.email.toLowerCase() : null);
  }

  if (body.telefone !== undefined) {
    updates.push('telefone = ?');
    bindings.push(body.telefone || null);
  }

  if (body.cargo !== undefined) {
    updates.push('cargo = ?');
    bindings.push(body.cargo);
  }

  if (body.setor !== undefined) {
    updates.push('setor = ?');
    bindings.push(body.setor);
  }

  if (body.funcao !== undefined) {
    updates.push('funcao = ?');
    bindings.push(body.funcao);
  }

  if (body.codigo_anac !== undefined) {
    updates.push('codigo_anac = ?');
    bindings.push(body.codigo_anac);
  }

  if (body.ativo !== undefined) {
    updates.push('ativo = ?');
    bindings.push(body.ativo ? 1 : 0);
  }

  if (body.is_instrutor !== undefined) {
    updates.push('is_instrutor = ?');
    bindings.push(body.is_instrutor ? 1 : 0);
  }

  if (body.is_checador !== undefined) {
    updates.push('is_checador = ?');
    bindings.push(body.is_checador ? 1 : 0);
  }

  if (body.admissao !== undefined) {
    updates.push('admissao = ?');
    bindings.push(body.admissao);
  }

  if (body.status !== undefined) {
    updates.push('status = ?');
    bindings.push(body.status);
    // Sync ativo column: ATIVO → 1, any other status → 0
    const isAtivo = String(body.status).toUpperCase().trim() === 'ATIVO';
    updates.push('ativo = ?');
    bindings.push(isAtivo ? 1 : 0);
  }

  // ===== NOVOS CAMPOS ADICIONADOS =====

  // Dados Pessoais
  if (body.rg !== undefined) {
    updates.push('rg = ?');
    bindings.push(body.rg);
  }

  if (body.guerra !== undefined) {
    updates.push('guerra = ?');
    bindings.push(body.guerra);
  }

  if (body.nascimento !== undefined) {
    updates.push('nascimento = ?');
    bindings.push(body.nascimento);
  }

  // NOVOS CAMPOS FASE 1
  if (body.sexo !== undefined) {
    updates.push('sexo = ?');
    bindings.push(body.sexo);
  }

  if (body.nacionalidade !== undefined) {
    updates.push('nacionalidade = ?');
    bindings.push(body.nacionalidade);
  }

  if (body.telefone_emergencia !== undefined) {
    updates.push('telefone_emergencia = ?');
    bindings.push(body.telefone_emergencia);
  }

  if (body.contato_emergencia_nome !== undefined) {
    updates.push('contato_emergencia_nome = ?');
    bindings.push(body.contato_emergencia_nome);
  }

  if (body.foto_url !== undefined) {
    updates.push('foto_url = ?');
    bindings.push(body.foto_url);
  }

  // Dados Profissionais
  if (body.base !== undefined) {
    updates.push('base = ?');
    bindings.push(body.base);
  }

  if (body.modelo_aeronave_id !== undefined) {
    updates.push('modelo_aeronave_id = ?');
    bindings.push(body.modelo_aeronave_id);

    // Atualizar coluna legada 'aeronave' quando modelo_aeronave_id mudar
    const modeloAeronave = await db
      .prepare(
        `SELECT COALESCE(modelo, codigo, nome) AS aeronave FROM modelos_aeronave WHERE id = ?`,
      )
      .bind(body.modelo_aeronave_id)
      .first<{ aeronave: string }>();

    if (modeloAeronave?.aeronave) {
      updates.push('aeronave = ?');
      bindings.push(modeloAeronave.aeronave);
    }
  }

  // Qualificações/Documentação
  if (body.nivel_icao !== undefined) {
    updates.push('nivel_icao = ?');
    bindings.push(body.nivel_icao);
  }

  if (body.data_realizacao_icao !== undefined) {
    updates.push('data_realizacao_icao = ?');
    bindings.push(body.data_realizacao_icao);
  }

  if (body.validade_icao !== undefined) {
    updates.push('validade_icao = ?');
    bindings.push(body.validade_icao);
  }

  if (body.cma !== undefined) {
    updates.push('cma = ?');
    bindings.push(body.cma);
  }

  if (body.data_realizacao_cma !== undefined) {
    updates.push('data_realizacao_cma = ?');
    bindings.push(body.data_realizacao_cma);
  }

  if (body.validade_cma !== undefined) {
    updates.push('validade_cma = ?');
    bindings.push(body.validade_cma);
  }

  if (body.aso !== undefined) {
    updates.push('aso = ?');
    bindings.push(body.aso);
  }

  if (body.data_realizacao_aso !== undefined) {
    updates.push('data_realizacao_aso = ?');
    bindings.push(body.data_realizacao_aso);
  }

  if (body.validade_aso !== undefined) {
    updates.push('validade_aso = ?');
    bindings.push(body.validade_aso);
  }

  if (body.sispat !== undefined) {
    updates.push('sispat = ?');
    bindings.push(body.sispat);
  }

  if (body.prestserv !== undefined) {
    updates.push('prestserv = ?');
    bindings.push(body.prestserv);
  }

  // Endereço Completo
  if (body.cep !== undefined) {
    updates.push('cep = ?');
    bindings.push(body.cep);
  }

  if (body.logradouro !== undefined) {
    updates.push('logradouro = ?');
    bindings.push(body.logradouro);
  }

  if (body.numero !== undefined) {
    updates.push('numero = ?');
    bindings.push(body.numero);
  }

  if (body.complemento !== undefined) {
    updates.push('complemento = ?');
    bindings.push(body.complemento);
  }

  if (body.bairro !== undefined) {
    updates.push('bairro = ?');
    bindings.push(body.bairro);
  }

  if (body.cidade !== undefined) {
    updates.push('cidade = ?');
    bindings.push(body.cidade);
  }

  if (body.estado !== undefined) {
    updates.push('estado = ?');
    bindings.push(body.estado);
  }

  // Observações
  if (body.observacoes !== undefined) {
    updates.push('observacoes = ?');
    bindings.push(body.observacoes);
  }

  // ===== FIM DOS NOVOS CAMPOS =====

  if (updates.length === 0) {
    badRequest('Nenhum campo para atualizar');
  }

  updates.push("updated_at = datetime('now')");

  const query = `UPDATE funcionarios SET ${updates.join(', ')} WHERE id = ?`;

  await db
    .prepare(query)
    .bind(...bindings, id)
    .run();

  // Buscar dados atualizados para auditoria
  const dadosNovos = await db.prepare('SELECT * FROM funcionarios WHERE id = ?').bind(id).first();

  // Registrar auditoria
  const auditoriaInfo = extrairUsuarioAuditoria(c);
  await registrarAuditoria({
    db,
    tabela: 'funcionarios',
    acao: 'UPDATE',
    registro_id: id,
    dados_anteriores: dadosAnteriores,
    dados_novos: dadosNovos,
    ...auditoriaInfo,
  });
  // Sincronizar certificações para qualificacoes_historico
  try {
    await syncFuncionarioCertificacoes(db, {
      funcionario_id: id,
      nivel_icao: body.nivel_icao,
      data_realizacao_icao: body.data_realizacao_icao,
      validade_icao: body.validade_icao,
      cma: body.cma,
      data_realizacao_cma: body.data_realizacao_cma,
      validade_cma: body.validade_cma,
      aso: body.aso,
      data_realizacao_aso: body.data_realizacao_aso,
      validade_aso: body.validade_aso,
    });
  } catch (syncError) {
    console.error('[Funcionarios] Erro ao sincronizar certificações (UPDATE):', syncError);
    // Não falhar a requisição, apenas logar o erro
  }
  const response: ApiResponse = {
    success: true,
    message: 'Funcionário atualizado com sucesso',
  };

  return c.json(response);
});

/**
 * DELETE /api/funcionarios/:id
 * Remove funcionário (soft delete)
 *
 * RBAC: apenas admin
 */
app.delete('/:id', auth(), requireRole('admin'), async (c) => {
  const db = c.env.DB;
  const id = parseInt(c.req.param('id'));

  if (isNaN(id)) {
    badRequest('ID inválido');
  }

  // Buscar dados antes de deletar para auditoria
  const funcionario = await db
    .prepare('SELECT * FROM funcionarios WHERE id = ? AND deleted_at IS NULL')
    .bind(id)
    .first();

  if (!funcionario) {
    notFound('Funcionário não encontrado');
  }

  const result = await softDelete(db, 'funcionarios', id);

  if (result.meta.changes === 0) {
    notFound('Funcionário não encontrado');
  }

  // Registrar auditoria
  const auditoriaInfo = extrairUsuarioAuditoria(c);
  await registrarAuditoria({
    db,
    tabela: 'funcionarios',
    acao: 'DELETE',
    registro_id: id,
    dados_anteriores: funcionario,
    ...auditoriaInfo,
  });

  const response: ApiResponse = {
    success: true,
    message: 'Funcionário removido com sucesso',
  };

  return c.json(response);
});

export default app;
