// ============================================================
// AIRTRUST - FASE 4: FICHA 360° DO FUNCIONÁRIO
// ============================================================
// Endpoint que retorna visão única com TODAS as informações:
//  - Dados do funcionário (pessoas)
//  - Qualificações (com tipos_qualificacao)
//  - Licenças
//  - Requisitos de compliance para a função
// ============================================================

import { Hono } from 'hono';
import type { Context } from 'hono';

type Env = {
  DB: D1Database;
};

const app = new Hono<{ Bindings: Env }>();

// ============================================================
// Função auxiliar: buscar dados 360° completos
// ============================================================

export async function getFicha360(db: D1Database, funcionarioId: number) {
  try {
    // 1. Dados do funcionário
    const funcionario = await db
      .prepare(`SELECT * FROM funcionarios WHERE id = ? AND deleted_at IS NULL`)
      .bind(funcionarioId)
      .first();
    if (!funcionario) return null;

    // Detectar esquema divergente de qualificações
    const pragmaHist = await db
      .prepare("PRAGMA table_info('qualificacoes_historico')")
      .all<{ name: string }>();
    const histCols = new Set((pragmaHist.results || []).map((r) => r.name));
    const colInicio = histCols.has('data_realizacao')
      ? 'data_realizacao'
      : histCols.has('data_conclusao')
      ? 'data_conclusao'
      : 'data_conclusao';
    const colFim = histCols.has('data_vencimento')
      ? 'data_vencimento'
      : histCols.has('data_validade')
      ? 'data_validade'
      : 'data_vencimento';
    const colTipo = histCols.has('tipo_qualificacao_id')
      ? 'tipo_qualificacao_id'
      : histCols.has('qualificacao_id')
      ? 'qualificacao_id'
      : 'qualificacao_id';

    // 2. Qualificações (normalizar campos)
    const qualificacoesRaw = await db
      .prepare(
        `SELECT q.id, q.funcionario_id, q.${colTipo} as tipo_id, q.${colInicio} as data_realizacao, q.${colFim} as data_vencimento, q.observacoes, q.created_at, q.updated_at, tq.categoria, tq.nome, tq.codigo FROM qualificacoes_historico q JOIN qualificacoes_tipos tq ON q.${colTipo} = tq.id WHERE q.funcionario_id = ? AND q.deleted_at IS NULL ORDER BY q.${colFim} DESC`,
      )
      .bind(funcionarioId)
      .all();
    interface QualRaw {
      [key: string]: unknown;
    }
    const qualificacoes = (qualificacoesRaw.results || []).map((q) => {
      const qr = q as QualRaw;
      return {
        ...qr,
        data_realizacao: qr['data_realizacao'] as string,
        data_vencimento: qr['data_vencimento'] as string,
      };
    });

    // 3. Licenças (tolerar ausência da tabela)
    let licencas: unknown[] = [];
    try {
      const licPragma = await db.prepare("PRAGMA table_info('licencas')").all<{ name: string }>();
      if (licPragma.results && licPragma.results.length > 0) {
        const lic = await db
          .prepare(
            `SELECT * FROM licencas WHERE funcionario_id = ? AND deleted_at IS NULL ORDER BY data_vencimento DESC`,
          )
          .bind(funcionarioId)
          .all();
        licencas = lic.results || [];
      }
    } catch {
      licencas = [];
    }

    // 4. Requisitos de compliance para a função do funcionário
    const funcao = (funcionario as Record<string, unknown>).funcao || 'Piloto';
    let requisitos: unknown[] = [];
    try {
      const reqPragma = await db
        .prepare("PRAGMA table_info('requisitos_compliance')")
        .all<{ name: string }>();
      if (reqPragma.results && reqPragma.results.length > 0) {
        const req = await db
          .prepare(
            `SELECT * FROM requisitos_compliance WHERE funcao = ? AND deleted_at IS NULL ORDER BY tipo_recurso, referencia`,
          )
          .bind(funcao)
          .all();
        requisitos = req.results || [];
      }
    } catch {
      requisitos = [];
    }

    // 5. Sessões de simulador (participações) - detectar tabela de participantes
    const participantesTables = ['sessoes_participantes', 'participantes_sessao'];
    let participantesTable: string | null = null;
    for (const t of participantesTables) {
      const pragma = await db.prepare(`PRAGMA table_info(${t})`).all<{ name: string }>();
      if (pragma.results && pragma.results.length > 0) {
        participantesTable = t;
        break;
      }
    }
    let sessoes: unknown[] = [];
    if (participantesTable) {
      // Verificar colunas para deleted_at / papel vs funcao
      const partColsPragma = await db
        .prepare(`PRAGMA table_info(${participantesTable})`)
        .all<{ name: string }>();
      const partCols = new Set((partColsPragma.results || []).map((r) => r.name));
      const papelCol = partCols.has('papel')
        ? 'papel'
        : partCols.has('funcao')
        ? 'funcao'
        : "'PARTICIPANTE'";
      const deletedFilter = partCols.has('deleted_at') ? 'AND p.deleted_at IS NULL' : '';
      sessoes =
        (
          await db
            .prepare(
              `SELECT s.id, s.simulador_id, s.data_sessao, s.tipo_sessao, s.duracao_minutos, s.status, p.${papelCol} as papel
             FROM ${participantesTable} p JOIN sessoes s ON p.sessao_id = s.id
             WHERE p.funcionario_id = ? ${deletedFilter} AND s.deleted_at IS NULL
             ORDER BY s.data_sessao DESC LIMIT 20`,
            )
            .bind(funcionarioId)
            .all()
        ).results || [];
    }

    // 6. Fichas de simulador do funcionário
    const fichas =
      (
        await db
          .prepare(
            `SELECT id, sessao_id, data_sessao, tipo_sessao, nota_geral, status, updated_at FROM fichas_sessao WHERE funcionario_id = ? AND deleted_at IS NULL ORDER BY data_sessao DESC LIMIT 20`,
          )
          .bind(funcionarioId)
          .all()
      ).results || [];

    return {
      funcionario,
      qualificacoes,
      licencas,
      requisitos,
      simulador: {
        sessoes,
        fichas,
      },
    };
  } catch (error) {
    console.error('Erro em getFicha360:', error);
    throw error;
  }
}

// ============================================================
// GET /api/funcionarios/:id/ficha-360
// ============================================================

app.get('/funcionarios/:id/ficha-360', async (c: Context<{ Bindings: Env }>) => {
  try {
    const id = Number(c.req.param('id'));

    if (Number.isNaN(id)) {
      return c.json({ error: 'ID inválido' }, 400);
    }

    const data = await getFicha360(c.env.DB, id);

    if (!data) {
      return c.json({ error: 'Funcionário não encontrado' }, 404);
    }

    return c.json({
      success: true,
      data,
    });
  } catch (error) {
    console.error('Erro ao buscar ficha 360°:', error);
    return c.json(
      {
        success: false,
        error: 'Erro ao buscar ficha 360°',
      },
      500,
    );
  }
});

export default app;
