/**
 * QUALIFICACOES - MÓDULO HISTÓRICO
 * Gestão de histórico de qualificações com filtros, stats e paginação
 *
 * Endpoints:
 * - GET /historico - Lista histórico com filters, stats, paginação
 * - GET /historico/stats - Estatísticas globais
 * - GET /historico/stats-extended - Stats com filtros e cache
 */

import { Hono } from 'hono';
import type { Env } from '../../types';
import { auth, optionalAuth } from '../../middleware/auth';
import { z } from 'zod';
import { calcularDataVencimento } from '../../utils/qualificacoes-expiration';

const router = new Hono<{ Bindings: Env }>();

// ===== CACHE E HELPERS =====
interface HistoricoStatsCacheEntry {
  key: string;
  ts: number;
  data: {
    total: number;
    validas: number;
    vencendo: number;
    vencidas: number;
    renovadas: number;
    planejadas: number;
  };
}
let historicoStatsCache: HistoricoStatsCacheEntry | null = null;

function generateETag(parts: unknown[]): string {
  try {
    const base = JSON.stringify(parts);
    const b64 = btoa(base).substring(0, 24);
    return `"qh-${b64}"`;
  } catch {
    return '"qh-etag-fallback"';
  }
}

function getCacheTtlMs(env: Env): number {
  const raw = (env as unknown as { CACHE_TTL_SECONDS?: string }).CACHE_TTL_SECONDS || '30';
  const n = parseInt(raw);
  if (isNaN(n) || n <= 0) return 30000;
  return n * 1000;
}

async function invalidateMaterializedStats(db: D1Database) {
  try {
    await db
      .prepare("DELETE FROM qualificacoes_historico_stats_daily WHERE day = date('now')")
      .run();
  } catch (e) {
    console.error('[invalidateMaterializedStats] erro', e);
  }
  historicoStatsCache = null;
}

async function ensureHistoricoSchema(db: D1Database) {
  try {
    const col = await db.prepare('PRAGMA table_info(qualificacoes_historico)').all();
    const hasRenovada = (col.results || []).some((r: any) => r.name === 'renovada');
    if (!hasRenovada) {
      await db
        .prepare('ALTER TABLE qualificacoes_historico ADD COLUMN renovada INTEGER DEFAULT 0')
        .run();
    }

    const hasStatus = (col.results || []).some((r: any) => r.name === 'status');
    if (!hasStatus) {
      await db.prepare('ALTER TABLE qualificacoes_historico ADD COLUMN status TEXT').run();
    }
  } catch (e) {
    console.warn('[ensureHistoricoSchema] Falha:', (e as Error).message);
  }
}

async function ensureModelosAeronaveModeloColumn(db: D1Database) {
  try {
    const col = await db.prepare('PRAGMA table_info(modelos_aeronave)').all();
    const hasModelo = (col.results || []).some((r: any) => r.name === 'modelo');
    if (!hasModelo) {
      await db.prepare('ALTER TABLE modelos_aeronave ADD COLUMN modelo TEXT').run();
    }
    await db
      .prepare(
        "UPDATE modelos_aeronave SET modelo = COALESCE(modelo, codigo, nome) WHERE modelo IS NULL OR modelo = ''",
      )
      .run();
    await db
      .prepare('CREATE INDEX IF NOT EXISTS idx_modelos_aeronave_modelo ON modelos_aeronave(modelo)')
      .run();
  } catch (e) {
    console.warn('[ensureModelosAeronaveModeloColumn] Falha:', (e as Error).message);
  }
}

// Mapeamento de colunas para ordenação segura (evita SQL injection)
const SORTABLE_COLUMNS: Record<string, string> = {
  status: `(
    CASE
      WHEN qh.deleted_at IS NOT NULL THEN 'CANCELADA'
      WHEN qh.renovada = 1 THEN 'RENOVADA'
      WHEN qh.data_conclusao IS NULL THEN 'PLANEJADA'
      WHEN date(qh.data_conclusao, '+' || qt.validade || ' months') IS NULL THEN 'INDEFINIDA'
      WHEN date(qh.data_conclusao, '+' || qt.validade || ' months') < date('now') THEN 'VENCIDA'
      WHEN date(qh.data_conclusao, '+' || qt.validade || ' months') <= date('now','+30 days') THEN 'VENCENDO_30'
      ELSE 'VALIDA'
    END
  )`,
  funcionario: 'f.nome',
  funcionario_nome: 'f.nome',
  qualificacao: 'qt.nome',
  qualificacao_nome: 'qt.nome',
  codigo: 'qt.codigo',
  qualificacao_codigo: 'qt.codigo',
  modelo_aeronave: 'COALESCE(ma.modelo, ma.codigo, ma.nome)',
  categoria: 'qt.categoria',
  qualificacao_categoria: 'qt.categoria',
  data_realizacao: 'qh.data_conclusao',
  realizado: 'qh.data_conclusao',
  data_vencimento:
    "date(qh.data_conclusao, '+' || COALESCE(qh.validade_meses, qt.validade, 12) || ' months')",
  vencimento:
    "date(qh.data_conclusao, '+' || COALESCE(qh.validade_meses, qt.validade, 12) || ' months')",
  validade: 'qt.validade',
  created_at: 'qh.created_at',
  id: 'qh.id',
};

function buildOrderByClause(orderBy: string, order: string): string {
  const direction = order.toUpperCase() === 'DESC' ? 'DESC' : 'ASC';
  const column = SORTABLE_COLUMNS[orderBy] || SORTABLE_COLUMNS['data_vencimento'];
  return `${column} ${direction}`;
}

function safe(fn: (c: any) => Promise<Response> | Response) {
  return async (c: any) => {
    try {
      return await fn(c);
    } catch (e) {
      const errorMessage = (e as Error).message || String(e);
      console.error('[HISTORICO_ERROR]', errorMessage, (e as Error).stack);
      return c.json({ success: false, error: errorMessage }, 500);
    }
  };
}

// ===== ENDPOINTS =====

/**
 * GET /historico
 * Lista histórico de qualificações com filtros, stats e paginação
 */
router.get(
  '/',
  auth(),
  safe(async (c) => {
    const db = c.env.DB;

    await ensureModelosAeronaveModeloColumn(db);

    const {
      page = '1',
      limit = '20',
      search = '',
      status = '',
      funcionario_id = '',
      tipo_id = '',
      aeronave_id = '',
      categoria = '',
      orderBy = 'data_vencimento',
      order = 'ASC',
    } = c.req.query();

    const pageNum = Math.max(parseInt(page, 10) || 1, 1);
    const limitNum = Math.min(Math.max(parseInt(limit, 10) || 20, 1), 500);
    const offset = (pageNum - 1) * limitNum;

    const conditions: string[] = [
      'qh.deleted_at IS NULL',
      'f.id IS NOT NULL',
      'f.deleted_at IS NULL',
      "UPPER(COALESCE(f.status, 'ATIVO')) = 'ATIVO'",
    ];
    console.log('[HISTORICO] Conditions setup. Deleted_at IS NULL enforced.');
    const params: unknown[] = [];

    if (search) {
      conditions.push(
        '(f.nome LIKE ? OR f.matricula LIKE ? OR qt.nome LIKE ? OR qt.codigo LIKE ? OR COALESCE(ma.modelo, ma.codigo, ma.nome) LIKE ?)',
      );
      const pattern = `%${search}%`;
      params.push(pattern, pattern, pattern, pattern, pattern);
    }

    if (funcionario_id) {
      conditions.push('qh.funcionario_id = ?');
      params.push(funcionario_id);
    }
    if (tipo_id) {
      conditions.push('qh.qualificacao_id = ?');
      params.push(tipo_id);
    }
    if (aeronave_id) {
      conditions.push('f.modelo_aeronave_id = ?');
      params.push(aeronave_id);
    }

    if (categoria) {
      conditions.push('qt.categoria = ?');
      params.push(categoria);
    }

    switch (status) {
      case 'VALIDA':
        conditions.push("date(qh.data_conclusao, '+' || qt.validade || ' months') >= date('now')");
        conditions.push('qh.data_conclusao IS NOT NULL');
        break;
      case 'VENCIDA':
        conditions.push("date(qh.data_conclusao, '+' || qt.validade || ' months') < date('now')");
        conditions.push('qh.data_conclusao IS NOT NULL');
        break;
      case 'VENCENDO_30':
        conditions.push(
          "date(qh.data_conclusao, '+' || qt.validade || ' months') >= date('now') AND date(qh.data_conclusao, '+' || qt.validade || ' months') <= date('now','+30 days')",
        );
        conditions.push('qh.data_conclusao IS NOT NULL');
        break;
      case 'RENOVADA':
        conditions.push('qh.renovada = 1');
        break;
      case 'PLANEJADA':
        conditions.push('qh.data_conclusao IS NULL');
        break;
      case 'CANCELADA':
        conditions.push('qh.deleted_at IS NOT NULL');
        break;
    }

    const whereClause = conditions.join(' AND ');

    // STATS GLOBAIS
    const statsQuery = `SELECT 
      COUNT(*) as total,
      SUM(CASE 
        WHEN qh.renovada = 1 THEN 0
        WHEN qh.data_conclusao IS NULL THEN 0
        WHEN julianday(date(qh.data_conclusao, '+' || qt.validade || ' months')) >= julianday('now') 
         AND julianday(date(qh.data_conclusao, '+' || qt.validade || ' months')) - julianday('now') > 30 THEN 1 
        ELSE 0 
      END) as validas,
      SUM(CASE 
        WHEN qh.renovada = 1 THEN 0
        WHEN qh.data_conclusao IS NULL THEN 0
        WHEN julianday(date(qh.data_conclusao, '+' || qt.validade || ' months')) - julianday('now') <= 30 
         AND julianday(date(qh.data_conclusao, '+' || qt.validade || ' months')) >= julianday('now') THEN 1 
        ELSE 0 
      END) as vencendo,
      SUM(CASE 
        WHEN qh.renovada = 1 THEN 0
        WHEN qh.data_conclusao IS NULL THEN 0
        WHEN julianday(date(qh.data_conclusao, '+' || qt.validade || ' months')) < julianday('now') THEN 1 
        ELSE 0 
      END) as vencidas,
      SUM(CASE WHEN qh.renovada = 1 THEN 1 ELSE 0 END) as renovadas,
      SUM(CASE WHEN qh.data_conclusao IS NULL AND qh.deleted_at IS NULL THEN 1 ELSE 0 END) as planejadas
    FROM qualificacoes_historico qh
    LEFT JOIN funcionarios f ON f.id = qh.funcionario_id 
      AND f.deleted_at IS NULL 
      AND UPPER(COALESCE(f.status, 'ATIVO')) = 'ATIVO'
    LEFT JOIN qualificacoes_tipos qt ON qt.id = qh.qualificacao_id
    LEFT JOIN modelos_aeronave ma ON CAST(ma.id AS TEXT) = f.modelo_aeronave_id AND ma.deleted_at IS NULL
    WHERE ${whereClause}`;

    const statsResult = await db
      .prepare(statsQuery)
      .bind(...params)
      .first();

    const stats = {
      total: Number((statsResult as any)?.total || 0),
      validas: Number((statsResult as any)?.validas || 0),
      vencendo: Number((statsResult as any)?.vencendo || 0),
      vencidas: Number((statsResult as any)?.vencidas || 0),
      renovadas: Number((statsResult as any)?.renovadas || 0),
      planejadas: Number((statsResult as any)?.planejadas || 0),
    };

    // DADOS PAGINADOS
    const dataQuery = `SELECT 
      qh.id,
      qh.funcionario_id,
      f.nome as funcionario_nome,
      f.matricula as funcionario_matricula,
      f.funcao AS funcionario_funcao,
      f.cpf AS funcionario_cpf,
      f.codigo_anac AS funcionario_codigo_anac,
      f.modelo_aeronave_id,
      COALESCE(ma.modelo, ma.codigo, ma.nome) AS modelo_aeronave,
      qh.qualificacao_id AS tipo_id,
      qt.nome AS tipo_nome,
      COALESCE(qh.tipo, qt.nome) AS tipo,
      COALESCE(qh.qualificacao_codigo, qt.codigo) AS tipo_codigo,
      COALESCE(qh.categoria, qt.categoria) AS tipo_categoria,
      COALESCE(qh.validade_meses, qt.validade) AS qualificacao_validade,
      COALESCE(qh.validade_meses, qt.validade) AS validade_meses,
      qt.vencimento_fim_mes AS vencimento_fim_mes,
      qh.data_conclusao AS data_realizacao,
      date(qh.data_conclusao, '+' || qt.validade || ' months') AS data_vencimento,
      qh.renovada,
      qh.numero_certificado,
      qh.observacoes AS observacao,
      qh.created_at,
      qh.updated_at,
      qh.certificado_arquivo_id,
      CASE WHEN qh.certificado_arquivo_id IS NOT NULL THEN 1 ELSE 0 END AS tem_certificado,
      qh.arquivo_url AS certificado_url,
      qc.cor AS categoria_cor,
      qc.id AS categoria_id
    FROM qualificacoes_historico qh
    LEFT JOIN funcionarios f ON f.id = qh.funcionario_id 
      AND f.deleted_at IS NULL 
      AND UPPER(COALESCE(f.status, 'ATIVO')) = 'ATIVO'
    LEFT JOIN qualificacoes_tipos qt ON qt.id = qh.qualificacao_id AND qt.deleted_at IS NULL
    LEFT JOIN modelos_aeronave ma ON CAST(ma.id AS TEXT) = f.modelo_aeronave_id AND ma.deleted_at IS NULL
    LEFT JOIN qualificacoes_categorias qc ON UPPER(TRIM(qc.nome)) = UPPER(TRIM(COALESCE(qt.categoria, qh.categoria))) AND qc.deleted_at IS NULL
    WHERE ${whereClause}
    ORDER BY ${buildOrderByClause(orderBy, order)}
    LIMIT ? OFFSET ?`;

    const dataParams = [...params, limitNum, offset];
    const { results } = await db
      .prepare(dataQuery)
      .bind(...dataParams)
      .all();

    // Enriquecer dados com status derivado (como no original)
    const nowTs = Date.now();
    const enriched = (results || []).map((r: any) => {
      // DEBUG CRÍTICO: Log detalhado do campo tem_certificado
      if (r.funcionario_matricula === '172005' && r.tipo_codigo === 'OPC-139') {
        console.log(`[HISTORICO CERTIFICADO DEBUG] ID ${r.id}:`, {
          funcionario: r.funcionario_nome,
          matricula: r.funcionario_matricula,
          tipo: r.tipo_codigo,
          certificado_arquivo_id: r.certificado_arquivo_id,
          tem_certificado: r.tem_certificado,
          certificado_url: r.certificado_url,
        });
      }

      if (r.id === 3849 || r.id === 3253) {
        console.log(
          `[HISTORICO] Processing ID ${r.id}: renovada=${r.renovada}, vencimento=${r.data_vencimento}`,
        );
      }
      let derivedStatus: string;
      if (!r.data_vencimento) derivedStatus = 'INDEFINIDA';
      else {
        const vencTs = new Date(r.data_vencimento).getTime();
        const diffDias = Math.floor((vencTs - nowTs) / (1000 * 60 * 60 * 24));
        if (r.renovada) derivedStatus = 'RENOVADA';
        else if (diffDias < 0) derivedStatus = 'VENCIDA';
        else if (diffDias <= 30) derivedStatus = 'VENCENDO_30';
        else derivedStatus = 'VALIDA';
      }
      return {
        ...r,
        status: derivedStatus,
        data_conclusao: r.data_realizacao, // manter ambos para compatibilidade
        qualificacao_nome: r.tipo_nome,
        qualificacao_codigo: r.tipo_codigo,
        qualificacao_categoria: r.tipo_categoria,
        categoria_cor: r.categoria_cor || null,
        categoria_id: r.categoria_id || null,
        qualificacao_id: r.tipo_id, // manter ambos para compatibilidade
      };
    });

    const etag = generateETag([
      'historico',
      stats.total,
      pageNum,
      limitNum,
      status,
      funcionario_id,
      tipo_id,
      search,
    ]);

    return c.json({
      success: true,
      data: enriched,
      meta: {
        count: enriched.length,
        limit: limitNum,
        offset,
        page: pageNum,
        total: stats.total,
        etag,
      },
      stats,
      pagination: {
        page: pageNum,
        limit: limitNum,
        offset,
        total: stats.total,
        pages: Math.ceil(stats.total / limitNum),
      },
    });
  }),
);

/**
 * GET /historico/stats
 * Estatísticas globais de qualificações
 */
router.get(
  '/stats',
  auth(),
  safe(async (c) => {
    const db = c.env.DB;

    const statsResult = await db
      .prepare(
        `SELECT 
        COUNT(*) as total,
        SUM(CASE 
          WHEN qh.renovada = 1 THEN 0
          WHEN julianday(qh.data_vencimento) >= julianday('now') AND julianday(qh.data_vencimento) - julianday('now') > 30 THEN 1 
          ELSE 0 
        END) as validas,
        SUM(CASE 
          WHEN qh.renovada = 1 THEN 0
          WHEN julianday(qh.data_vencimento) - julianday('now') <= 30 AND julianday(qh.data_vencimento) >= julianday('now') THEN 1 
          ELSE 0 
        END) as vencendo,
        SUM(CASE 
          WHEN qh.renovada = 1 THEN 0
          WHEN julianday(qh.data_vencimento) < julianday('now') THEN 1 
          ELSE 0 
        END) as vencidas,
        SUM(CASE WHEN qh.renovada = 1 THEN 1 ELSE 0 END) as renovadas
      FROM qualificacoes_historico qh
      WHERE qh.deleted_at IS NULL`,
      )
      .first();

    const stats = {
      total: Number((statsResult as any)?.total || 0),
      validas: Number((statsResult as any)?.validas || 0),
      vencendo: Number((statsResult as any)?.vencendo || 0),
      vencidas: Number((statsResult as any)?.vencidas || 0),
      renovadas: Number((statsResult as any)?.renovadas || 0),
    };

    return c.json({ success: true, data: stats });
  }),
);

/**
 * GET /historico/stats-extended
 * Estatísticas com filtros e cache
 */
router.get(
  '/stats-extended',
  auth(),
  safe(async (c) => {
    const db = c.env.DB;
    const funcionarioId = c.req.query('funcionario_id');
    const qualificacaoId = c.req.query('qualificacao_id');
    const extended = (c.req.query('extended') || 'false') === 'true';
    const materialized = (c.req.query('materialized') || 'false') === 'true';

    const whereClauses: string[] = ['qh.deleted_at IS NULL'];
    const bindings: unknown[] = [];

    if (funcionarioId) {
      whereClauses.push('qh.funcionario_id = ?');
      bindings.push(funcionarioId);
    }
    if (qualificacaoId) {
      whereClauses.push('qh.qualificacao_id = ?');
      bindings.push(qualificacaoId);
    }

    const whereClause = whereClauses.join(' AND ');
    const cacheKey = `${funcionarioId || ''}|${qualificacaoId || ''}`;
    const now = Date.now();

    let stats: {
      total: number;
      validas: number;
      vencendo: number;
      vencidas: number;
      renovadas: number;
      planejadas: number;
    } = { total: 0, validas: 0, vencendo: 0, vencidas: 0, renovadas: 0, planejadas: 0 };

    if (
      historicoStatsCache &&
      historicoStatsCache.key === cacheKey &&
      now - historicoStatsCache.ts < getCacheTtlMs(c.env)
    ) {
      stats = historicoStatsCache.data;
    } else {
      const statsQuery = `SELECT 
            COUNT(*) as total,
            SUM(CASE WHEN julianday(qh.data_vencimento) >= julianday('now') AND julianday(qh.data_vencimento) - julianday('now') > 30 THEN 1 ELSE 0 END) as validas,
            SUM(CASE WHEN julianday(qh.data_vencimento) - julianday('now') <= 30 AND julianday(qh.data_vencimento) >= julianday('now') THEN 1 ELSE 0 END) as vencendo,
            SUM(CASE WHEN julianday(qh.data_vencimento) < julianday('now') THEN 1 ELSE 0 END) as vencidas
          FROM qualificacoes_historico qh
          WHERE ${whereClause}`;

      if (materialized) {
        const scopeHash = `${funcionarioId || ''}|${qualificacaoId || ''}`;
        const day = new Date().toISOString().substring(0, 10);
        const existing = await db
          .prepare(
            `SELECT total, validas, vencendo, vencidas, renovadas FROM qualificacoes_historico_stats_daily WHERE day = ? AND scope_hash = ? LIMIT 1`,
          )
          .bind(day, scopeHash)
          .first();

        if (existing) {
          stats = {
            total: Number((existing as any).total || 0),
            validas: Number((existing as any).validas || 0),
            vencendo: Number((existing as any).vencendo || 0),
            vencidas: Number((existing as any).vencidas || 0),
            renovadas: Number((existing as any).renovadas || 0),
            planejadas: Number((existing as any).planejadas || 0),
          };
        } else {
          const statsResult = await db
            .prepare(statsQuery)
            .bind(...bindings)
            .first();
          const toInsert = {
            total: Number((statsResult as any)?.total || 0),
            validas: Number((statsResult as any)?.validas || 0),
            vencendo: Number((statsResult as any)?.vencendo || 0),
            vencidas: Number((statsResult as any)?.vencidas || 0),
            renovadas: 0,
            planejadas: 0,
          };
          await db
            .prepare(
              `INSERT OR IGNORE INTO qualificacoes_historico_stats_daily (day, scope_hash, total, validas, vencendo, vencidas, renovadas) VALUES (?, ?, ?, ?, ?, ?, ?)`,
            )
            .bind(
              day,
              scopeHash,
              toInsert.total,
              toInsert.validas,
              toInsert.vencendo,
              toInsert.vencidas,
              toInsert.renovadas,
            )
            .run();
          stats = toInsert;
        }
      } else {
        const statsResult = await db
          .prepare(statsQuery)
          .bind(...bindings)
          .first();
        stats = {
          total: Number((statsResult as any)?.total || 0),
          validas: Number((statsResult as any)?.validas || 0),
          vencendo: Number((statsResult as any)?.vencendo || 0),
          vencidas: Number((statsResult as any)?.vencidas || 0),
          renovadas: 0,
          planejadas: 0,
        };
      }

      historicoStatsCache = { key: cacheKey, ts: now, data: stats };
    }

    const etag = generateETag([
      'historico-stats',
      stats.total,
      stats.validas,
      stats.vencendo,
      stats.vencidas,
      stats.renovadas,
      materialized ? 'mat' : 'live',
    ]);

    const ifNone = c.req.header('If-None-Match');
    if (ifNone && ifNone === etag) {
      return new Response(null, {
        status: 304,
        headers: {
          ETag: etag,
          'Cache-Control': 'private, max-age=30',
          'X-Cache-Status': 'HIT',
          'X-Materialized': materialized ? 'true' : 'false',
        },
      });
    }

    let extendedData: unknown = undefined;
    if (extended) {
      try {
        const extQuery = `SELECT qt.categoria AS categoria,
                  COUNT(*) AS total,
                  SUM(CASE WHEN julianday(qh.data_vencimento) < julianday('now') THEN 1 ELSE 0 END) AS vencidas,
                  SUM(CASE WHEN julianday(qh.data_vencimento) - julianday('now') <= 30 AND julianday(qh.data_vencimento) >= julianday('now') THEN 1 ELSE 0 END) AS vencendo,
                  SUM(CASE WHEN julianday(qh.data_vencimento) - julianday('now') > 30 THEN 1 ELSE 0 END) AS validas
             FROM qualificacoes_historico qh
             LEFT JOIN qualificacoes_tipos qt ON qt.id = qh.qualificacao_id AND qt.deleted_at IS NULL
             WHERE ${whereClause}
             GROUP BY qt.categoria
             ORDER BY total DESC
             LIMIT 50`;
        const { results: catRows } = await db
          .prepare(extQuery)
          .bind(...bindings)
          .all();
        extendedData = catRows || [];
      } catch (e) {
        extendedData = { error: (e as Error).message };
      }
    }

    return new Response(
      JSON.stringify({
        success: true,
        data: stats,
        extended: extendedData,
      }),
      {
        status: 200,
        headers: {
          'Content-Type': 'application/json',
          ETag: etag,
          'Cache-Control': 'private, max-age=30',
          'X-Cache-Status': historicoStatsCache?.key === cacheKey ? 'HIT' : 'MISS',
          'X-Materialized': materialized ? 'true' : 'false',
        },
      },
    );
  }),
);

// ===== SCHEMA PARA RENOVAÇÃO =====
const renovarSchema = z
  .object({
    // Aceitar ambos os nomes para compatibilidade
    nova_data_vencimento: z.string().min(1).optional(),
    nova_data_conclusao: z.string().min(1).optional(),
    observacao: z.string().optional(),
  })
  .refine((data) => data.nova_data_vencimento || data.nova_data_conclusao, {
    message: 'Nova data de conclusão/realização é obrigatória',
  });

/**
 * POST /historico/:id/renovar
 * Renovar qualificação existente
 * - Marca o registro atual como RENOVADA
 * - Cria novo registro com a nova data de vencimento
 */
router.post(
  '/:id/renovar',
  auth(),
  safe(async (c) => {
    const db = c.env.DB;

    // Compatibilidade com bases antigas (ex.: coluna `status` ausente)
    await ensureHistoricoSchema(db);

    const id = parseInt(c.req.param('id'), 10);

    if (isNaN(id)) {
      return c.json({ success: false, error: 'ID inválido' }, 400);
    }

    // Parse body
    const body = await c.req.json();
    const parsed = renovarSchema.safeParse(body);
    if (!parsed.success) {
      return c.json(
        { success: false, error: 'Dados inválidos', details: parsed.error.flatten().fieldErrors },
        400,
      );
    }

    // Aceitar ambos os nomes
    const novaDataRealizacao = parsed.data.nova_data_conclusao || parsed.data.nova_data_vencimento;
    const observacao = parsed.data.observacao;

    // Validar formato de data
    if (!novaDataRealizacao || !/^\d{4}-\d{2}-\d{2}$/.test(novaDataRealizacao)) {
      return c.json(
        { success: false, error: 'Data de conclusão inválida. Use formato YYYY-MM-DD' },
        400,
      );
    }

    // Buscar qualificação original COM dados do tipo para calcular validade
    const originalResult = await db
      .prepare(
        `SELECT qh.id, qh.funcionario_id, qh.qualificacao_id, qh.qualificacao_codigo, 
                qh.data_conclusao, qh.data_vencimento, qh.observacoes, qh.renovada, 
                qh.validade_meses as hist_validade_meses, qh.tipo_codigo, qh.codigo,
                qh.categoria, qh.numero_certificado, qh.instrutor,
                qt.validade as tipo_validade, qt.nome as tipo_nome, qt.categoria as tipo_categoria
         FROM qualificacoes_historico qh
         LEFT JOIN qualificacoes_tipos qt ON qt.id = qh.qualificacao_id OR qt.codigo = qh.qualificacao_codigo
         WHERE qh.id = ? AND qh.deleted_at IS NULL`,
      )
      .bind(id)
      .first();

    const original = originalResult as {
      id: number;
      funcionario_id: number;
      qualificacao_id: number | null;
      qualificacao_codigo: string | null;
      data_conclusao: string | null;
      data_vencimento: string | null;
      observacoes: string | null;
      renovada: number;
      hist_validade_meses: number | null;
      tipo_codigo: string | null;
      codigo: string | null;
      categoria: string | null;
      numero_certificado: string | null;
      instrutor: string | null;
      tipo_validade: number | null;
      tipo_nome: string | null;
      tipo_categoria: string | null;
    } | null;

    if (!original) {
      return c.json({ success: false, error: 'Qualificação não encontrada' }, 404);
    }

    if (original.renovada === 1) {
      return c.json({ success: false, error: 'Esta qualificação já foi renovada' }, 400);
    }

    try {
      // 1. Marcar original como RENOVADA
      await db
        .prepare(
          `UPDATE qualificacoes_historico 
           SET renovada = 1, updated_at = datetime('now')
           WHERE id = ?`,
        )
        .bind(id)
        .run();

      // 2. Calcular nova data de vencimento
      // Prioridade: hist_validade_meses > tipo_validade > default 12 meses
      const validadeMeses = original.hist_validade_meses || original.tipo_validade || 12;

      const novaDataVencimento = calcularDataVencimento(novaDataRealizacao!, validadeMeses, 1);

      // 3. Criar novo registro com nova data
      // Copiar TODOS os dados do original, apenas alterando datas e observações
      const codigoQualificacao =
        original.qualificacao_codigo || original.codigo || original.tipo_codigo;
      const categoriaQualificacao = original.categoria || original.tipo_categoria;

      const novaObservacao = observacao
        ? `Renovação de #${id}. ${observacao}`
        : `Renovação automática de #${id} em ${new Date().toISOString().split('T')[0]}`;

      console.log('[RENOVAR] Inserindo novo registro:', {
        funcionario_id: original.funcionario_id,
        qualificacao_id: original.qualificacao_id,
        qualificacao_codigo: codigoQualificacao,
        data_conclusao: novaDataRealizacao,
        data_vencimento: novaDataVencimento,
        validade_meses: validadeMeses,
        numero_certificado: original.numero_certificado,
        instrutor: original.instrutor,
      });

      const insertResult = await db
        .prepare(
          `INSERT INTO qualificacoes_historico 
           (funcionario_id, qualificacao_id, qualificacao_codigo, categoria, 
            data_conclusao, data_vencimento, validade_meses, observacoes, 
            renovada, numero_certificado, instrutor,
            created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?, datetime('now'), datetime('now'))`,
        )
        .bind(
          original.funcionario_id,
          original.qualificacao_id,
          codigoQualificacao,
          categoriaQualificacao,
          novaDataRealizacao, // data_conclusao = data informada pelo usuário
          novaDataVencimento, // data_vencimento calculada
          validadeMeses,
          `Renovação de #${id}${observacao ? '. ' + observacao : ''}`, // observações com referência ao ID original
          original.numero_certificado, // copiar certificado
          original.instrutor, // copiar instrutor
        )
        .run();

      // Invalidar cache
      await invalidateMaterializedStats(db);

      return c.json({
        success: true,
        message: 'Qualificação renovada com sucesso',
        data: {
          registro_anterior_id: id,
          novo_registro_id: insertResult.meta.last_row_id,
          nova_data_conclusao: novaDataRealizacao,
          nova_data_vencimento: novaDataVencimento,
          validade_meses: validadeMeses,
        },
      });
    } catch (error) {
      console.error('[RENOVAR] Erro:', error);
      const errorMessage = error instanceof Error ? error.message : String(error);
      return c.json(
        { success: false, error: 'Erro ao renovar qualificação', details: errorMessage },
        500,
      );
    }
  }),
);

/**
 * POST /historico
 * Criar novo registro de qualificação
 */
router.post(
  '/',
  auth(),
  safe(async (c) => {
    const db = c.env.DB;

    // Compatibilidade com bases antigas (ex.: coluna `status` ausente)
    await ensureHistoricoSchema(db);

    const body = await c.req.json();

    // Schema de criação - aceita tanto funcionario_cpf quanto funcionario_id
    const createSchema = z
      .object({
        funcionario_id: z.number().int().positive().optional(),
        funcionario_cpf: z.string().optional(),
        qualificacao_codigo: z.string().min(1),
        data_conclusao: z.string().min(1),
        data_vencimento: z.string().min(1).nullable().optional(),
        observacoes: z.string().nullable().optional(),
        status: z.enum(['PLANEJADA', 'CONCLUIDA']).optional().default('CONCLUIDA'),
      })
      .refine((data) => data.funcionario_id !== undefined || data.funcionario_cpf !== undefined, {
        message: 'funcionario_id ou funcionario_cpf é obrigatório',
      });

    const parsed = createSchema.safeParse(body);
    if (!parsed.success) {
      return c.json(
        { success: false, error: 'Dados inválidos', details: parsed.error.issues },
        400,
      );
    }

    const { funcionario_cpf, qualificacao_codigo, data_conclusao, observacoes, data_vencimento } =
      parsed.data;
    let funcionario_id = parsed.data.funcionario_id;

    // Se veio CPF, buscar funcionario_id
    if (!funcionario_id && funcionario_cpf) {
      const func = (await db
        .prepare('SELECT id FROM funcionarios WHERE cpf = ? AND deleted_at IS NULL')
        .bind(funcionario_cpf)
        .first()) as { id: number } | null;
      if (!func) {
        return c.json(
          { success: false, error: `Funcionário com CPF ${funcionario_cpf} não encontrado` },
          404,
        );
      }
      funcionario_id = func.id;
    }

    // Buscar qualificacao_id pelo código
    const tipo = await db
      .prepare('SELECT id, categoria, validade FROM qualificacoes_tipos WHERE codigo = ?')
      .bind(qualificacao_codigo)
      .first<{ id: number; categoria: string; validade: number | null }>();

    if (!tipo) {
      return c.json(
        {
          success: false,
          error: `Tipo de qualificação com código ${qualificacao_codigo} não encontrado`,
        },
        404,
      );
    }

    const qualificacao_id = tipo.id;
    const categoria = tipo.categoria;
    const validade_meses = tipo.validade || 12;

    // NÃO calcular data_vencimento - deixar NULL para cálculo dinâmico
    // Sistema calcula automaticamente: data_conclusao + validade_meses

    // Auto-detectar status baseado na data de conclusão
    // Se data_conclusao é no futuro, automaticamente definir como PLANEJADA
    const hoje = new Date();
    hoje.setHours(0, 0, 0, 0);
    const dataConclusaoDate = new Date(data_conclusao + 'T00:00:00Z');

    let statusFinal = parsed.data.status;
    if (dataConclusaoDate > hoje) {
      // Data futura = qualificação planejada
      statusFinal = 'PLANEJADA';
    }

    // Inserir registro - data_vencimento E validade_meses = NULL (cálculo dinâmico SEMPRE do tipo)
    const result = await db
      .prepare(
        `INSERT INTO qualificacoes_historico 
         (funcionario_id, qualificacao_id, qualificacao_codigo, categoria, 
          data_conclusao, data_vencimento, validade_meses, observacoes, 
          status, renovada, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, NULL, NULL, ?, ?, 0, datetime('now'), datetime('now'))`,
      )
      .bind(
        funcionario_id,
        qualificacao_id,
        qualificacao_codigo,
        categoria,
        data_conclusao,
        observacoes || null,
        statusFinal,
      )
      .run();

    // Invalidar cache
    await invalidateMaterializedStats(db);

    return c.json({
      success: true,
      message: 'Qualificação criada com sucesso',
      data: {
        id: result.meta.last_row_id,
        funcionario_id,
        qualificacao_id,
        qualificacao_codigo,
        categoria,
        data_conclusao,
        data_vencimento: null, // Calculado dinamicamente no frontend
        validade_meses,
      },
    });
  }),
);

/**
 * PUT /historico/:id
 * Atualizar registro de qualificação (data_conclusao, data_vencimento, observacoes)
 */
router.put(
  '/:id',
  auth(),
  safe(async (c) => {
    const db = c.env.DB;
    const id = parseInt(c.req.param('id'));

    if (isNaN(id) || id <= 0) {
      return c.json({ success: false, error: 'ID inválido' }, 400);
    }

    // Verificar se existe
    const existing = (await db
      .prepare('SELECT id FROM qualificacoes_historico WHERE id = ? AND deleted_at IS NULL')
      .bind(id)
      .first()) as { id: number } | null;

    if (!existing) {
      return c.json({ success: false, error: 'Registro não encontrado' }, 404);
    }

    // Parse body
    const body = await c.req.json();
    const { data_conclusao, observacoes } = body;
    // IGNORAR data_vencimento do body - sempre NULL para cálculo dinâmico

    // Validar campos obrigatórios
    if (!data_conclusao) {
      return c.json({ success: false, error: 'data_conclusao é obrigatória' }, 400);
    }

    // Update - data_vencimento sempre NULL (cálculo dinâmico)
    await db
      .prepare(
        `UPDATE qualificacoes_historico 
         SET data_conclusao = ?, 
             data_vencimento = NULL, 
             observacoes = ?,
             updated_at = datetime('now')
         WHERE id = ? AND deleted_at IS NULL`,
      )
      .bind(data_conclusao, observacoes || null, id)
      .run();

    // Invalidar cache
    await invalidateMaterializedStats(db);

    return c.json({
      success: true,
      message: 'Qualificação atualizada com sucesso',
      data: {
        id,
        data_conclusao,
        data_vencimento: null, // Calculado dinamicamente pelo frontend
        observacoes,
      },
    });
  }),
);

/**
 * POST /historico/:id/confirmar
 * Confirmar qualificação planejada como concluída
 * - Verifica se status = 'PLANEJADA'
 * - Atualiza para status = 'CONCLUIDA'
 * - Registra data_confirmacao e confirmada_por
 */
router.post(
  '/:id/confirmar',
  auth(),
  safe(async (c) => {
    const db = c.env.DB;
    const id = parseInt(c.req.param('id'), 10);
    const user = c.get('user') as { id?: number } | undefined;
    const userId = user?.id || null;

    if (isNaN(id) || id <= 0) {
      return c.json({ success: false, error: 'ID inválido' }, 400);
    }

    // Verificar se existe e está PLANEJADA
    const existing = await db
      .prepare(
        `SELECT id, status, funcionario_id, qualificacao_codigo 
         FROM qualificacoes_historico 
         WHERE id = ? AND deleted_at IS NULL`,
      )
      .bind(id)
      .first<{
        id: number;
        status: string | null;
        funcionario_id: number;
        qualificacao_codigo: string;
      }>();

    if (!existing) {
      return c.json({ success: false, error: 'Qualificação não encontrada' }, 404);
    }

    const currentStatus = existing.status || 'CONCLUIDA';
    if (currentStatus !== 'PLANEJADA') {
      return c.json(
        {
          success: false,
          error: `Apenas qualificações PLANEJADAS podem ser confirmadas. Status atual: ${currentStatus}`,
        },
        400,
      );
    }

    // Atualizar para CONCLUIDA
    await db
      .prepare(
        `UPDATE qualificacoes_historico 
         SET status = 'CONCLUIDA', 
             data_confirmacao = datetime('now'), 
             confirmada_por = ?,
             updated_at = datetime('now')
         WHERE id = ?`,
      )
      .bind(userId, id)
      .run();

    // Invalidar cache
    await invalidateMaterializedStats(db);

    return c.json({
      success: true,
      message: 'Qualificação confirmada com sucesso',
      data: {
        id,
        status: 'CONCLUIDA',
        confirmada_por: userId,
      },
    });
  }),
);

