/**
 * DELETE /historico/:id
 * Deletar registro de qualificação (soft delete ou hard delete para testes)
 */
router.delete(
  '/:id',
  auth(),
  safe(async (c) => {
    const db = c.env.DB;
    const id = parseInt(c.req.param('id'));

    if (isNaN(id) || id <= 0) {
      return c.json({ success: false, error: 'ID inválido' }, 400);
    }

    // Verificar se existe (apenas registros não deletados)
    const exists = await db
      .prepare('SELECT id FROM qualificacoes_historico WHERE id = ? AND deleted_at IS NULL')
      .bind(id)
      .first();

    if (!exists) {
      return c.json({ success: false, error: 'Registro não encontrado' }, 404);
    }

    // Soft delete (padrão do sistema)
    await db
      .prepare(
        'UPDATE qualificacoes_historico SET deleted_at = datetime("now") WHERE id = ? AND deleted_at IS NULL',
      )
      .bind(id)
      .run();

    // Invalidar cache
    await invalidateMaterializedStats(db);

    return c.json({
      success: true,
      message: 'Registro deletado com sucesso',
      data: { id },
    });
  }),
);

export default router;
