/**
 * RATE LIMITING MIDDLEWARE
 *
 * Protege endpoints sensíveis contra abuso
 * Usa in-memory store (por worker instance)
 *
 * Configurações:
 * - Login: 5 tentativas/minuto por IP
 * - API geral: 100 req/minuto por IP
 * - Webhooks: 30 req/minuto por IP
 */

import type { MiddlewareHandler } from 'hono';
import type { Env } from '../types';

interface RateLimitEntry {
  count: number;
  resetAt: number;
}

// In-memory store (por worker instance - OK para Cloudflare Workers)
const rateLimitStore = new Map<string, RateLimitEntry>();

// Limpar entradas expiradas (chamado inline durante requisições)
function cleanupExpired() {
  const now = Date.now();
  for (const [key, entry] of rateLimitStore.entries()) {
    if (now > entry.resetAt) {
      rateLimitStore.delete(key);
    }
  }
}

// Cleanup probabilístico: 1% das requisições faz limpeza
// Evita overhead mas mantém memória sob controle
function maybeCleanup() {
  if (Math.random() < 0.01) {
    cleanupExpired();
  }
}

export interface RateLimitConfig {
  /** Número máximo de requisições */
  maxRequests: number;
  /** Janela de tempo em segundos */
  windowSeconds: number;
  /** Prefixo para a chave (ex: 'login', 'api', 'webhook') */
  keyPrefix: string;
  /** Função para extrair identificador (default: IP) */
  keyExtractor?: (c: Parameters<MiddlewareHandler<{ Bindings: Env }>>[0]) => string;
}

/**
 * Middleware de Rate Limiting
 *
 * @example
 * // 5 tentativas de login por minuto
 * app.use('/api/auth/login', rateLimiter({ maxRequests: 5, windowSeconds: 60, keyPrefix: 'login' }));
 *
 * // 100 requisições API por minuto
 * app.use('/api/*', rateLimiter({ maxRequests: 100, windowSeconds: 60, keyPrefix: 'api' }));
 */
export function rateLimiter(config: RateLimitConfig): MiddlewareHandler<{ Bindings: Env }> {
  const { maxRequests, windowSeconds, keyPrefix, keyExtractor } = config;

  return async (c, next) => {
    // NUNCA fazer rate limit em OPTIONS (preflight CORS)
    if (c.req.method === 'OPTIONS') {
      return next();
    }

    // Cleanup probabilístico: 1% das requisições faz limpeza
    maybeCleanup();

    // Extrair identificador (IP por padrão)
    const identifier = keyExtractor
      ? keyExtractor(c)
      : c.req.header('CF-Connecting-IP') ||
        c.req.header('X-Forwarded-For')?.split(',')[0]?.trim() ||
        'unknown';

    const key = `${keyPrefix}:${identifier}`;
    const now = Date.now();
    const windowMs = windowSeconds * 1000;

    // Buscar ou criar entrada
    let entry = rateLimitStore.get(key);

    if (!entry || now > entry.resetAt) {
      // Nova janela
      entry = { count: 1, resetAt: now + windowMs };
      rateLimitStore.set(key, entry);
    } else {
      // Incrementar contador
      entry.count++;
    }

    // Adicionar headers de rate limit
    const remaining = Math.max(0, maxRequests - entry.count);
    const resetSeconds = Math.ceil((entry.resetAt - now) / 1000);

    c.header('X-RateLimit-Limit', String(maxRequests));
    c.header('X-RateLimit-Remaining', String(remaining));
    c.header('X-RateLimit-Reset', String(resetSeconds));

    // Verificar limite
    if (entry.count > maxRequests) {
      c.header('Retry-After', String(resetSeconds));

      return c.json(
        {
          success: false,
          error: 'Muitas requisições. Tente novamente em alguns segundos.',
          code: 'RATE_LIMIT_EXCEEDED',
          retryAfter: resetSeconds,
        },
        429,
      );
    }

    return next();
  };
}

/**
 * Configurações pré-definidas
 */
export const rateLimitPresets = {
  /** Login: 5 tentativas/minuto */
  login: { maxRequests: 5, windowSeconds: 60, keyPrefix: 'login' },

  /** API geral: 100 req/minuto */
  api: { maxRequests: 100, windowSeconds: 60, keyPrefix: 'api' },

  /** Webhooks: 30 req/minuto */
  webhook: { maxRequests: 30, windowSeconds: 60, keyPrefix: 'webhook' },

  /** Upload: 10 req/minuto */
  upload: { maxRequests: 10, windowSeconds: 60, keyPrefix: 'upload' },

  /** Exportação: 5 req/minuto */
  export: { maxRequests: 5, windowSeconds: 60, keyPrefix: 'export' },
} as const;
