import { Hono } from 'hono';
import { auth } from '../middleware/auth';
import { requireRole } from '../middleware/rbac';
import { processarNotificacoes } from '../cron/notificacoes';

type Env = {
  DB: D1Database;
  SENDGRID_API_KEY?: string;
};

const app = new Hono<{ Bindings: Env }>();

// =============================================
// POST /api/notificacoes/processar
// Processar notificações manualmente (admin only)
// =============================================
app.post('/processar', auth(), requireRole('admin'), async (c) => {
  try {
    console.log('[NOTIFICACOES] 🚀 Processamento manual iniciado pelo usuário');

    await processarNotificacoes(c.env);

    return c.json({
      success: true,
      message: 'Notificações processadas com sucesso',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Erro desconhecido';
    console.error('[NOTIFICACOES] ❌ Erro no processamento manual:', error);
    return c.json(
      {
        success: false,
        error: 'Erro ao processar notificações',
        details: errorMessage,
      },
      500,
    );
  }
});

// =============================================
// GET /api/notificacoes/log
// Listar log de notificações
// =============================================
app.get('/log', auth(), async (c) => {
  try {
    const {
      limit = '50',
      offset = '0',
      status,
      funcionario_cpf,
      data_inicio,
      data_fim,
    } = c.req.query();

    let query = `
      SELECT 
        nl.id,
        nl.config_id,
        nl.qualificacao_historico_id,
        nl.funcionario_cpf,
        f.nome as funcionario_nome,
        nl.tipo,
        nl.destinatario,
        nl.assunto,
        nl.corpo,
        nl.status,
        nl.erro_mensagem,
        nl.enviado_em,
        nl.created_at,
        qt.nome as qualificacao_nome,
        qt.categoria
      FROM notificacoes_log nl
      LEFT JOIN funcionarios f ON nl.funcionario_cpf = f.cpf
      LEFT JOIN qualificacoes_historico qh ON nl.qualificacao_historico_id = qh.id
      LEFT JOIN qualificacoes_tipos qt ON qh.qualificacao_codigo = qt.codigo
      WHERE 1=1
    `;

    const params: (string | number)[] = [];

    if (status) {
      query += ` AND nl.status = ?`;
      params.push(status);
    }

    if (funcionario_cpf) {
      query += ` AND nl.funcionario_cpf = ?`;
      params.push(funcionario_cpf);
    }

    if (data_inicio) {
      query += ` AND DATE(nl.enviado_em) >= ?`;
      params.push(data_inicio);
    }

    if (data_fim) {
      query += ` AND DATE(nl.enviado_em) <= ?`;
      params.push(data_fim);
    }

    query += ` ORDER BY nl.created_at DESC`;
    query += ` LIMIT ? OFFSET ?`;
    params.push(parseInt(limit), parseInt(offset));

    const { results } = await c.env.DB.prepare(query)
      .bind(...params)
      .all();

    // Estatísticas
    const { results: stats } = await c.env.DB.prepare(
      `
      SELECT 
        COUNT(*) as total,
        SUM(CASE WHEN status = 'enviada' THEN 1 ELSE 0 END) as enviadas,
        SUM(CASE WHEN status = 'erro' THEN 1 ELSE 0 END) as erros,
        SUM(CASE WHEN status = 'pendente' THEN 1 ELSE 0 END) as pendentes
      FROM notificacoes_log
    `,
    ).all();

    return c.json({
      success: true,
      data: results,
      meta: {
        count: results.length,
        limit: parseInt(limit),
        offset: parseInt(offset),
        stats: stats[0],
      },
    });
  } catch (error) {
    console.error('[NOTIFICACOES] ❌ Erro ao listar log:', error);
    return c.json(
      {
        success: false,
        error: 'Erro ao listar log de notificações',
      },
      500,
    );
  }
});

// =============================================
// GET /api/notificacoes/config
// Listar configurações de notificações
// =============================================
app.get('/config', auth(), async (c) => {
  try {
    const { results } = await c.env.DB.prepare(
      `
      SELECT 
        id,
        tipo,
        ativo,
        dias_antes,
        urgencia,
        destinatarios,
        template,
        created_at,
        updated_at
      FROM notificacoes_config
      WHERE deleted_at IS NULL
      ORDER BY dias_antes DESC
    `,
    ).all();

    return c.json({
      success: true,
      data: results,
    });
  } catch (error) {
    console.error('[NOTIFICACOES] ❌ Erro ao listar configs:', error);
    return c.json(
      {
        success: false,
        error: 'Erro ao listar configurações',
      },
      500,
    );
  }
});

// =============================================
// PUT /api/notificacoes/config/:id
// Atualizar configuração
// =============================================
app.put('/config/:id', auth(), async (c) => {
  try {
    const id = parseInt(c.req.param('id'));
    const input = await c.req.json();

    await c.env.DB.prepare(
      `
      UPDATE notificacoes_config
      SET 
        ativo = COALESCE(?, ativo),
        dias_antes = COALESCE(?, dias_antes),
        urgencia = COALESCE(?, urgencia),
        destinatarios = COALESCE(?, destinatarios),
        template = COALESCE(?, template),
        updated_at = CURRENT_TIMESTAMP
      WHERE id = ?
    `,
    )
      .bind(
        input.ativo !== undefined ? input.ativo : null,
        input.dias_antes || null,
        input.urgencia || null,
        input.destinatarios || null,
        input.template || null,
        id,
      )
      .run();

    const updated = await c.env.DB.prepare(
      `
      SELECT * FROM notificacoes_config WHERE id = ?
    `,
    )
      .bind(id)
      .first();

    return c.json({
      success: true,
      data: updated,
    });
  } catch (error) {
    console.error('[NOTIFICACOES] ❌ Erro ao atualizar config:', error);
    return c.json(
      {
        success: false,
        error: 'Erro ao atualizar configuração',
      },
      500,
    );
  }
});

// =============================================
// GET /api/notificacoes/sistema
// Lista notificações do sistema (alertas EdApp, etc)
// =============================================
app.get('/sistema', auth(), async (c) => {
  try {
    const db = c.env.DB;
    const { lidas = 'false', limit = '50', tipo = '' } = c.req.query();

    const conditions: string[] = ['n.deleted_at IS NULL'];
    const params: unknown[] = [];

    if (lidas === 'false') {
      conditions.push('n.lida = 0');
    } else if (lidas === 'true') {
      conditions.push('n.lida = 1');
    }

    if (tipo) {
      conditions.push('n.tipo = ?');
      params.push(tipo);
    }

    const whereClause = conditions.join(' AND ');
    const limitNum = Math.min(parseInt(limit, 10) || 50, 200);

    const query = `
      SELECT 
        n.*,
        f.nome as funcionario_nome,
        f.matricula as funcionario_matricula
      FROM notificacoes_sistema n
      LEFT JOIN funcionarios f ON f.id = n.funcionario_id
      WHERE ${whereClause}
      ORDER BY 
        CASE n.prioridade
          WHEN 'URGENTE' THEN 1
          WHEN 'ALTA' THEN 2
          WHEN 'MEDIA' THEN 3
          WHEN 'BAIXA' THEN 4
          ELSE 5
        END,
        n.created_at DESC
      LIMIT ?
    `;

    const { results } = await db
      .prepare(query)
      .bind(...params, limitNum)
      .all();

    const countQuery = `
      SELECT COUNT(*) as total
      FROM notificacoes_sistema
      WHERE lida = 0 AND deleted_at IS NULL
    `;
    const countResult = await db.prepare(countQuery).first<{ total: number }>();

    return c.json({
      success: true,
      data: results,
      total_nao_lidas: countResult?.total || 0,
    });
  } catch (error) {
    console.error('[NOTIFICACOES_SISTEMA_ERROR]', error);
    return c.json({ success: false, error: String(error) }, 500);
  }
});

