// =============================================
// PUT /api/notificacoes/sistema/:id/marcar-lida
// Marca notificação como lida
// =============================================
app.put('/sistema/:id/marcar-lida', auth(), async (c) => {
  try {
    const db = c.env.DB;
    const id = parseInt(c.req.param('id'), 10);
    const user = c.get('user') as { id?: number } | undefined;

    await db
      .prepare(
        `UPDATE notificacoes_sistema 
         SET lida = 1, 
             lida_em = datetime('now'),
             lida_por = ?,
             updated_at = datetime('now')
         WHERE id = ? AND deleted_at IS NULL`,
      )
      .bind(user?.id || null, id)
      .run();

    return c.json({ success: true });
  } catch (error) {
    console.error('[NOTIFICACOES_MARK_READ_ERROR]', error);
    return c.json({ success: false, error: String(error) }, 500);
  }
});

// =============================================
// PUT /api/notificacoes/sistema/marcar-todas-lidas
// Marca todas como lidas
// =============================================
app.put('/sistema/marcar-todas-lidas', auth(), async (c) => {
  try {
    const db = c.env.DB;
    const user = c.get('user') as { id?: number } | undefined;

    const result = await db
      .prepare(
        `UPDATE notificacoes_sistema 
         SET lida = 1, 
             lida_em = datetime('now'),
             lida_por = ?,
             updated_at = datetime('now')
         WHERE lida = 0 AND deleted_at IS NULL`,
      )
      .bind(user?.id || null)
      .run();

    return c.json({
      success: true,
      total_marcadas: result.meta.changes,
    });
  } catch (error) {
    console.error('[NOTIFICACOES_MARK_ALL_READ_ERROR]', error);
    return c.json({ success: false, error: String(error) }, 500);
  }
});

export default app;
