/**
 * AUTH ROUTES - Login, Refresh, Logout
 * Atualizado para usar tabela usuarios + refresh tokens
 */

import { Hono } from 'hono';
import type { Env } from '../types';
import {
  generateJWT,
  verifyPassword,
  generateRefreshToken,
  getRefreshTokenExpiry,
} from '../utils/security';
import { badRequest, unauthorized } from '../middleware/error-handler';
import { auth } from '../middleware/auth';
import { rateLimit } from '../middleware/rateLimit';

// Tipar variáveis adicionadas ao contexto pelo middleware auth()
type AuthVars = {
  userId: number | string;
  userEmail: string;
  userRole: string;
};

const authRoutes = new Hono<{ Bindings: Env; Variables: AuthVars }>();

// Handler OPTIONS para todas as rotas de auth (preflight CORS)
authRoutes.options('/*', (c) => {
  const origin = c.req.header('Origin') || 'http://localhost:3000';
  c.header('Access-Control-Allow-Origin', origin);
  c.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, PATCH, OPTIONS');
  c.header(
    'Access-Control-Allow-Headers',
    'Content-Type, Authorization, X-Requested-With, Accept, Origin',
  );
  c.header('Access-Control-Allow-Credentials', 'true');
  c.header('Access-Control-Max-Age', '86400');
  c.status(204);
  return c.body(null);
});

/**
 * POST /api/auth/login
 *
 * Autentica usuário com email/senha e retorna access + refresh tokens
 *
 * Body:
 * {
 *   "email": "admin@airtrust.com",
 *   "senha": "Admin@123"
 * }
 *
 * Response:
 * {
 *   "success": true,
 *   "data": {
 *     "accessToken": "eyJhbGc...",
 *     "refreshToken": "a1b2c3d4...",
 *     "user": {
 *       "id": 1,
 *       "email": "admin@airtrust.com",
 *       "role": "admin",
 *       "nome": "Administrador AirTrust"
 *     }
 *   }
 * }
 */
authRoutes.post('/login', rateLimit({ windowMs: 60000, max: 10 }), async (c) => {
  try {
    const body = await c.req.json();
    // Aceita tanto 'password' quanto 'senha' para compatibilidade
    const { email, senha, password } = body;
    const passwordToUse = senha || password;

    // Validação básica
    if (!email || !passwordToUse) {
      throw badRequest('Email e senha são obrigatórios', 'MISSING_CREDENTIALS');
    }

    // Atalho de desenvolvimento: bypass completo sem acesso ao banco
    const devEnv = c.env.ENVIRONMENT || 'development';
    if (devEnv !== 'production') {
      const jwtSecret = c.env.JWT_SECRET || 'dev-secret-jwt-airtrust-2025';
      const accessToken = await generateJWT(
        {
          sub: 1,
          email: email.toLowerCase(),
          role: 'admin',
          nome: 'Administrador AirTrust (DEV)',
        },
        jwtSecret,
        3600,
      );

      return c.json({
        success: true,
        data: {
          accessToken,
          refreshToken: 'dev-refresh-token',
          user: {
            id: 1,
            email: email.toLowerCase(),
            role: 'ADMIN',
            nome: 'Administrador AirTrust (DEV)',
          },
        },
      });
    }

    // Buscar usuário no D1
    const db = c.env.DB;

    // Detectar coluna de ativo (active/ativo) de forma segura
    const columns =
      (await db.prepare("PRAGMA table_info('usuarios')").all<{ name: string }>()).results || [];
    const hasActive = columns?.some((col) => col.name === 'active');
    const hasAtivo = columns?.some((col) => col.name === 'ativo');
    const activeWhere = hasActive ? 'AND active = 1' : hasAtivo ? 'AND ativo = 1' : '';

    type DbUser = {
      id: number;
      email: string;
      perfil: string;
      password_hash: string;
      nome: string;
    } | null;

    let user = await db
      .prepare(
        `
        SELECT *
        FROM usuarios
        WHERE email = ?
          AND deleted_at IS NULL
          ${activeWhere}
      `,
      )
      .bind(email.toLowerCase())
      .first<DbUser>();

    if (!user) {
      // Em desenvolvimento, auto-provisionar admin se não existir
      const devEnv = c.env.ENVIRONMENT || 'development';
      if (devEnv !== 'production' && email.toLowerCase() === 'admin@airtrust.com') {
        await db
          .prepare(
            `INSERT INTO usuarios (email, password_hash, nome, perfil, ${
              hasActive ? 'active' : hasAtivo ? 'ativo' : 'created_at'
            })
             VALUES (?, ?, ?, ?, ${hasActive || hasAtivo ? '1' : "datetime('now')"})`,
          )
          .bind('admin@airtrust.com', 'dev-local-bypass', 'Administrador AirTrust', 'ADMIN')
          .run();

        const created = await db
          .prepare(`SELECT * FROM usuarios WHERE email = ? AND deleted_at IS NULL ${activeWhere}`)
          .bind('admin@airtrust.com')
          .first<DbUser>();
        if (created) {
          user = created;
        } else {
          throw unauthorized('Credenciais inválidas', 'INVALID_CREDENTIALS');
        }
      } else {
        throw unauthorized('Credenciais inválidas', 'INVALID_CREDENTIALS');
      }
    }

    // Verificar senha (com fallback de desenvolvimento opcional)
    let isValidPassword = false;
    try {
      isValidPassword = await verifyPassword(
        passwordToUse,
        (user as NonNullable<DbUser>).password_hash,
      );
    } catch (e) {
      console.error('[AUTH] Erro ao verificar senha (bcrypt):', e);
    }

    // Fallback para desenvolvimento: permite login com credenciais padrão se habilitado
    const devBypassEnabled =
      devEnv !== 'production' && (c.env.DEV_AUTH_BYPASS !== 'false' || devEnv === 'development');

    if (!isValidPassword && devBypassEnabled) {
      if (
        user.email === 'admin@airtrust.com' &&
        (passwordToUse === 'Admin@123' || passwordToUse === 'admin123')
      ) {
        isValidPassword = true;
      }
    }

    if (!isValidPassword) {
      throw unauthorized('Credenciais inválidas', 'INVALID_CREDENTIALS');
    }

    // Gerar JWT access token (1 hora)
    const jwtSecret = c.env.JWT_SECRET || 'dev-secret-jwt-airtrust-2025';

    const accessToken = await generateJWT(
      {
        sub: (user as NonNullable<DbUser>).id,
        email: (user as NonNullable<DbUser>).email,
        role: (user as NonNullable<DbUser>).perfil.toLowerCase(), // Normalize to lowercase for RBAC
        nome: (user as NonNullable<DbUser>).nome,
      },
      jwtSecret,
      3600, // 1 hora em segundos
    );

    // Gerar refresh token (7 dias)
    const refreshToken = generateRefreshToken();
    const expiresAt = getRefreshTokenExpiry(7);

    // Salvar refresh token no D1
    await db
      .prepare('INSERT INTO refresh_tokens (user_id, token, expires_at) VALUES (?, ?, ?)')
      .bind((user as NonNullable<DbUser>).id, refreshToken, expiresAt)
      .run();

    // Retornar tokens e dados do usuário
    return c.json({
      success: true,
      data: {
        accessToken,
        refreshToken,
        user: {
          id: user.id,
          email: user.email,
          role: user.perfil, // Campo real: perfil (ADMIN, GESTOR, USUARIO)
          nome: user.nome,
        },
      },
    });
  } catch (error) {
    // Preserve ApiError to allow specific codes/messages from helpers
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    if ((error as any)?.name === 'ApiError') throw error as never;
    console.error('[AUTH] Login error:', error);
    throw unauthorized('Erro ao processar login', 'LOGIN_ERROR');
  }
});

/**
 * POST /api/auth/refresh
 *
 * Renova access token usando refresh token válido
 *
 * Body:
 * {
 *   "refreshToken": "a1b2c3d4..."
 * }
 *
 * Response:
 * {
 *   "success": true,
 *   "data": {
 *     "accessToken": "eyJhbGc...",
 *     "refreshToken": "e5f6g7h8..." (opcional: novo refresh token)
 *   }
 * }
 */
authRoutes.post('/refresh', async (c) => {
  try {
    const body = await c.req.json();
    const { refreshToken } = body;

    if (!refreshToken) {
      throw badRequest('Refresh token é obrigatório', 'MISSING_REFRESH_TOKEN');
    }

    // Buscar refresh token no D1
    const db = c.env.DB;

    // Detectar coluna de ativo em usuarios
    const columns =
      (await db.prepare("PRAGMA table_info('usuarios')").all<{ name: string }>()).results || [];
    const hasActive = columns?.some((col) => col.name === 'active');
    const hasAtivo = columns?.some((col) => col.name === 'ativo');
    const activeWhere = hasActive ? 'AND u.active = 1' : hasAtivo ? 'AND u.ativo = 1' : '';

    type TokenRecord = { user_id: number; email: string; perfil: string; nome: string } | null;
    const tokenRecord = await db
      .prepare(
        `
        SELECT rt.*, u.email, u.perfil, u.nome 
        FROM refresh_tokens rt
        INNER JOIN usuarios u ON rt.user_id = u.id
        WHERE rt.token = ? 
          AND rt.revoked_at IS NULL
          AND rt.expires_at > datetime('now')
          AND u.deleted_at IS NULL
          ${activeWhere}
      `,
      )
      .bind(refreshToken)
      .first<TokenRecord>();

    if (!tokenRecord) {
      throw unauthorized('Refresh token inválido ou expirado', 'INVALID_REFRESH_TOKEN');
    }

    // Gerar novo access token
    const jwtSecret = c.env.JWT_SECRET || 'dev-secret-jwt-airtrust-2025';

    const newAccessToken = await generateJWT(
      {
        sub: (tokenRecord as NonNullable<TokenRecord>).user_id,
        email: tokenRecord.email,
        role: tokenRecord.perfil.toLowerCase(), // Normalize to lowercase
        nome: tokenRecord.nome,
      },
      jwtSecret,
      3600, // 1 hora
    );

    // Opcional: Rotação de refresh token (gerar novo e invalidar o antigo)
    const newRefreshToken = generateRefreshToken();
    const newExpiresAt = getRefreshTokenExpiry(7);

    await db
      .prepare('UPDATE refresh_tokens SET revoked_at = datetime("now") WHERE token = ?')
      .bind(refreshToken)
      .run();

    await db
      .prepare('INSERT INTO refresh_tokens (user_id, token, expires_at) VALUES (?, ?, ?)')
      .bind((tokenRecord as NonNullable<TokenRecord>).user_id, newRefreshToken, newExpiresAt)
      .run();

    return c.json({
      success: true,
      data: {
        accessToken: newAccessToken,
        refreshToken: newRefreshToken,
      },
    });
  } catch (error) {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    if ((error as any)?.name === 'ApiError') throw error as never;
    console.error('[AUTH] Refresh error:', error);
    throw unauthorized('Erro ao renovar token', 'REFRESH_ERROR');
  }
});

/**
 * POST /api/auth/logout
 *
 * Invalida refresh token (revoga)
 *
 * Body:
 * {
 *   "refreshToken": "a1b2c3d4..."
 * }
 *
 * Response:
 * {
 *   "success": true,
 *   "message": "Logout realizado com sucesso"
 * }
 */
authRoutes.post('/logout', async (c) => {
  try {
    const body = await c.req.json();
    const { refreshToken } = body;

    if (!refreshToken) {
      throw badRequest('Refresh token é obrigatório', 'MISSING_REFRESH_TOKEN');
    }

    // Revogar refresh token
    const db = c.env.DB;

    await db
      .prepare('UPDATE refresh_tokens SET revoked_at = datetime("now") WHERE token = ?')
      .bind(refreshToken)
      .run();

    return c.json({
      success: true,
      message: 'Logout realizado com sucesso',
    });
  } catch (error) {
    if (error instanceof Response) throw error;

    console.error('[AUTH] Logout error:', error);
    return c.json(
      {
        success: false,
        error: 'Erro ao fazer logout',
      },
      500,
    );
  }
});

/**
 * GET /api/auth/me
 *
 * Retorna dados do usuário autenticado
 * Requer: Authorization: Bearer <accessToken>
 */
authRoutes.get('/me', auth(), async (c) => {
  try {
    // c.get is tipado via Variables, mas pode retornar string
    const userIdRaw = c.get('userId');
    const userId = typeof userIdRaw === 'string' ? Number(userIdRaw) : (userIdRaw as number);

    // Buscar dados do usuário no D1
    const db = c.env.DB;

    // Detectar coluna de ativo em usuarios
    const columns =
      (await db.prepare("PRAGMA table_info('usuarios')").all<{ name: string }>()).results || [];
    const hasActive = columns?.some((col) => col.name === 'active');
    const hasAtivo = columns?.some((col) => col.name === 'ativo');
    const activeWhere = hasActive ? 'AND active = 1' : hasAtivo ? 'AND ativo = 1' : '';

    type MeRow = { id: number; email: string; perfil: string; nome: string } | null;
    const user = await db
      .prepare(
        `
        SELECT id, email, nome, perfil
        FROM usuarios
        WHERE id = ?
          AND deleted_at IS NULL
          ${activeWhere}
      `,
      )
      .bind(userId)
      .first<MeRow>();

    if (!user) {
      throw unauthorized('Usuário não encontrado', 'USER_NOT_FOUND');
    }

    return c.json({
      success: true,
      data: {
        id: (user as NonNullable<MeRow>).id,
        email: (user as NonNullable<MeRow>).email,
        role: (user as NonNullable<MeRow>).perfil.toLowerCase(), // Normalize to lowercase
        nome: (user as NonNullable<MeRow>).nome,
      },
    });
  } catch (error) {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    if ((error as any)?.name === 'ApiError') throw error as never;
    console.error('[AUTH] /me error:', error);
    throw unauthorized('Erro ao buscar dados do usuário', 'ME_ERROR');
  }
});

export { authRoutes };
