import { calcularDiasAteVencimento, determinarUrgencia } from '../utils/qualificacoes-expiration';

interface Env {
  DB: D1Database;
  EMAIL_API_KEY?: string;
  SENDGRID_API_KEY?: string;
}

interface NotificacaoConfig {
  id: number;
  tipo: string;
  ativo: number;
  dias_antes: number;
  urgencia: string | null;
  destinatarios: string | null;
  template: string;
}

interface QualificacaoParaNotificar {
  id: number;
  funcionario_cpf: string;
  funcionario_nome: string;
  funcionario_email: string;
  qualificacao_codigo: string;
  qualificacao_nome: string;
  categoria: string;
  data_vencimento: string;
}

/**
 * Cron job para enviar notificações de qualificações expirando
 * Executar diariamente às 8h
 */
export async function processarNotificacoes(env: Env): Promise<void> {
  console.log('[NOTIFICACOES] 🔔 Iniciando processamento...');
  console.log('[NOTIFICACOES] Data/Hora:', new Date().toISOString());

  try {
    // 1. Buscar configurações ativas
    const { results: configs } = await env.DB.prepare(
      `
      SELECT 
        id,
        tipo,
        ativo,
        dias_antes,
        urgencia,
        destinatarios,
        template
      FROM notificacoes_config
      WHERE ativo = 1 AND deleted_at IS NULL
      ORDER BY dias_antes ASC
    `,
    ).all();

    console.log(`[NOTIFICACOES] 📋 ${configs.length} configurações ativas encontradas`);

    if (configs.length === 0) {
      console.log('[NOTIFICACOES] ⚠️ Nenhuma configuração ativa. Abortando.');
      return;
    }

    let totalEnviadas = 0;
    let totalErros = 0;

    // 2. Processar cada configuração
    for (const config of configs as unknown as NotificacaoConfig[]) {
      console.log(
        `[NOTIFICACOES] 📧 Processando config ID ${config.id} (${config.tipo}, ${config.dias_antes} dias)`,
      );

      const resultado = await processarConfiguracao(env, config);
      totalEnviadas += resultado.enviadas;
      totalErros += resultado.erros;
    }

    console.log('[NOTIFICACOES] ✅ Processamento concluído');
    console.log(`[NOTIFICACOES] 📊 Total enviadas: ${totalEnviadas}`);
    console.log(`[NOTIFICACOES] ❌ Total erros: ${totalErros}`);
  } catch (error) {
    console.error('[NOTIFICACOES] 💥 Erro fatal:', error);
    throw error;
  }
}

async function processarConfiguracao(
  env: Env,
  config: NotificacaoConfig,
): Promise<{ enviadas: number; erros: number }> {
  let enviadas = 0;
  let erros = 0;

  // Buscar qualificações que precisam de notificação
  const { results: qualificacoes } = await env.DB.prepare(
    `
    SELECT 
      qh.id,
      qh.funcionario_cpf,
      f.nome as funcionario_nome,
      f.email as funcionario_email,
      qh.qualificacao_codigo,
      qt.nome as qualificacao_nome,
      qt.categoria,
      qh.data_vencimento
    FROM qualificacoes_historico qh
    INNER JOIN funcionarios f ON qh.funcionario_cpf = f.cpf
    INNER JOIN qualificacoes_tipos qt ON qh.qualificacao_codigo = qt.codigo
    WHERE qh.deleted_at IS NULL
      AND f.deleted_at IS NULL
      AND UPPER(COALESCE(NULLIF(TRIM(f.status), ''), 'ATIVO')) = 'ATIVO'
      AND qt.deleted_at IS NULL
      AND qh.data_vencimento IS NOT NULL
      AND qh.id IN (
        -- Apenas o registro mais recente de cada qualificação por funcionário
        SELECT MAX(id)
        FROM qualificacoes_historico
        WHERE deleted_at IS NULL
        GROUP BY funcionario_cpf, qualificacao_codigo
      )
  `,
  ).all();

  console.log(`[NOTIFICACOES] 🔍 ${qualificacoes.length} qualificações encontradas para análise`);

  for (const qualificacao of qualificacoes as unknown as QualificacaoParaNotificar[]) {
    const diasAteVencimento = calcularDiasAteVencimento(qualificacao.data_vencimento);
    const urgencia = determinarUrgencia(diasAteVencimento);

    // Verificar se deve notificar
    if (!deveNotificar(config, diasAteVencimento, urgencia)) {
      continue;
    }

    // Verificar se já foi notificado recentemente (últimas 24h)
    const jaNotificado = await env.DB.prepare(
      `
      SELECT id FROM notificacoes_log
      WHERE qualificacao_historico_id = ?
        AND config_id = ?
        AND status = 'enviada'
        AND enviado_em >= datetime('now', '-1 day')
      LIMIT 1
    `,
    )
      .bind(qualificacao.id, config.id)
      .first();

    if (jaNotificado) {
      console.log(
        `[NOTIFICACOES] ⏭️  Já notificado: ${qualificacao.funcionario_nome} - ${qualificacao.qualificacao_nome}`,
      );
      continue;
    }

    // Enviar notificação
    const sucesso = await enviarNotificacao(env, config, qualificacao, diasAteVencimento);

    if (sucesso) {
      enviadas++;
    } else {
      erros++;
    }
  }

  return { enviadas, erros };
}

function deveNotificar(
  config: NotificacaoConfig,
  diasAteVencimento: number | null,
  urgencia: string | null,
): boolean {
  // Se não tem vencimento (vitalício), não notifica
  if (diasAteVencimento === null) return false;

  // Se já venceu, não notifica (já passou)
  if (diasAteVencimento < 0) return false;

  // Se está muito longe do vencimento, não notifica
  if (diasAteVencimento > config.dias_antes) return false;

  // Se config tem filtro de urgência e não bate, não notifica
  if (config.urgencia && urgencia !== config.urgencia) return false;

  return true;
}

async function enviarNotificacao(
  env: Env,
  config: NotificacaoConfig,
  qualificacao: QualificacaoParaNotificar,
  diasAteVencimento: number,
): Promise<boolean> {
  try {
    // Determinar destinatários
    let destinatarios: string[] = [];

    if (config.destinatarios) {
      try {
        destinatarios = JSON.parse(config.destinatarios);
      } catch {
        destinatarios = [config.destinatarios];
      }
    }

    // Se não tem destinatários configurados, usar email do funcionário
    if (destinatarios.length === 0 && qualificacao.funcionario_email) {
      destinatarios = [qualificacao.funcionario_email];
    }

    // Se ainda não tem destinatários, não envia
    if (destinatarios.length === 0) {
      console.log(`[NOTIFICACOES] ⚠️  Sem destinatários: ${qualificacao.funcionario_nome}`);
      return false;
    }

    // Interpolar template
    const corpo = interpolarTemplate(config.template, {
      qualificacao: qualificacao.qualificacao_nome,
      funcionario: qualificacao.funcionario_nome,
      dias: diasAteVencimento.toString(),
      categoria: qualificacao.categoria,
      data_vencimento: new Date(qualificacao.data_vencimento).toLocaleDateString('pt-BR'),
    });

    const urgenciaIcon = diasAteVencimento <= 7 ? '🚨' : diasAteVencimento <= 15 ? '⚠️' : '📅';
    const assunto = `${urgenciaIcon} Alerta: Qualificação ${qualificacao.qualificacao_nome} expirando em ${diasAteVencimento} dias`;

    // Enviar notificação
    if (config.tipo === 'EMAIL') {
      await enviarEmail(env, destinatarios, assunto, corpo);
    } else if (config.tipo === 'DASHBOARD') {
      // Dashboard notificações são apenas registradas no log
      console.log(`[NOTIFICACOES] 📊 Dashboard: ${corpo}`);
    }

    // Registrar log de sucesso
    await env.DB.prepare(
      `
      INSERT INTO notificacoes_log (
        config_id,
        qualificacao_historico_id,
        funcionario_cpf,
        tipo,
        destinatario,
        assunto,
        corpo,
        status,
        enviado_em
      ) VALUES (?, ?, ?, ?, ?, ?, ?, 'enviada', datetime('now'))
    `,
    )
      .bind(
        config.id,
        qualificacao.id,
        qualificacao.funcionario_cpf,
        config.tipo,
        destinatarios.join(', '),
        assunto,
        corpo,
      )
      .run();

    console.log(
      `[NOTIFICACOES] ✅ Enviada: ${qualificacao.funcionario_nome} - ${qualificacao.qualificacao_nome} (${diasAteVencimento}d)`,
    );
    return true;
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Erro desconhecido';
    console.error(`[NOTIFICACOES] ❌ Erro ao enviar:`, error);

    // Registrar erro no log
    await env.DB.prepare(
      `
      INSERT INTO notificacoes_log (
        config_id,
        qualificacao_historico_id,
        funcionario_cpf,
        tipo,
        status,
        erro_mensagem
      ) VALUES (?, ?, ?, ?, 'erro', ?)
    `,
    )
      .bind(config.id, qualificacao.id, qualificacao.funcionario_cpf, config.tipo, errorMessage)
      .run();

    return false;
  }
}

function interpolarTemplate(template: string, vars: Record<string, string>): string {
  let resultado = template;

  for (const [key, value] of Object.entries(vars)) {
    resultado = resultado.replace(new RegExp(`{{${key}}}`, 'g'), value);
  }

  return resultado;
}

async function enviarEmail(
  env: Env,
  destinatarios: string[],
  assunto: string,
  corpo: string,
): Promise<void> {
  console.log(`[EMAIL] 📧 Para: ${destinatarios.join(', ')}`);
  console.log(`[EMAIL] 📋 Assunto: ${assunto}`);
  console.log(`[EMAIL] 📄 Corpo: ${corpo.substring(0, 100)}...`);

  // Integração com SendGrid
  if (env.SENDGRID_API_KEY) {
    try {
      const response = await fetch('https://api.sendgrid.com/v3/mail/send', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${env.SENDGRID_API_KEY}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          personalizations: [
            {
              to: destinatarios.map((email) => ({ email })),
              subject: assunto,
            },
          ],
          from: {
            email: 'noreply@airtrust.com',
            name: 'AirTrust - Sistema de Qualificações',
          },
          content: [
            {
              type: 'text/plain',
              value: corpo,
            },
            {
              type: 'text/html',
              value: `
                <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
                  <h2 style="color: #1e40af;">Sistema de Qualificações AirTrust</h2>
                  <p style="font-size: 16px; line-height: 1.6;">${corpo.replace(/\n/g, '<br>')}</p>
                  <hr style="margin: 20px 0;">
                  <p style="color: #666; font-size: 12px;">
                    Esta é uma notificação automática. Por favor, não responda este email.
                  </p>
                </div>
              `,
            },
          ],
        }),
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`SendGrid API error: ${response.status} - ${errorText}`);
      }

      console.log(`[EMAIL] ✅ Email enviado via SendGrid`);
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Erro desconhecido';
      console.error(`[EMAIL] ❌ Erro SendGrid:`, errorMessage);
      throw error;
    }
  } else {
    console.log(
      `[EMAIL] ⚠️  SENDGRID_API_KEY não configurada. Email NÃO enviado (modo simulação).`,
    );
  }
}
