// ========================================
// SCHEMAS ZOD
// ========================================

const WebhookSchema = z.object({
  event: z.enum(['CourseCompletedEvent', 'course.completed']),
  data: z.object({
    userId: z.string(),
    courseId: z.string(),
    completedAt: z.string().optional(),
    score: z.number().optional(),
    username: z.string().optional(),
    email: z.string().optional(),
  }),
});

const CreateMapeamentoUsuarioSchema = z.object({
  funcionario_id: z.number(),
  edapp_user_id: z.string(),
  edapp_email: z.string().optional(),
  edapp_username: z.string().optional(),
});

const CreateMapeamentoCursoSchema = z.object({
  edapp_course_id: z.string(),
  edapp_course_name: z.string().optional(),
  edapp_course_code: z.string().optional(),
  qualificacao_codigo: z.string(),
});

// ========================================
// HELPERS
// ========================================

async function findFuncionarioByEdappUser(db: D1Database, edappUserId: string) {
  return await db
    .prepare(
      `
    SELECT funcionario_id FROM integracoes_edapp_usuarios 
    WHERE edapp_user_id = ? AND deleted_at IS NULL AND ativo = 1
  `,
    )
    .bind(edappUserId)
    .first<{ funcionario_id: number }>();
}

async function findQualificacaoByCourse(db: D1Database, courseId: string) {
  return await db
    .prepare(
      `
    SELECT qualificacao_codigo, edapp_course_name FROM integracoes_edapp_cursos 
    WHERE edapp_course_id = ? AND deleted_at IS NULL AND ativo = 1
  `,
    )
    .bind(courseId)
    .first<{ qualificacao_codigo: string; edapp_course_name: string }>();
}

async function createQualificacao(
  db: D1Database,
  funcionarioId: number,
  qualificacaoCodigo: string,
  origem: string,
  dataCompletedAt?: string, // Data de conclusão do curso (do EdApp)
) {
  // Usar data do EdApp ou hoje como fallback
  const dataConclusao = dataCompletedAt
    ? new Date(dataCompletedAt).toISOString().split('T')[0]
    : new Date().toISOString().split('T')[0];

  // 1. Buscar configuração do tipo de qualificação (validade em meses e ID)
  const tipoQualificacao = await db
    .prepare(
      `
    SELECT id, validade FROM qualificacoes_tipos 
    WHERE codigo = ? AND deleted_at IS NULL
  `,
    )
    .bind(qualificacaoCodigo)
    .first<{ id: number; validade: number }>();

  if (!tipoQualificacao) {
    return {
      success: false,
      message: `Tipo de qualificação ${qualificacaoCodigo} não encontrado`,
    };
  }

  // 2. NÃO calcular data_vencimento - deixar NULL para cálculo dinâmico
  // O sistema calcula automaticamente baseado em data_conclusao + validade_meses

  // 3. Marcar qualificações anteriores como antigas (soft-delete lógico via observações)
  // Para EdApp, sempre criamos um NOVO registro ao invés de atualizar o existente
  await db
    .prepare(
      `
    UPDATE qualificacoes_historico 
    SET observacoes = COALESCE(observacoes, '') || ' | Substituída por curso EdApp em ' || ?
    WHERE funcionario_id = ? 
      AND qualificacao_codigo = ? 
      AND data_vencimento > date('now') 
      AND deleted_at IS NULL
      AND observacoes NOT LIKE '%Substituída por curso EdApp%'
  `,
    )
    .bind(dataConclusao, funcionarioId, qualificacaoCodigo)
    .run();

  // 4. Criar SEMPRE uma nova qualificação (registro individual de cada conclusão)
  const result = await db
    .prepare(
      `
    INSERT INTO qualificacoes_historico (
      funcionario_id, qualificacao_id, qualificacao_codigo, data_conclusao, data_vencimento, 
      validade_meses, observacoes, created_at
    ) VALUES (?, ?, ?, ?, NULL, NULL, ?, datetime('now'))
  `,
    )
    .bind(
      funcionarioId,
      tipoQualificacao.id,
      qualificacaoCodigo,
      dataConclusao,
      `EdApp: ${origem} | Válido por ${tipoQualificacao.validade} meses | Conclusão: ${dataConclusao}`,
    )
    .run();

  return {
    success: true,
    qualificacao_id: result.meta.last_row_id,
    message: `Qualificação criada (validade: ${tipoQualificacao.validade} meses)`,
    renovacao: false,
  };
}

async function renovarQualificacao(
  db: D1Database,
  funcionarioId: number,
  qualificacaoCodigo: string,
  origem: string,
  dataCompletedAt: string,
) {
  const dataConclusao = new Date(dataCompletedAt).toISOString().split('T')[0];

  // Buscar qualificação existente válida (não vencida)
  const qualificacaoExistente = await db
    .prepare(
      `
    SELECT id, data_vencimento 
    FROM qualificacoes_historico 
    WHERE funcionario_id = ? 
      AND qualificacao_codigo = ? 
      AND data_vencimento >= date('now')
      AND deleted_at IS NULL
    ORDER BY data_vencimento DESC
    LIMIT 1
  `,
    )
    .bind(funcionarioId, qualificacaoCodigo)
    .first<{ id: number; data_vencimento: string }>();

  if (qualificacaoExistente) {
    // Marcar a antiga como substituída
    await db
      .prepare(
        `
      UPDATE qualificacoes_historico 
      SET observacoes = COALESCE(observacoes, '') || ' | Substituída por renovação EdApp em ' || ?
      WHERE id = ?
    `,
      )
      .bind(dataConclusao, qualificacaoExistente.id)
      .run();

    // Criar nova qualificação com vencimento calculado a partir da data de conclusão
    const resultado = await createQualificacao(
      db,
      funcionarioId,
      qualificacaoCodigo,
      origem,
      dataCompletedAt,
    );

    return {
      ...resultado,
      renovada: true,
      qualificacao_antiga_id: qualificacaoExistente.id,
    };
  }

  // Se não existe qualificação válida, criar nova normalmente
  return await createQualificacao(db, funcionarioId, qualificacaoCodigo, origem, dataCompletedAt);
}

async function callEdAppAPI(env: Env, method: string, endpoint: string, body?: unknown) {
  const url = `https://rest.edapp.com${endpoint}`;

  const options: RequestInit = {
    method,
    headers: {
      Authorization: `Bearer ${env.EDAPP_API_TOKEN}`,
      'Content-Type': 'application/json',
    },
  };

  if (body) options.body = JSON.stringify(body);

  const response = await fetch(url, options);
  const responseText = await response.text();

  if (!response.ok) {
    console.error(`EdApp API Error: ${response.status} - ${responseText}`);
    throw new Error(`EdApp API Error: ${response.status} - ${responseText}`);
  }

  try {
    return JSON.parse(responseText);
  } catch {
    return responseText;
  }
}

// ========================================
// ENDPOINT: WEBHOOK RECEIVER
// ========================================

edappRouter.post('/webhook', async (c: Context) => {
  try {
    const secret = c.req.header('X-EdApp-Secret');
    if (secret !== c.env.EDAPP_WEBHOOK_SECRET) {
      return c.json({ error: 'Unauthorized' }, 401);
    }

    const body = await c.req.json();
    const parsed = WebhookSchema.parse(body);
    const { event, data } = parsed;

    // Log evento
    const eventoResult = await c.env.DB.prepare(
      `
      INSERT INTO integracoes_edapp_eventos (tipo_evento, edapp_user_id, edapp_course_id, payload_json)
      VALUES (?, ?, ?, ?)
    `,
    )
      .bind(event, data.userId, data.courseId, JSON.stringify(body))
      .run();

    const eventoId = eventoResult.meta.last_row_id;

    // Só processar conclusão
    if (event !== 'CourseCompletedEvent' && event !== 'course.completed') {
      await c.env.DB.prepare(`UPDATE integracoes_edapp_eventos SET processado = 1 WHERE id = ?`)
        .bind(eventoId)
        .run();
      return c.json({ success: true, message: 'Evento ignorado', evento_id: eventoId });
    }

    // Mapear usuário
    const funcionario = await findFuncionarioByEdappUser(c.env.DB, data.userId);
    if (!funcionario?.funcionario_id) {
      await c.env.DB.prepare(
        `
        UPDATE integracoes_edapp_eventos SET erro_ultima = ?, tentativas = tentativas + 1 WHERE id = ?
      `,
      )
        .bind('Usuário não mapeado', eventoId)
        .run();
      return c.json({ success: false, error: 'Usuário não mapeado', evento_id: eventoId }, 400);
    }

    // Mapear curso
    const qualificacao = await findQualificacaoByCourse(c.env.DB, data.courseId);
    if (!qualificacao?.qualificacao_codigo) {
      await c.env.DB.prepare(
        `
        UPDATE integracoes_edapp_eventos SET erro_ultima = ?, tentativas = tentativas + 1 WHERE id = ?
      `,
      )
        .bind('Curso não mapeado', eventoId)
        .run();
      return c.json({ success: false, error: 'Curso não mapeado', evento_id: eventoId }, 400);
    }

    // Gerar qualificação
    const resultado = await createQualificacao(
      c.env.DB,
      funcionario.funcionario_id,
      qualificacao.qualificacao_codigo,
      `course_id:${data.courseId}`,
      data.completedAt, // Passar data de conclusão do EdApp
    );

    // Marcar processado E atualizar funcionario_id e qualificacao_historico_id
    await c.env.DB.prepare(
      `UPDATE integracoes_edapp_eventos 
       SET processado = 1, 
           funcionario_id = ?,
           qualificacao_historico_id = ?,
           updated_at = datetime('now')
       WHERE id = ?`,
    )
      .bind(funcionario.funcionario_id, resultado.qualificacao_id, eventoId)
      .run();

    // 🔔 CRIAR NOTIFICAÇÃO AUTOMÁTICA
    const grupoNotificacao = `edapp_${new Date().toISOString().split('T')[0]}`;
    await c.env.DB.prepare(
      `INSERT INTO notificacoes_sistema (
        tipo, prioridade, titulo, mensagem, dados, grupo,
        funcionario_id, qualificacao_historico_id, link, acao_primaria,
        created_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))`,
    )
      .bind(
        'EDAPP_QUALIFICACAO',
        'MEDIA',
        '✅ Treinamento EdApp Concluído',
        `${funcionario.funcionario_nome} concluiu o treinamento ${qualificacao.edapp_course_name || qualificacao.qualificacao_codigo}`,
        JSON.stringify({
          funcionario_id: funcionario.funcionario_id,
          funcionario_nome: funcionario.funcionario_nome,
          qualificacao_codigo: qualificacao.qualificacao_codigo,
          data_conclusao: data.completedAt,
          score: data.score,
          courseId: data.courseId,
          renovacao: resultado.renovacao || false,
        }),
        grupoNotificacao,
        funcionario.funcionario_id,
        resultado.qualificacao_id,
        `/qualificacoes?id=${resultado.qualificacao_id}`,
        'Ver Qualificação',
      )
      .run();

    return c.json({
      success: true,
      data: {
        evento_id: eventoId,
        funcionario_id: funcionario.funcionario_id,
        qualificacao_codigo: qualificacao.qualificacao_codigo,
        qualificacao_id: resultado.qualificacao_id,
        qualificacao_criada: resultado.success,
      },
    });
  } catch (error: any) {
    console.error('Webhook EdApp erro:', error);
    return c.json({ success: false, error: error.message }, 500);
  }
});

// ========================================
// ENDPOINT: CRIAR WEBHOOK NO EDAPP AUTOMATICAMENTE
// POST /api/integracoes/edapp/setup-webhook
// ========================================

edappRouter.post('/setup-webhook', async (c: Context) => {
  try {
    // Construir URL do webhook (usar URL da API em produção)
    const baseUrl = new URL(c.req.url);
    const webhookUrl = `${baseUrl.protocol}//${baseUrl.host}/api/integracoes/edapp/webhook`;

    // Validar que temos o token
    if (!c.env.EDAPP_API_TOKEN) {
      throw new Error('EDAPP_API_TOKEN não configurado');
    }

    if (!c.env.EDAPP_WEBHOOK_SECRET) {
      throw new Error('EDAPP_WEBHOOK_SECRET não configurado');
    }

    // Criar webhook no EdApp seguindo documentação v2
    // Ref: https://rest.edapp.com/v2/webhooks
    // Campos obrigatórios: WebHookUrl, EventName (case-sensitive)
    const webhookPayload = {
      WebHookUrl: webhookUrl,
      EventName: 'CourseCompletedEvent',
      IsActive: true,
    };

    // Fazer chamada direta para tratar 409 especialmente
    const apiUrl = 'https://rest.edapp.com/v2/webhooks';
    const response = await fetch(apiUrl, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${c.env.EDAPP_API_TOKEN}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(webhookPayload),
    });

    const responseText = await response.text();

    // Tratar webhook já existente (409 Conflict)
    if (response.status === 409) {
      // Buscar webhooks existentes
      const listResponse = await fetch('https://rest.edapp.com/v2/webhooks', {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${c.env.EDAPP_API_TOKEN}`,
        },
      });
      const webhooks = (await listResponse.json()) as Array<{ id?: string; webHookUrl?: string }>;

      // Encontrar o webhook que corresponde à nossa URL
      const ourWebhook = webhooks.find((w) => w.webHookUrl === webhookUrl);
      if (ourWebhook?.id) {
        // Salvar ID do webhook existente
        await c.env.DB.prepare(
          `INSERT OR REPLACE INTO integracoes_edapp_config (chave, valor, updated_at)
           VALUES ('webhook_id', ?, datetime('now'))`,
        )
          .bind(String(ourWebhook.id))
          .run();
      }

      return c.json({
        success: true,
        data: {
          webhook_id: ourWebhook?.id || null,
          webhook_url: webhookUrl,
          message: 'Webhook já está configurado no EdApp',
          existing_webhooks: webhooks,
        },
      });
    }

    if (!response.ok) {
      console.error(`EdApp webhook error [${response.status}]:`, responseText);
      return c.json(
        {
          success: false,
          error: `EdApp API Error: ${response.status} - ${responseText}`,
          details: `Error: EdApp API Error: ${response.status} - ${responseText}`,
        },
        500,
      );
    }

    let result;
    try {
      result = JSON.parse(responseText);
    } catch {
      result = { raw: responseText };
    }

    // Salvar ID do webhook - EdApp pode retornar diferentes formatos
    const resultData = result as Record<string, unknown>;
    const webhookId =
      resultData.Id ||
      resultData.id ||
      resultData.WebHookId ||
      resultData.webhookId ||
      (resultData.data as Record<string, unknown> | undefined)?.id ||
      (resultData.data as Record<string, unknown> | undefined)?.Id;

    if (!webhookId) {
      console.error('❌ Resposta EdApp sem ID reconhecido:', JSON.stringify(result, null, 2));
      // Se não houver ID mas a resposta foi OK, retornar sucesso com aviso
      return c.json({
        success: true,
        data: {
          webhook_url: webhookUrl,
          raw_response: result,
          warning: 'Webhook possivelmente criado, mas ID não encontrado na resposta',
        },
      });
    }

    await c.env.DB.prepare(
      `
      INSERT OR REPLACE INTO integracoes_edapp_config (chave, valor, updated_at)
      VALUES ('webhook_id', ?, datetime('now'))
    `,
    )
      .bind(String(webhookId))
      .run();

    return c.json({ success: true, data: { webhook_id: webhookId, webhook_url: webhookUrl } });
  } catch (error: any) {
    console.error('❌ Erro ao criar webhook:', error);
    return c.json({ success: false, error: error.message, details: error.toString() }, 500);
  }
});

// ========================================
// ENDPOINT: DELETAR WEBHOOK DO EDAPP
// DELETE /api/integracoes/edapp/webhook-config
// ========================================

edappRouter.delete('/webhook-config', async (c: Context) => {
  try {
    const config = await c.env.DB.prepare(
      `
      SELECT valor FROM integracoes_edapp_config WHERE chave = 'webhook_id'
    `,
    ).first<{ valor: string }>();

    if (!config?.valor) {
      return c.json({ success: false, error: 'Webhook não configurado' }, 404);
    }

    await callEdAppAPI(c.env, 'DELETE', `/v2/webhooks/${config.valor}`);

    await c.env.DB.prepare(
      `
      DELETE FROM integracoes_edapp_config WHERE chave = 'webhook_id'
    `,
    ).run();

    return c.json({ success: true, message: 'Webhook removido' });
  } catch (error: any) {
    console.error('Erro ao deletar webhook:', error);
    return c.json({ success: false, error: error.message }, 500);
  }
});

