// ========================================
// ENDPOINT: CRIAR EVENTO DE TESTE
// POST /api/integracoes/edapp/teste
// ========================================

edappRouter.post('/teste', async (c) => {
  try {
    const body = await c.req.json();
    const { edapp_user_id, edapp_course_id } = body;

    if (!edapp_user_id || !edapp_course_id) {
      return c.json(
        { success: false, error: 'edapp_user_id e edapp_course_id são obrigatórios' },
        400,
      );
    }

    // Verificar se o usuário está mapeado
    const usuarioMapeado = await findFuncionarioByEdappUser(c.env.DB, edapp_user_id);
    if (!usuarioMapeado?.funcionario_id) {
      return c.json(
        { success: false, error: `Usuário EdApp ${edapp_user_id} não está mapeado` },
        400,
      );
    }

    // Verificar se o curso está mapeado
    const cursoMapeado = await findQualificacaoByCourse(c.env.DB, edapp_course_id);
    if (!cursoMapeado?.qualificacao_codigo) {
      return c.json(
        { success: false, error: `Curso EdApp ${edapp_course_id} não está mapeado` },
        400,
      );
    }

    // Criar evento de teste
    const testPayload = {
      event: 'CourseCompletedEvent',
      data: {
        userId: edapp_user_id,
        courseId: edapp_course_id,
        completedAt: new Date().toISOString(),
        score: 100,
        username: 'TESTE_USER',
        email: 'teste@edapp.com',
      },
    };

    // Log evento
    const eventoResult = await c.env.DB.prepare(
      `
      INSERT INTO integracoes_edapp_eventos (tipo_evento, edapp_user_id, edapp_course_id, payload_json)
      VALUES (?, ?, ?, ?)
    `,
    )
      .bind('CourseCompletedEvent', edapp_user_id, edapp_course_id, JSON.stringify(testPayload))
      .run();

    const eventoId = eventoResult.meta.last_row_id;

    // Gerar qualificação (usa data do payload de teste)
    const resultado = await createQualificacao(
      c.env.DB,
      usuarioMapeado.funcionario_id,
      cursoMapeado.qualificacao_codigo,
      `test_course:${edapp_course_id}`,
      testPayload.data.completedAt, // Usar data do payload de teste
    );

    // Marcar processado e associar qualificacao_historico_id
    await c.env.DB.prepare(
      `UPDATE integracoes_edapp_eventos 
       SET processado = 1, 
           qualificacao_historico_id = ?,
           funcionario_id = ?
       WHERE id = ?`,
    )
      .bind(resultado.qualificacao_id || null, usuarioMapeado.funcionario_id, eventoId)
      .run();

    return c.json({
      success: true,
      message: '✅ Evento de teste criado e qualificação gerada! Verifique o histórico.',
      data: {
        evento_id: eventoId,
        funcionario_id: usuarioMapeado.funcionario_id,
        qualificacao_codigo: cursoMapeado.qualificacao_codigo,
        qualificacao_criada: resultado.success,
        mensagem_qualificacao: resultado.message,
      },
    });
  } catch (error: any) {
    console.error('❌ Erro ao criar evento de teste:', error);
    return c.json({ success: false, error: error.message }, 500);
  }
});

// ========================================
// ENDPOINT: LISTAR CURSOS CONCLUÍDOS (READ-ONLY)
// GET /api/integracoes/edapp/conclusoes
// ========================================

edappRouter.get('/conclusoes', async (c) => {
  try {
    const limit = parseInt(c.req.query('limit') || '100');
    const offset = parseInt(c.req.query('offset') || '0');

    const conclusoes = await c.env.DB.prepare(
      `
      SELECT 
        e.id,
        e.tipo_evento,
        e.edapp_user_id,
        e.edapp_course_id,
        e.payload_json,
        e.processado,
        e.created_at,
        u.funcionario_id,
        f.matricula,
        f.nome as funcionario_nome,
        c.edapp_course_name,
        c.edapp_course_code,
        c.qualificacao_codigo,
        tq.nome as qualificacao_nome
      FROM integracoes_edapp_eventos e
      LEFT JOIN integracoes_edapp_usuarios u ON e.edapp_user_id = u.edapp_user_id AND u.deleted_at IS NULL
      LEFT JOIN funcionarios f ON u.funcionario_id = f.id AND f.deleted_at IS NULL
      LEFT JOIN integracoes_edapp_cursos c ON e.edapp_course_id = c.edapp_course_id AND c.deleted_at IS NULL
      LEFT JOIN qualificacoes_tipos tq ON c.qualificacao_codigo = tq.codigo AND tq.deleted_at IS NULL
      WHERE e.deleted_at IS NULL
        AND e.tipo_evento IN ('CourseCompletedEvent', 'course.completed')
      ORDER BY e.created_at DESC
      LIMIT ? OFFSET ?
    `,
    )
      .bind(limit, offset)
      .all();

    // Parse payload_json para cada evento
    const conclusoesComParsed = (conclusoes.results || []).map((evt: any) => {
      let parsedData = null;
      try {
        const parsed = JSON.parse(evt.payload_json || '{}');
        parsedData = parsed.data || parsed;
      } catch {
        // Ignora erros de parse
      }

      return {
        id: evt.id,
        tipo_evento: evt.tipo_evento,
        edapp_user_id: evt.edapp_user_id,
        edapp_course_id: evt.edapp_course_id,
        processado: evt.processado === 1,
        created_at: evt.created_at,
        completedAt: parsedData?.completedAt || evt.created_at,
        score: parsedData?.score,
        funcionario_id: evt.funcionario_id,
        funcionario_matricula: evt.matricula,
        funcionario_nome: evt.funcionario_nome,
        curso_nome: evt.edapp_course_name,
        curso_codigo: evt.edapp_course_code,
        qualificacao_codigo: evt.qualificacao_codigo,
        qualificacao_nome: evt.qualificacao_nome,
        mapeado: !!(evt.funcionario_id && evt.qualificacao_codigo),
      };
    });

    const total = await c.env.DB.prepare(
      `
      SELECT COUNT(*) as total
      FROM integracoes_edapp_eventos
      WHERE deleted_at IS NULL
        AND tipo_evento IN ('CourseCompletedEvent', 'course.completed')
    `,
    ).first<{ total: number }>();

    return c.json({
      success: true,
      data: conclusoesComParsed,
      pagination: {
        limit,
        offset,
        total: total?.total || 0,
      },
    });
  } catch (error: any) {
    console.error('Erro ao buscar conclusões:', error.message);
    return c.json({ success: false, error: error.message || 'Erro ao buscar conclusões' }, 500);
  }
});

// ========================================
// POST /api/integracoes/edapp/importar-historico
// Importa histórico de conclusões do EdApp via API
// ========================================

edappRouter.post('/importar-historico', async (c: Context) => {
  const db = c.env.DB;
  let novasCriadas = 0;
  let renovadas = 0;
  let ignoradas = 0;
  let erros = 0;
  const detalhes: any[] = [];

  try {
    // 1. Buscar TODOS os eventos de conclusão de curso dos webhooks NÃO PROCESSADOS
    // (não usamos API porque ela não retorna status/completedAt)
    const eventosResult = await db
      .prepare(
        `
      SELECT DISTINCT
        e.id as evento_id,
        e.edapp_user_id,
        e.edapp_course_id,
        e.payload_json,
        e.created_at,
        u.funcionario_id,
        f.nome as funcionario_nome,
        f.matricula,
        c.qualificacao_codigo,
        c.edapp_course_name
      FROM integracoes_edapp_eventos e
      LEFT JOIN integracoes_edapp_usuarios u 
        ON e.edapp_user_id = u.edapp_user_id AND u.deleted_at IS NULL
      LEFT JOIN funcionarios f 
        ON u.funcionario_id = f.id AND f.deleted_at IS NULL
      LEFT JOIN integracoes_edapp_cursos c 
        ON e.edapp_course_id = c.edapp_course_id AND c.deleted_at IS NULL
      WHERE e.tipo_evento IN ('CourseCompletedEvent', 'course.completed')
        AND e.deleted_at IS NULL
        AND e.processado = 0
        AND u.funcionario_id IS NOT NULL
        AND c.qualificacao_codigo IS NOT NULL
      ORDER BY e.created_at ASC
    `,
      )
      .all<{
        evento_id: number;
        edapp_user_id: string;
        edapp_course_id: string;
        payload_json: string;
        created_at: string;
        funcionario_id: number;
        funcionario_nome: string;
        matricula: string;
        qualificacao_codigo: string;
        edapp_course_name: string;
      }>();

    const eventos = eventosResult.results || [];

    // 2. Para cada evento de conclusão
    for (const evento of eventos) {
      try {
        // Extrair completedAt do payload
        let completedAt: string | undefined;
        try {
          const payload = JSON.parse(evento.payload_json);
          completedAt = payload.data?.completedAt || payload.completedAt;
        } catch {
          completedAt = evento.created_at; // Fallback: usar data do evento
        }

        if (!completedAt) continue;

        const dataConclusao = new Date(completedAt).toISOString().split('T')[0];

        // 3. Verificar se já existe qualificação com essa data exata
        const qualificacaoExistente = await db
          .prepare(
            `
            SELECT id 
            FROM qualificacoes_historico 
            WHERE funcionario_id = ? 
              AND qualificacao_codigo = ? 
              AND data_conclusao = ?
              AND deleted_at IS NULL
          `,
          )
          .bind(evento.funcionario_id, evento.qualificacao_codigo, dataConclusao)
          .first<{ id: number }>();

        if (qualificacaoExistente) {
          detalhes.push({
            funcionario: evento.funcionario_nome,
            matricula: evento.matricula,
            curso: evento.edapp_course_name,
            qualificacao: evento.qualificacao_codigo,
            data_conclusao: dataConclusao,
            status: 'já_existe',
            motivo: 'Qualificação já registrada com essa data',
          });
          ignoradas++;
          continue;
        }

        // 4. Verificar se existe qualificação válida para renovar
        const qualificacaoRenovavel = await db
          .prepare(
            `
            SELECT id, data_vencimento 
            FROM qualificacoes_historico 
            WHERE funcionario_id = ? 
              AND qualificacao_codigo = ? 
              AND data_vencimento >= date('now')
              AND deleted_at IS NULL
            ORDER BY data_vencimento DESC
            LIMIT 1
          `,
          )
          .bind(evento.funcionario_id, evento.qualificacao_codigo)
          .first<{ id: number; data_vencimento: string }>();

        if (qualificacaoRenovavel) {
          // RENOVAR: criar nova qualificação
          const resultado = await renovarQualificacao(
            db,
            evento.funcionario_id,
            evento.qualificacao_codigo,
            `Renovação EdApp: ${evento.edapp_course_name}`,
            completedAt,
          );

          if (resultado.success) {
            // Marcar evento como processado
            await db
              .prepare(
                `UPDATE integracoes_edapp_eventos 
                 SET processado = 1, 
                     qualificacao_historico_id = ?,
                     updated_at = datetime('now')
                 WHERE id = ?`,
              )
              .bind(resultado.qualificacao_id, evento.evento_id)
              .run();

            detalhes.push({
              funcionario: evento.funcionario_nome,
              matricula: evento.matricula,
              curso: evento.edapp_course_name,
              qualificacao: evento.qualificacao_codigo,
              data_conclusao: dataConclusao,
              status: 'renovada',
              qualificacao_antiga_id: qualificacaoRenovavel.id,
              qualificacao_nova_id: resultado.qualificacao_id,
            });
            renovadas++;
          } else {
            detalhes.push({
              funcionario: evento.funcionario_nome,
              curso: evento.edapp_course_name,
              status: 'erro',
              motivo: resultado.message,
            });
            erros++;
          }
        } else {
          // CRIAR nova qualificação
          const resultado = await createQualificacao(
            db,
            evento.funcionario_id,
            evento.qualificacao_codigo,
            `Importação histórico: ${evento.edapp_course_name}`,
            completedAt,
          );

          if (resultado.success) {
            // Marcar evento como processado
            await db
              .prepare(
                `UPDATE integracoes_edapp_eventos 
                 SET processado = 1, 
                     qualificacao_historico_id = ?,
                     updated_at = datetime('now')
                 WHERE id = ?`,
              )
              .bind(resultado.qualificacao_id, evento.evento_id)
              .run();

            detalhes.push({
              funcionario: evento.funcionario_nome,
              matricula: evento.matricula,
              curso: evento.edapp_course_name,
              qualificacao: evento.qualificacao_codigo,
              data_conclusao: dataConclusao,
              status: 'criada',
              qualificacao_id: resultado.qualificacao_id,
            });
            novasCriadas++;
          } else {
            detalhes.push({
              funcionario: evento.funcionario_nome,
              curso: evento.edapp_course_name,
              status: 'erro',
              motivo: resultado.message,
            });
            erros++;
          }
        }
      } catch (eventoError: any) {
        console.error(`Erro ao processar evento:`, eventoError);
        erros++;
      }
    }

    const usuariosProcessados = new Set(
      eventos.map((e: { funcionario_id: number }) => e.funcionario_id),
    ).size;

    return c.json({
      success: true,
      data: {
        resumo: {
          usuarios_processados: usuariosProcessados,
          novas_criadas: novasCriadas,
          renovadas: renovadas,
          ignoradas: ignoradas,
          erros: erros,
          total: novasCriadas + renovadas + ignoradas + erros,
        },
        detalhes: detalhes,
      },
    });
  } catch (error: any) {
    console.error('Erro ao importar histórico EdApp:', error);
    return c.json(
      {
        success: false,
        error: error.message || 'Erro ao importar histórico',
        detalhes: detalhes,
      },
      500,
    );
  }
});

