// ============================================================
// AIRTRUST - FASE 4: COMPLIANCE (Cálculo de Status)
// ============================================================
// Endpoints:
//  1. GET /api/funcionarios/:id/compliance - status individual
//  2. GET /api/compliance/funcionarios - lista de todos
// ============================================================

import { Hono } from 'hono';
import type { Context } from 'hono';
import { parseISO, differenceInDays } from 'date-fns';
import { getFicha360 } from './ficha360';

type Env = {
  DB: D1Database;
};

const app = new Hono<{ Bindings: Env }>();

// ============================================================
// Tipos
// ============================================================

type RequisitoStatus = 'ok' | 'risco' | 'faltando';
type ComplianceStatus = 'conforme' | 'em_risco' | 'nao_conforme';

interface RequisitoCompliance {
  id: number;
  funcao: string;
  tipo_recurso: 'qualificacao' | 'licenca';
  referencia: string;
  descricao?: string;
  status: RequisitoStatus;
  dias_restantes: number | null;
}

interface ComplianceResult {
  funcionario: Record<string, unknown>;
  status: ComplianceStatus;
  requisitos: RequisitoCompliance[];
}

// ============================================================
// Função auxiliar: calcular status de compliance
// ============================================================

function calcularStatusRequisito(
  req: Record<string, unknown>,
  qualificacoes: Array<Record<string, unknown>>,
  licencas: Array<Record<string, unknown>>,
  hoje: Date,
): RequisitoCompliance {
  const baseReq = {
    id: req.id as number,
    funcao: req.funcao as string,
    tipo_recurso: req.tipo_recurso as 'qualificacao' | 'licenca',
    referencia: req.referencia as string,
    descricao: req.descricao as string | undefined,
  };

  if (req.tipo_recurso === 'qualificacao') {
    // Buscar qualificação com codigo = referencia
    const qual = qualificacoes.find((q) => q.codigo === req.referencia);

    if (!qual || !qual.data_vencimento) {
      return { ...baseReq, status: 'faltando', dias_restantes: null };
    }

    const dtVenc = parseISO(qual.data_vencimento as string);
    const dias = differenceInDays(dtVenc, hoje);

    if (dias < 0) {
      return { ...baseReq, status: 'faltando', dias_restantes: dias };
    }
    if (dias <= 60) {
      return { ...baseReq, status: 'risco', dias_restantes: dias };
    }
    return { ...baseReq, status: 'ok', dias_restantes: dias };
  }

  if (req.tipo_recurso === 'licenca') {
    // Buscar licença com tipo = referencia
    const lic = licencas.find((l) => l.tipo === req.referencia);

    if (!lic || !lic.data_vencimento) {
      return { ...baseReq, status: 'faltando', dias_restantes: null };
    }

    const dtVenc = parseISO(lic.data_vencimento as string);
    const dias = differenceInDays(dtVenc, hoje);

    if (dias < 0) {
      return { ...baseReq, status: 'faltando', dias_restantes: dias };
    }
    if (dias <= 60) {
      return { ...baseReq, status: 'risco', dias_restantes: dias };
    }
    return { ...baseReq, status: 'ok', dias_restantes: dias };
  }

  // Tipo desconhecido (evitar crash)
  return { ...baseReq, status: 'faltando', dias_restantes: null };
}

function calcularStatusGlobal(requisitos: RequisitoCompliance[]): ComplianceStatus {
  const temFaltando = requisitos.some((r) => r.status === 'faltando');
  const temRisco = requisitos.some((r) => r.status === 'risco');

  if (temFaltando) return 'nao_conforme';
  if (temRisco) return 'em_risco';
  return 'conforme';
}

// ============================================================
// GET /api/funcionarios/:id/compliance
// ============================================================

app.get('/funcionarios/:id/compliance', async (c: Context<{ Bindings: Env }>) => {
  try {
    const id = Number(c.req.param('id'));

    if (Number.isNaN(id)) {
      return c.json({ error: 'ID inválido' }, 400);
    }

    const ficha = await getFicha360(c.env.DB, id);

    if (!ficha) {
      return c.json({ error: 'Funcionário não encontrado' }, 404);
    }

    const hoje = new Date();

    const requisitos = (ficha.requisitos as Array<Record<string, unknown>>).map((req) =>
      calcularStatusRequisito(
        req,
        ficha.qualificacoes as Array<Record<string, unknown>>,
        ficha.licencas as Array<Record<string, unknown>>,
        hoje,
      ),
    );

    const statusGlobal = calcularStatusGlobal(requisitos);

    const result: ComplianceResult = {
      funcionario: ficha.funcionario as Record<string, unknown>,
      status: statusGlobal,
      requisitos,
    };

    return c.json({
      success: true,
      data: result,
    });
  } catch (error) {
    console.error('Erro ao calcular compliance:', error);
    return c.json(
      {
        success: false,
        error: 'Erro ao calcular compliance',
      },
      500,
    );
  }
});

// ============================================================
// GET /api/compliance/funcionarios?funcao=&base=
// ============================================================

app.get('/compliance/funcionarios', async (c: Context<{ Bindings: Env }>) => {
  try {
    const funcao = c.req.query('funcao') ?? '';
    const base = c.req.query('base') ?? '';

    console.log('[Compliance] Listando compliance de funcionários', { funcao, base });

    // Buscar todos funcionários com filtros (APENAS ATIVOS)
    let query = `SELECT id, nome, matricula, funcao, NULL as base FROM funcionarios WHERE deleted_at IS NULL AND ativo = 1`;
    const params: unknown[] = [];

    if (funcao) {
      query += ` AND funcao = ?`;
      params.push(funcao);
    }
    if (base) {
      // Base não existe na tabela, ignorar filtro
    }
    query += ` ORDER BY nome`;

    const stmt = await c.env.DB.prepare(query)
      .bind(...params)
      .all();

    if (!stmt.success || !stmt.results) {
      console.error('[Compliance] Erro ao buscar funcionários:', stmt.error);
      return c.json({ success: false, error: 'Erro ao buscar funcionários' }, 500);
    }

    const funcionarios = stmt.results as Array<Record<string, unknown>>;
    console.log(`[Compliance] Encontrados ${funcionarios.length} funcionários`);

    const hoje = new Date();
    const resultados: Array<{
      funcionario_id: string;
      nome_completo: string;
      matricula: string;
      funcao: string;
      base: string | null;
      status: ComplianceStatus;
    }> = [];

    for (const f of funcionarios) {
      try {
        const ficha = await getFicha360(c.env.DB, Number(f.id));
        if (!ficha) {
          console.warn(`[Compliance] Ficha não encontrada para funcionário ${f.id}`);
          continue;
        }

        const requisitos = (ficha.requisitos as Array<Record<string, unknown>>).map((req) =>
          calcularStatusRequisito(
            req,
            ficha.qualificacoes as Array<Record<string, unknown>>,
            ficha.licencas as Array<Record<string, unknown>>,
            hoje,
          ),
        );

        const status = calcularStatusGlobal(requisitos);

        resultados.push({
          funcionario_id: String(f.id),
          nome_completo: f.nome as string,
          matricula: f.matricula as string,
          funcao: f.funcao as string,
          base: f.base as string | null,
          status,
        });
      } catch (err) {
        console.error(`[Compliance] Erro ao processar funcionário ${f.id}:`, err);
        // Continua para o próximo funcionário
      }
    }

    return c.json({
      success: true,
      data: resultados,
      total: resultados.length,
    });
  } catch (error) {
    console.error('Erro ao listar compliance:', error);
    return c.json(
      {
        success: false,
        error: 'Erro ao listar compliance',
      },
      500,
    );
  }
});

export default app;
