/**
 * IMPORTAÇÃO XLSX - Sistema completo para 3 tabelas
 *
 * Endpoints:
 * - POST /api/importacao-xlsx/funcionarios
 * - POST /api/importacao-xlsx/historico
 * - POST /api/importacao-xlsx/tipos
 *
 * Modos:
 * - "completar": Adiciona novos registros, atualiza existentes
 * - "substituir": Remove todos e insere os novos (com confirmação)
 */

import { Hono } from 'hono';
import type { Env } from '../types';
import { auth } from '../middleware/auth';
import ExcelJS from 'exceljs';

const app = new Hono<{ Bindings: Env }>();

// ===== TIPOS =====

interface ImportResult {
  success: boolean;
  mode: string;
  totalRows: number;
  inserted: number;
  updated: number;
  deleted?: number;
  errors: Array<{
    linha: number;
    erro: string;
    dados?: Record<string, any>;
  }>;
}

// ===== HELPER: Parse XLSX =====

async function parseXLSXFile(fileBuffer: ArrayBuffer): Promise<any[]> {
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.load(fileBuffer);

  const worksheet = workbook.worksheets[0];
  if (!worksheet) {
    throw new Error('Planilha vazia ou inválida');
  }

  const rows: any[] = [];
  const headers: string[] = [];

  worksheet.eachRow((row, rowNumber) => {
    if (rowNumber === 1) {
      // Headers
      row.eachCell((cell) => {
        headers.push(String(cell.value || '').trim());
      });
    } else {
      // Data rows
      const rowData: Record<string, any> = {};
      row.eachCell((cell, colNumber) => {
        const header = headers[colNumber - 1];
        if (header) {
          let value = cell.value;

          // Handle Excel dates
          if (value instanceof Date) {
            value = value.toISOString().split('T')[0];
          } else if (typeof value === 'object' && value !== null && 'result' in value) {
            value = value.result;
          }

          rowData[header] = value;
        }
      });

      // Só adiciona se tiver pelo menos um campo preenchido
      if (Object.values(rowData).some((v) => v !== null && v !== undefined && v !== '')) {
        rows.push(rowData);
      }
    }
  });

  return rows;
}

// ===== FUNCIONÁRIOS =====

/**
 * POST /api/importacao-xlsx/funcionarios
 * Body: FormData com arquivo "file" e campo "mode" (completar|substituir)
 */
app.post('/funcionarios', auth(), async (c) => {
  try {
    const formData = await c.req.formData();
    const file = formData.get('file') as File;
    const mode = (formData.get('mode') as string) || 'completar';

    if (!file) {
      return c.json({ success: false, error: 'Arquivo não enviado' }, 400);
    }

    // Parse XLSX
    const buffer = await file.arrayBuffer();
    const rows = await parseXLSXFile(buffer);

    if (rows.length === 0) {
      return c.json({ success: false, error: 'Planilha vazia' }, 400);
    }

    const db = c.env.DB;
    const errors: any[] = [];
    let inserted = 0;
    let updated = 0;
    let deleted = 0;

    // Modo SUBSTITUIR: deletar tudo primeiro
    if (mode === 'substituir') {
      const deleteResult = await db
        .prepare(`UPDATE funcionarios SET deleted_at = datetime('now') WHERE deleted_at IS NULL`)
        .run();
      deleted = deleteResult.meta.changes || 0;
    }

    // Processar cada linha
    for (let i = 0; i < rows.length; i++) {
      const row = rows[i];
      const linha = i + 2; // +2 porque linha 1 é header e arrays começam em 0

      try {
        // Validar campos obrigatórios
        if (!row.Nome || !row.CPF) {
          errors.push({
            linha,
            erro: 'Nome e CPF são obrigatórios',
            dados: row,
          });
          continue;
        }

        // Buscar modelo_aeronave_id se tiver aeronave
        let modeloAeronaveId = null;
        if (row.Aeronave) {
          const modeloResult = await db
            .prepare(
              `SELECT id FROM modelos_aeronave 
               WHERE deleted_at IS NULL 
               AND (modelo = ? OR codigo = ? OR nome = ?)
               LIMIT 1`,
            )
            .bind(row.Aeronave, row.Aeronave, row.Aeronave)
            .first();

          if (modeloResult) {
            modeloAeronaveId = modeloResult.id;
          }
        }

        // Verificar se já existe (por CPF)
        const existente = await db
          .prepare(`SELECT id FROM funcionarios WHERE cpf = ? AND deleted_at IS NULL`)
          .bind(row.CPF)
          .first();

        if (existente) {
          // UPDATE
          await db
            .prepare(
              `UPDATE funcionarios SET
                nome = ?,
                matricula = ?,
                email = ?,
                telefone = ?,
                nascimento = ?,
                admissao = ?,
                cargo = ?,
                funcao = ?,
                modelo_aeronave_id = ?,
                codigo_anac = ?,
                licenca = ?,
                is_instrutor = ?,
                is_examinador = ?,
                ativo = ?,
                updated_at = datetime('now')
              WHERE id = ?`,
            )
            .bind(
              row.Nome,
              row['Matrícula'] || null,
              row.Email || null,
              row.Telefone || null,
              row.Nascimento || null,
              row['Admissão'] || null,
              row.Cargo || null,
              row['Função'] || null,
              modeloAeronaveId,
              row['Código ANAC'] || null,
              row['Licença'] || null,
              row.Instrutor === 'Sim' ? 1 : 0,
              row.Examinador === 'Sim' ? 1 : 0,
              row.Ativo === 'Sim' ? 1 : 0,
              existente.id,
            )
            .run();

          updated++;
        } else {
          // INSERT
          await db
            .prepare(
              `INSERT INTO funcionarios (
                nome, cpf, matricula, email, telefone, nascimento, admissao,
                cargo, funcao, modelo_aeronave_id, codigo_anac, licenca,
                is_instrutor, is_examinador, ativo, created_at, updated_at
              ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))`,
            )
            .bind(
              row.Nome,
              row.CPF,
              row['Matrícula'] || null,
              row.Email || null,
              row.Telefone || null,
              row.Nascimento || null,
              row['Admissão'] || null,
              row.Cargo || null,
              row['Função'] || null,
              modeloAeronaveId,
              row['Código ANAC'] || null,
              row['Licença'] || null,
              row.Instrutor === 'Sim' ? 1 : 0,
              row.Examinador === 'Sim' ? 1 : 0,
              row.Ativo === 'Sim' ? 1 : 0,
            )
            .run();

          inserted++;
        }
      } catch (err: any) {
        errors.push({
          linha,
          erro: err.message || String(err),
          dados: row,
        });
      }
    }

    const result: ImportResult = {
      success: errors.length === 0,
      mode,
      totalRows: rows.length,
      inserted,
      updated,
      deleted: mode === 'substituir' ? deleted : undefined,
      errors,
    };

    return c.json(result);
  } catch (error: any) {
    console.error('[IMPORT XLSX FUNCIONARIOS] Erro:', error);
    return c.json({ success: false, error: error.message }, 500);
  }
});

// ===== HISTÓRICO =====

/**
 * POST /api/importacao-xlsx/historico
 */
app.post('/historico', auth(), async (c) => {
  try {
    const formData = await c.req.formData();
    const file = formData.get('file') as File;
    const mode = (formData.get('mode') as string) || 'completar';

    if (!file) {
      return c.json({ success: false, error: 'Arquivo não enviado' }, 400);
    }

    const buffer = await file.arrayBuffer();
    const rows = await parseXLSXFile(buffer);

    if (rows.length === 0) {
      return c.json({ success: false, error: 'Planilha vazia' }, 400);
    }

    const db = c.env.DB;
    const errors: any[] = [];
    let inserted = 0;
    let updated = 0;
    let deleted = 0;

    // Modo SUBSTITUIR
    if (mode === 'substituir') {
      const deleteResult = await db
        .prepare(
          `UPDATE qualificacoes_historico SET deleted_at = datetime('now') WHERE deleted_at IS NULL`,
        )
        .run();
      deleted = deleteResult.meta.changes || 0;
    }

    // Processar cada linha
    for (let i = 0; i < rows.length; i++) {
      const row = rows[i];
      const linha = i + 2;

      try {
        // Validar campos obrigatórios
        if (!row['Funcionário'] || !row['Qualificação']) {
          errors.push({
            linha,
            erro: 'Funcionário e Qualificação são obrigatórios',
            dados: row,
          });
          continue;
        }

        // Buscar funcionario_id
        const funcionarioNome = row['Funcionário'];
        const funcionario = await db
          .prepare(`SELECT id FROM funcionarios WHERE nome = ? AND deleted_at IS NULL LIMIT 1`)
          .bind(funcionarioNome)
          .first();

        if (!funcionario) {
          errors.push({
            linha,
            erro: `Funcionário não encontrado: ${funcionarioNome}`,
            dados: row,
          });
          continue;
        }

        // Buscar tipo_qualificacao_id
        const qualificacaoNome = row['Qualificação'];
        const tipoQualificacao = await db
          .prepare(
            `SELECT id FROM tipos_qualificacoes WHERE nome = ? AND deleted_at IS NULL LIMIT 1`,
          )
          .bind(qualificacaoNome)
          .first();

        if (!tipoQualificacao) {
          errors.push({
            linha,
            erro: `Tipo de qualificação não encontrado: ${qualificacaoNome}`,
            dados: row,
          });
          continue;
        }

        // Verificar se já existe
        const existente = await db
          .prepare(
            `SELECT id FROM qualificacoes_historico 
             WHERE funcionario_id = ? AND tipo_qualificacao_id = ? 
             AND data_conclusao = ? AND deleted_at IS NULL`,
          )
          .bind(funcionario.id, tipoQualificacao.id, row['Data Conclusão'])
          .first();

        const campos = {
          funcionario_id: funcionario.id,
          tipo_qualificacao_id: tipoQualificacao.id,
          nome: row['Qualificação'],
          codigo: row['Código'] || null,
          categoria: row.Categoria || null,
          data_conclusao: row['Data Conclusão'] || null,
          data_vencimento: row['Data Vencimento'] || null,
          instrutor: row.Instrutor || null,
          examinador: row.Examinador || null,
          observacoes: row['Observações'] || null,
          qualificacao_status: row.Status || 'CONCLUIDA',
        };

        if (existente) {
          // UPDATE
          await db
            .prepare(
              `UPDATE qualificacoes_historico SET
                nome = ?, codigo = ?, categoria = ?, data_conclusao = ?,
                data_vencimento = ?, instrutor = ?, examinador = ?,
                observacoes = ?, qualificacao_status = ?, updated_at = datetime('now')
              WHERE id = ?`,
            )
            .bind(
              campos.nome,
              campos.codigo,
              campos.categoria,
              campos.data_conclusao,
              campos.data_vencimento,
              campos.instrutor,
              campos.examinador,
              campos.observacoes,
              campos.qualificacao_status,
              existente.id,
            )
            .run();
          updated++;
        } else {
          // INSERT
          await db
            .prepare(
              `INSERT INTO qualificacoes_historico (
                funcionario_id, qualificacao_id, qualificacao_codigo, categoria,
                data_conclusao, data_vencimento, instrutor, observacoes, 
                created_at, updated_at
              ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))`,
            )
            .bind(
              campos.funcionario_id,
              campos.tipo_qualificacao_id, // Agora vai para qualificacao_id
              campos.codigo,
              campos.categoria,
              campos.data_conclusao,
              campos.data_vencimento,
              campos.instrutor,
              campos.observacoes,
            )
            .run();
          inserted++;
        }
      } catch (err: any) {
        errors.push({
          linha,
          erro: err.message || String(err),
          dados: row,
        });
      }
    }

    const result: ImportResult = {
      success: errors.length === 0,
      mode,
      totalRows: rows.length,
      inserted,
      updated,
      deleted: mode === 'substituir' ? deleted : undefined,
      errors,
    };

    return c.json(result);
  } catch (error: any) {
    console.error('[IMPORT XLSX HISTORICO] Erro:', error);
    return c.json({ success: false, error: error.message }, 500);
  }
});

