/**
 * SERVICE: Geração de PDF da Ficha de Treinamento
 * Stack: pdfkit + TypeScript
 * Output: PDF A4 comprimido (1 página)
 * Arquivo: worker-airtrust/src/services/pdf-ficha.service.ts
 */

import PDFDocument from 'pdfkit';

interface FichaPDFData {
  fichaId: string;
  sessao_titulo: string;
  tripulante_nome: string;
  tripulante_codigo_anac: string;
  tripulante_funcao: string;
  instrutor_nome: string;
  instrutor_codigo_anac: string;
  data: string;
  horario_inicio: string;
  horario_fim: string;
  simulador: string;
  carga_horaria_total: string;
  status: string;
  observacoes_gerais: string;
  assinatura_aluno_timestamp: string | null;
  assinatura_instrutor_timestamp: string | null;
  logoBytes?: Buffer; // Optional company logo for embedding in PDF
  manobras: Array<{
    ordem: number;
    descricao: string;
    codigo: string;
    resultado: number | null;
  }>;
}

export async function gerarPDFFicha(dados: FichaPDFData): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    try {
      const doc = new PDFDocument({
        size: 'A4',
        margin: 20,
        bufferPages: true,
      });

      const chunks: Buffer[] = [];

      doc.on('data', (chunk: Buffer) => chunks.push(chunk));
      doc.on('end', () => resolve(Buffer.concat(chunks)));
      doc.on('error', reject);

      // ========== CORES ==========
      const COLOR = {
        primary: '#2180B0',
        danger: '#C0152F',
        warning: '#A84B2F',
        success: '#208090',
        text: '#134252',
        textSecondary: '#626C7C',
        border: '#E0E4E8',
        bgLight: '#F5F7FA',
      };

      // ========== GEOMETRIA A4 ==========
      const pageWidth = doc.page.width;
      const pageHeight = doc.page.height;
      const margin = 20;
      const contentWidth = pageWidth - 2 * margin;

      let currentY = margin;

      // ========== LOGO (SE DISPONÍVEL) ==========
      if (dados.logoBytes) {
        try {
          // Embed logo in top-left corner
          const maxLogoHeight = 40; // Maximum logo height
          const maxLogoWidth = 120; // Maximum logo width

          doc.image(dados.logoBytes, margin, currentY, {
            fit: [maxLogoWidth, maxLogoHeight],
          });

          // Move Y position down after logo
          currentY += maxLogoHeight + 8;
        } catch (logoError) {
          console.warn('Erro ao embutir logo no PDF:', logoError);
          // Continue without logo if there's an error
        }
      }

      // ========== HEADER ==========
      doc.fontSize(10).font('Helvetica-Bold').fillColor(COLOR.text);
      doc.text('FICHA DE TREINAMENTO DE VOO', margin, currentY, {
        align: 'left',
        width: contentWidth * 0.7,
      });

      // Badge Status
      const statusText = dados.status === 'PENDENTE' ? 'PENDENTE' : 'ASSINADO';
      const statusColor = dados.status === 'PENDENTE' ? COLOR.danger : COLOR.success;
      doc
        .fontSize(9)
        .font('Helvetica-Bold')
        .fillColor('white')
        .rect(pageWidth - margin - 80, currentY, 80, 20)
        .fill(statusColor);
      doc.fillColor('white').text(statusText, pageWidth - margin - 80, currentY + 5, {
        width: 80,
        align: 'center',
        height: 20,
      });

      currentY += 18;

      // Subtítulo
      doc
        .fontSize(8)
        .font('Helvetica')
        .fillColor(COLOR.textSecondary)
        .text(dados.sessao_titulo, margin, currentY, {
          width: contentWidth,
        });

      currentY += 14;

      // ========== LINHA SEPARADORA ==========
      doc
        .moveTo(margin, currentY)
        .lineTo(pageWidth - margin, currentY)
        .strokeColor(COLOR.border)
        .lineWidth(0.5)
        .stroke();

      currentY += 8;

      // ========== DADOS DA SESSÃO (2 COLUNAS) ==========
      let yPos = currentY;

      // Coluna 1
      const col1X = margin;
      const col1Width = contentWidth * 0.48;

      doc
        .fontSize(7)
        .font('Helvetica-Bold')
        .fillColor(COLOR.textSecondary)
        .text('TRIPULANTE', col1X, yPos);
      doc
        .fontSize(8)
        .font('Helvetica')
        .fillColor(COLOR.text)
        .text(dados.tripulante_nome, col1X, yPos + 10, {
          width: col1Width,
        });
      doc
        .fontSize(7)
        .font('Helvetica')
        .fillColor(COLOR.textSecondary)
        .text(`ANAC: ${dados.tripulante_codigo_anac}`, col1X, yPos + 24);

      doc
        .fontSize(7)
        .font('Helvetica-Bold')
        .fillColor(COLOR.textSecondary)
        .text('INSTRUTOR', col1X, yPos + 35);
      doc
        .fontSize(8)
        .font('Helvetica')
        .fillColor(COLOR.text)
        .text(dados.instrutor_nome, col1X, yPos + 45, {
          width: col1Width,
        });
      doc
        .fontSize(7)
        .font('Helvetica')
        .fillColor(COLOR.textSecondary)
        .text(`ANAC: ${dados.instrutor_codigo_anac}`, col1X, yPos + 59);

      // Coluna 2
      const col2X = col1X + col1Width + 10;
      doc
        .fontSize(7)
        .font('Helvetica-Bold')
        .fillColor(COLOR.textSecondary)
        .text('DATA', col2X, yPos);
      doc
        .fontSize(8)
        .font('Helvetica')
        .fillColor(COLOR.text)
        .text(dados.data, col2X, yPos + 10);

      doc
        .fontSize(7)
        .font('Helvetica-Bold')
        .fillColor(COLOR.textSecondary)
        .text('HORÁRIOS', col2X, yPos + 25);
      doc
        .fontSize(8)
        .font('Helvetica')
        .fillColor(COLOR.text)
        .text(`${dados.horario_inicio} / ${dados.horario_fim}`, col2X, yPos + 35);

      doc
        .fontSize(7)
        .font('Helvetica-Bold')
        .fillColor(COLOR.textSecondary)
        .text('SIMULADOR', col2X, yPos + 50);
      doc
        .fontSize(8)
        .font('Helvetica')
        .fillColor(COLOR.text)
        .text(dados.simulador, col2X, yPos + 60, {
          width: col1Width,
        });

      yPos += 75;

      // ========== LINHA SEPARADORA ==========
      doc
        .moveTo(margin, yPos)
        .lineTo(pageWidth - margin, yPos)
        .strokeColor(COLOR.border)
        .lineWidth(0.5)
        .stroke();

      yPos += 8;

      // ========== MANOBRAS (2 COLUNAS) ==========
      doc
        .fontSize(7)
        .font('Helvetica-Bold')
        .fillColor(COLOR.text)
        .text('ITENS AVALIADOS', margin, yPos);

      yPos += 10;

      const manobraEsquerda = dados.manobras.filter((m) => m.ordem >= 1 && m.ordem <= 11);
      const manobraDireita = dados.manobras.filter((m) => m.ordem >= 12 && m.ordem <= 22);

      function renderManobraColuna(
        manobras: typeof dados.manobras,
        xStart: number,
        yStart: number,
        maxHeight: number,
      ): number {
        let y = yStart;
        const colWidth = contentWidth * 0.48;
        const maxY = yStart + maxHeight;

        manobras.forEach((manobra) => {
          if (y > maxY) return;

          // Número + Descrição
          doc
            .fontSize(6)
            .font('Helvetica-Bold')
            .fillColor(COLOR.text)
            .text(`${manobra.ordem}. ${manobra.descricao}`, xStart, y, {
              width: colWidth - 25,
            });

          // Código
          doc
            .fontSize(5)
            .font('Helvetica')
            .fillColor(COLOR.textSecondary)
            .text(manobra.codigo, xStart, y + 10, {
              width: colWidth - 25,
            });

          // Score Badge
          const scoreSize = 16;
          const scoreBg = getScoreBgColor(manobra.resultado);
          const scoreX = xStart + colWidth - scoreSize;

          doc.rect(scoreX, y, scoreSize, scoreSize).fill(scoreBg);

          if (manobra.resultado !== null) {
            doc
              .fontSize(9)
              .font('Helvetica-Bold')
              .fillColor('white')
              .text(manobra.resultado.toString(), scoreX, y + 3, {
                width: scoreSize,
                align: 'center',
              });
          }

          y += 18;
        });

        return y;
      }

      function getScoreBgColor(score: number | null): string {
        if (score === null) return COLOR.border;
        if (score >= 8) return COLOR.success;
        if (score >= 6) return COLOR.warning;
        return COLOR.danger;
      }

      // Renderizar colunas em paralelo
      const col1End = renderManobraColuna(manobraEsquerda, margin, yPos, 140);
      const col2End = renderManobraColuna(manobraDireita, col2X, yPos, 140);

      yPos = Math.max(col1End, col2End) + 5;

      // ========== OBSERVAÇÕES (MINI) ==========
      doc
        .fontSize(6)
        .font('Helvetica-Bold')
        .fillColor(COLOR.text)
        .text('OBSERVAÇÕES', margin, yPos);

      const obsHeight = 18;
      doc
        .rect(margin, yPos + 8, contentWidth, obsHeight)
        .fillAndStroke(COLOR.bgLight, COLOR.border);

      doc
        .fontSize(6)
        .font('Helvetica')
        .fillColor(COLOR.text)
        .text(dados.observacoes_gerais || '-', margin + 5, yPos + 10, {
          width: contentWidth - 10,
          height: obsHeight - 4,
          ellipsis: true,
        });

      yPos += obsHeight + 12;

      // ========== ASSINATURAS (MINI) ==========
      doc
        .fontSize(6)
        .font('Helvetica-Bold')
        .fillColor(COLOR.text)
        .text('ASSINATURAS', margin, yPos);

      yPos += 8;

      // Assinatura Tripulante
      const sigWidth = (contentWidth - 5) / 2;
      doc
        .fontSize(5)
        .font('Helvetica')
        .fillColor(COLOR.textSecondary)
        .text('Tripulante', margin, yPos);
      if (dados.assinatura_aluno_timestamp) {
        doc
          .fontSize(5)
          .fillColor(COLOR.success)
          .text(`✓ Assinado ${formatTime(dados.assinatura_aluno_timestamp)}`, margin, yPos + 8);
      } else {
        doc
          .fontSize(5)
          .fillColor(COLOR.warning)
          .text('Aguardando assinatura', margin, yPos + 8);
      }

      // Assinatura Instrutor
      doc
        .fontSize(5)
        .font('Helvetica')
        .fillColor(COLOR.textSecondary)
        .text('Instrutor', margin + sigWidth + 5, yPos);
      if (dados.assinatura_instrutor_timestamp) {
        doc
          .fontSize(5)
          .fillColor(COLOR.success)
          .text(
            `✓ Assinado ${formatTime(dados.assinatura_instrutor_timestamp)}`,
            margin + sigWidth + 5,
            yPos + 8,
          );
      } else {
        doc
          .fontSize(5)
          .fillColor(COLOR.warning)
          .text('Aguardando assinatura', margin + sigWidth + 5, yPos + 8);
      }

      // ========== FOOTER ==========
      const footerY = pageHeight - 30;
      doc
        .moveTo(margin, footerY)
        .lineTo(pageWidth - margin, footerY)
        .strokeColor(COLOR.border)
        .lineWidth(0.5)
        .stroke();

      doc
        .fontSize(6)
        .font('Helvetica')
        .fillColor(COLOR.textSecondary)
        .text(`Ficha ID: ${dados.fichaId}`, margin, footerY + 5, {
          width: contentWidth / 2,
        });

      doc
        .fontSize(6)
        .fillColor(COLOR.textSecondary)
        .text(
          `Gerado em: ${new Date().toLocaleString('pt-BR')}`,
          margin + contentWidth / 2,
          footerY + 5,
          {
            width: contentWidth / 2,
            align: 'right',
          },
        );

      doc.end();
    } catch (error) {
      reject(error);
    }
  });
}

function formatTime(timestamp: string): string {
  const date = new Date(timestamp);
  return date.toLocaleString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}
