app.post(
  '/historico/:id/certificados/upload',
  auth(),
  requireRole('admin', 'manager'),
  async (c) => {
    const db = c.env.DB;
    const bucket = c.env.BUCKET;
    const id = parseInt(c.req.param('id'));

    if (isNaN(id)) {
      return c.json({ success: false, error: 'ID inválido' }, 400);
    }

    try {
      const { historico, nomeFuncionario, cpf, codigo } = await resolveCertificadoContext(db, id);

      const form = await c.req.formData();
      const file = form.get('file') as File | null;
      const descricao = (form.get('descricao') as string) || null;
      const dataRealizacaoStr = (form.get('data_realizacao') as string) || null;

      if (!file) {
        return c.json({ success: false, error: 'Campo "file" é obrigatório' }, 400);
      }

      // ✅ NOVA VALIDAÇÃO: Tamanho máximo (10MB)
      const MAX_SIZE = 10 * 1024 * 1024;
      if (file.size > MAX_SIZE) {
        return c.json(
          {
            success: false,
            error: `Arquivo muito grande. Máximo: 10MB (enviado: ${(
              file.size /
              1024 /
              1024
            ).toFixed(2)}MB)`,
          },
          400,
        );
      }

      // ✅ NOVA VALIDAÇÃO: Tamanho mínimo (evitar vazios)
      if (file.size < 1024) {
        return c.json({ success: false, error: 'Arquivo muito pequeno (mínimo: 1KB)' }, 400);
      }

      // ✅ NOVA VALIDAÇÃO: Magic bytes do PDF
      const arrayBuffer = await file.arrayBuffer();
      const header = new Uint8Array(arrayBuffer.slice(0, 5));
      const isPDF =
        header[0] === 0x25 && // %
        header[1] === 0x50 && // P
        header[2] === 0x44 && // D
        header[3] === 0x46 && // F
        header[4] === 0x2d; // -

      if (!isPDF) {
        return c.json(
          {
            success: false,
            error: 'Arquivo inválido. Não é um PDF real (magic bytes inválidos)',
          },
          400,
        );
      }

      // Data de realização: usa data_realizacao se fornecida, senão fallback
      let dataRealização: Date;
      if (dataRealizacaoStr) {
        dataRealização = new Date(dataRealizacaoStr);
      } else if (historico.data_conclusao) {
        dataRealização = new Date(historico.data_conclusao);
      } else if (historico.data_vencimento) {
        dataRealização = new Date(historico.data_vencimento);
      } else {
        return c.json(
          {
            success: false,
            error:
              'Impossível fazer upload: qualificação não possui data de conclusão ou vencimento.',
          },
          400,
        );
      }

      const uuid = crypto.randomUUID().substring(0, 8);

      // Usar nomenclatura padronizada
      const nomeArquivo = gerarNomeArquivoPadronizado({
        tipo: 'CERTIFICADO_QUALIFICACAO',
        nomeFuncionario: nomeFuncionario,
        cpf,
        data: dataRealização,
        codigo,
        uuid,
      });

      console.log('[UPLOAD CERT] Gerando certificado:', {
        historicoId: id,
        cpf,
        codigo,
        nomeArquivoGerado: nomeArquivo,
      });

      const r2Key = `certificados/${nomeArquivo}`;
      const uint8Array = new Uint8Array(arrayBuffer);
      const fileType = file.type || 'application/pdf';

      // Calcular hash SHA-256
      const hashBuffer = await crypto.subtle.digest('SHA-256', uint8Array);
      const hashArray = Array.from(new Uint8Array(hashBuffer));
      const hash = hashArray.map((b) => b.toString(16).padStart(2, '0')).join('');

      await bucket.put(r2Key, uint8Array, {
        httpMetadata: {
          contentType: fileType,
        },
        customMetadata: {
          tipo: 'CERTIFICADO_QUALIFICACAO',
          cpf,
          codigo,
          historico_id: String(historico.id),
          data_referencia: dataRealização.toISOString(),
          origem: 'upload_manual',
          hash_sha256: hash,
        },
      });

      const result = await db
        .prepare(
          `INSERT INTO documentos (
           uuid, funcionario_id, nome_arquivo, tipo, tamanho, r2_key,
           descricao, created_at, updated_at
         ) VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))`,
        )
        .bind(
          uuid,
          historico.funcionario_id,
          nomeArquivo,
          fileType,
          uint8Array.byteLength,
          r2Key,
          descricao ||
            `Certificado anexado para qualificação ${codigo} em ${
              dataRealização.toISOString().split('T')[0]
            }`,
        )
        .run();

      const documentoId = result.meta.last_row_id;
      console.log(`✅ [UPLOAD CERT] Certificado salvo: ID ${documentoId}`);

      // ✅ INSERIR na pasta_virtual para exibir na UI
      try {
        await db
          .prepare(
            `INSERT INTO pasta_virtual (
              funcionario_id, documento_id, tipo_documento, categoria, 
              caminho_arquivo, nome_arquivo, dataupload, descricao, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, datetime('now'), ?, datetime('now'))`,
          )
          .bind(
            historico.funcionario_id,
            documentoId,
            'CERTIFICADO',
            'Certificados de Qualificação',
            r2Key,
            nomeArquivo,
            `Certificado ${codigo} - ${nomeFuncionario}`,
          )
          .run();
        console.log('✅ [UPLOAD CERT] Certificado inserido na pasta_virtual');
      } catch (e) {
        console.error('❌ [UPLOAD CERT] Erro ao inserir na pasta_virtual:', e);
        // Não falhar o processo todo por isso
      }

      // ✅ LINK certificado_arquivo_id ao historico
      await db
        .prepare(
          `UPDATE qualificacoes_historico 
           SET certificado_arquivo_id = ?, updated_at = datetime('now')
           WHERE id = ?`,
        )
        .bind(documentoId, id)
        .run();

      console.log(`✅ [UPLOAD CERT] Linked documento ${documentoId} to historico ${id}`);

      const response: ApiResponse<{ id: number; uuid: string; r2_key: string }> = {
        success: true,
        data: {
          id: documentoId,
          uuid,
          r2_key: r2Key,
        },
        message: 'Certificado anexado com sucesso',
      };

      return c.json(response, 201);
    } catch (error) {
      console.error('[UPLOAD CERT] Erro:', error);
      return c.json(
        {
          success: false,
          error: 'Erro ao fazer upload do certificado',
          details: error instanceof Error ? error.message : 'Erro desconhecido',
        },
        500,
      );
    }
  },
);

app.delete('/historico/:id/certificados/:certId', auth(), async (c) => {
  const db = c.env.DB;
  const bucket = c.env.BUCKET;
  const certId = parseInt(c.req.param('certId'));

  if (isNaN(certId)) {
    return c.json({ success: false, error: 'ID de certificado inválido' }, 400);
  }

  try {
    const documento = await db
      .prepare('SELECT * FROM documentos WHERE id = ? AND deleted_at IS NULL')
      .bind(certId)
      .first<Documento>();

    if (!documento) {
      console.warn(`[DELETE CERT] Certificado ID ${certId} não encontrado`);
      return c.json({ success: false, error: 'Certificado não encontrado' }, 404);
    }

    // GAP #8: Mover para pasta "deleted/" antes de soft delete
    const oldKey = documento.r2_key;
    const newKey = oldKey.replace('certificados/', 'certificados/deleted/');

    console.log(`🗑️  [SOFT DELETE CASCATA] Movendo: ${oldKey} → ${newKey}`);

    try {
      // Copiar para pasta deleted
      const existingObj = await bucket.get(oldKey);
      if (existingObj) {
        await bucket.put(newKey, existingObj.body, {
          httpMetadata: existingObj.httpMetadata,
          customMetadata: {
            ...(existingObj.customMetadata || {}),
            deleted_at: new Date().toISOString(),
            original_key: oldKey,
          },
        });

        // Deletar arquivo original
        await bucket.delete(oldKey);
        console.log(`✅ [SOFT DELETE] Arquivo movido para ${newKey}`);
      } else {
        console.warn(
          `⚠️  [SOFT DELETE] Arquivo ${oldKey} não encontrado no R2, apenas marcando no D1`,
        );
      }
    } catch (r2Error) {
      console.error('❌ [SOFT DELETE] Erro ao mover arquivo no R2:', r2Error);
      // Continua mesmo se R2 falhar (soft delete no D1 é mais importante)
    }

    // EXCLUSÃO EM CASCATA:
    // 1. Soft delete na tabela documentos
    await db
      .prepare(
        "UPDATE documentos SET deleted_at = datetime('now') WHERE id = ? AND deleted_at IS NULL",
      )
      .bind(certId)
      .run();

    // 2. Remover de pasta_virtual (se existir)
    console.log(`🗑️  [CASCATA] Verificando pasta_virtual para documento ID ${certId}...`);
    const pastaVirtualResult = await db
      .prepare(
        "UPDATE pasta_virtual SET deleted_at = datetime('now') WHERE documento_id = ? AND deleted_at IS NULL",
      )
      .bind(certId)
      .run();

    if (pastaVirtualResult.meta.changes > 0) {
      console.log(
        `✅ [CASCATA] ${pastaVirtualResult.meta.changes} registro(s) removido(s) de pasta_virtual`,
      );
    }

    // 3. Limpar referência em qualificacoes_historico (SET NULL, não deletar o histórico)
    console.log(
      `🗑️  [CASCATA] Limpando referência de certificado_arquivo_id em qualificacoes_historico...`,
    );
    const historicoResult = await db
      .prepare(
        'UPDATE qualificacoes_historico SET certificado_arquivo_id = NULL WHERE certificado_arquivo_id = ? AND deleted_at IS NULL',
      )
      .bind(certId)
      .run();

    if (historicoResult.meta.changes > 0) {
      console.log(
        `✅ [CASCATA] ${historicoResult.meta.changes} registro(s) atualizado(s) em qualificacoes_historico`,
      );
    }

    console.log(
      `✅ [DELETE CERT] Certificado ID ${certId} removido com sucesso (cascata completa)`,
    );

    const response: ApiResponse = {
      success: true,
      message: 'Certificado removido com sucesso (exclusão em cascata)',
    };

    return c.json(response);
  } catch (error) {
    console.error('[DELETE CERT] Erro:', error);
    return c.json(
      {
        success: false,
        error: 'Erro ao remover certificado',
        details: error instanceof Error ? error.message : 'Erro desconhecido',
      },
      500,
    );
  }
});

